INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C1','math',6,2,'u1',2,'나누는 수가 분수인 나눗셈의 뜻 — 같은 종류의 양을 얼마씩 몇 번 덜어 낼 수 있는지 묻는 자리임을 알고, (자연수)÷(자연수)·(분수)÷(자연수)를 바탕으로 식을 세우기',ARRAY['6수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C2','math',6,2,'u1',2,'분모가 같은 (분수)÷(분수) — 두 분수가 같은 단위분수 몇 개인지 세어 분자끼리 나누고, 분모는 답에 남지 않음을 알기',ARRAY['6수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C3','math',6,2,'u1',3,'분모가 같은 (분수)÷(분수) — 분자끼리 나누어떨어지지 않으면 몫을 분수로 나타내고, 몫의 분수 부분은 남은 양이 아니라 한 몫의 얼마인지를 뜻함을 알기',ARRAY['6수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C4','math',6,2,'u1',4,'분모가 다른 (분수)÷(분수) — 두 분수를 같은 크기의 조각으로 다시 세는 통분을 한 뒤 분자끼리 나누기',ARRAY['6수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C5','math',6,2,'u1',5,'(자연수)÷(단위분수) — 단위분수가 1 안에 분모만큼 들어감을 알고 자연수에 분모를 곱해 구하며, 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커짐을 알기',ARRAY['6수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C6','math',6,2,'u1',6,'(자연수)÷(진분수) — 분자로 나누고 분모를 곱하는 두 걸음을 한 줄로 적어 나누는 분수의 분모와 분자를 바꾸어 곱하기',ARRAY['6수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C7','math',6,2,'u1',7,'(분수)÷(분수)를 분수의 곱셈으로 — 나누는 분수만 분모와 분자를 바꾸어 곱하고, 나누어지는 분수는 그대로 두어야 함을 알기',ARRAY['6수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C8','math',6,2,'u1',8,'대분수의 나눗셈 — 대분수를 먼저 가분수로 고친 뒤 통분해 분자끼리 나누거나 곱셈으로 바꾸어 계산하기(두 길의 답은 같다)',ARRAY['6수01-10']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u1-C9','math',6,2,'u1',9,'문제 해결 — 길이 ÷ 타일 한 변으로 가로·세로에 들어가는 개수를 구하고, 가로 수 × 세로 수로 필요한 타일 수를 구하기(조건을 바꾸어도 방법은 같다)',ARRAY['6수01-10']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X01','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C6','M6-2-u1-C7']::text[],'나눗셈식을 거꾸로 세운다 — 나누어지는 양과 나누는 양을 바꾸어 (나누는 양)÷(나누어지는 양)으로 쓴다','「무엇을 얼마씩」 — 무엇이 앞, 얼마씩이 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X02','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3']::text[],'분모가 같은 나눗셈에서 분모를 답에 남기거나 분모끼리도 나눈다(⟨3/4⟩ ÷ ⟨1/4⟩ = ⟨3/4⟩, 분모끼리 4 ÷ 4)','같은 조각이면 개수만 — 분모는 답에 안 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X03','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C5','M6-2-u1-C6']::text[],'나눗셈 대신 분자끼리 빼거나 더한다(연산을 바꾼다)','「몇 번 덜어 낼 수 있나」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X04','math',6,'u1',ARRAY['M6-2-u1-C3']::text[],'몫의 분수 부분을 「남은 양」으로 읽는다(⟨5/6⟩ ÷ ⟨2/6⟩ = 2⟨1/2⟩에서 ⟨1/2⟩이 남았다고 본다)','몫은 컵의 수 — 분수 부분은 컵 하나의 얼마') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X05','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'나누어떨어지지 않을 때 몫을 거꾸로 적는다(4 ÷ 7을 ⟨7/4⟩로)','나누어지는 수가 분자, 나누는 수가 분모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X06','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'분모가 다른데 통분하지 않고 분자끼리 바로 나눈다','조각 크기가 다르면 먼저 같은 조각으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X07','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'통분을 한쪽만 하거나 분모만 바꾸고 분자를 그대로 둔다','분모를 바꾼 만큼 분자도 같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X08','math',6,'u1',ARRAY['M6-2-u1-C5']::text[],'(자연수)÷(단위분수)에서 분모로 나누거나 분모만 답으로 쓴다(5 ÷ ⟨1/3⟩ = ⟨5/3⟩)','⟨1/3⟩은 1 안에 3번 — 분모를 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X09','math',6,'u1',ARRAY['M6-2-u1-C5','M6-2-u1-C6']::text[],'「나눗셈을 하면 몫은 늘 작아진다」고 여겨 몫이 커지는 것을 틀렸다고 본다','1보다 작은 수로 나누면 몫이 커져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X10','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C9']::text[],'나누는 분수를 뒤집지 않고 그대로 곱한다(4 ÷ ⟨2/3⟩ = 4 × ⟨2/3⟩)','나누는 분수의 분모와 분자를 바꾸어 곱해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X11','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C9']::text[],'두 걸음의 순서를 거꾸로 한다 — 분모로 나누고 분자를 곱한다','분자로 나누고(÷2) 분모를 곱해요(×3)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X12','math',6,'u1',ARRAY['M6-2-u1-C7','M6-2-u1-C8']::text[],'두 분수를 다 뒤집거나 앞 분수를 뒤집는다(또는 아무것도 안 뒤집고 곱한다)','뒤집는 것은 나누는 분수 하나뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X13','math',6,'u1',ARRAY['M6-2-u1-C8','M6-2-u1-C9']::text[],'대분수를 가분수로 고치지 않고 자연수 부분과 분수 부분을 따로 나누거나 대분수 그대로 뒤집는다','대분수는 먼저 가분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X14','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 분모를 곱하지 않는다)','자연수 × 분모 + 분자가 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X15','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'계산 마무리 실수 — 약분하지 않거나 가분수·대분수로 잘못 고친다','몫은 약분해서 대분수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X16','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7']::text[],'몫을 견줄 때 나누는 수가 클수록 몫도 크다고 여긴다','나누는 수가 작을수록 몫이 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X17','math',6,'u1',ARRAY['M6-2-u1-C9']::text[],'가로에 들어가는 수와 세로에 들어가는 수를 더해 전체 타일 수로 본다(곱해야 한다)','가로 줄이 세로 줄 수만큼 늘어선 것 — 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X18','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C5','M6-2-u1-C9']::text[],'무엇을 묻는지 놓친다 — 개수를 묻는데 양을 쓰거나 나누어지는 양을 그대로 답으로 쓴다','묻는 것이 「몇 개」인지 「얼마」인지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X19','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'어떤 수 문제에서 거꾸로 계산을 잘못한다 — 곱한 결과를 다시 곱하거나 결과를 그대로 어떤 수로 본다','곱했으면 거꾸로 나누어 어떤 수를 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u1-X20','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C8','M6-2-u1-C9']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 큰↔작은, 가능↔불가능','물음의 「잘못·가장·없는」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#1','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],true,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"복숭아잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 들어가는 작은 유리병에 나누어 담으려고 해요. 필요한 병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨3/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈으로 구해요.","나누어지는 양 ⟨3/5⟩이 앞, 얼마씩인 ⟨1/5⟩이 뒤 — ⟨3/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1,"label":"⟨3/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"끈 ⟨4/5⟩ m로 한 장에 ⟨1/5⟩ m씩 쓰는 편지를 꾸며요. 꾸밀 수 있는 편지 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨4/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/5⟩ + ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩ m에서 ⟨1/5⟩ m씩 덜어 내는 거예요.","몇 번 덜어 낼 수 있는지는 나눗셈이에요.","⟨4/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1,"label":"⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내기"}]}},{"stem":"물 ⟨8/9⟩ L를 한 컵에 ⟨2/9⟩ L씩 나누어 담아요. 필요한 컵의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨8/9⟩ ÷ ⟨2/9⟩","correct":true},{"t":"⟨2/9⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X01"},{"t":"⟨8/9⟩ × ⟨2/9⟩","mis":"M6-2-u1-X03"},{"t":"⟨8/9⟩ − ⟨2/9⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨8/9⟩ L에서 ⟨2/9⟩ L씩 덜어 내요.","같은 양을 몇 번 덜어 낼 수 있는지 — 나눗셈이에요.","⟨8/9⟩ ÷ ⟨2/9⟩예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2,"label":"⟨8/9⟩에서 ⟨2/9⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#2','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'mc','auto','⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":2,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?","explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨1/4⟩은 ⟨1/4⟩이 1개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 3 ÷ 1 = 3.","분모 4는 답에 남지 않아요. 몫은 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"3","correct":true},{"t":"⟨3/4⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"},{"t":"2","mis":"M6-2-u1-X03"}],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨3/4⟩에서 ⟨1/4⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#3','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',1,'sa','auto','⟨12/13⟩ ÷ ⟨3/13⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"sa","stem":"⟨12/13⟩ ÷ ⟨3/13⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개, ⟨3/13⟩은 ⟨1/13⟩이 3개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 12 ÷ 3 = 4.","분모 13은 답에 남지 않아요. 몫은 4예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#4','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',1,'mc','auto','⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03']::text[],true,'{"seq":4,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"⟨2/9⟩는 ⟨1/9⟩이 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"9개","mis":"M6-2-u1-X02"},{"t":"7개","mis":"M6-2-u1-X03"},{"t":"18개","mis":"M6-2-u1-X02"}],"explanation":["⟨2/9⟩는 ⟨1/9⟩ 조각을 2개 모은 수예요.","분모 9는 조각의 크기, 분자 2는 조각의 개수예요.","그래서 ⟨1/9⟩이 2개예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":2,"grp":1}]},"variant_rule":{"alt":[{"stem":"⟨3/5⟩은 ⟨1/5⟩이 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"5개","mis":"M6-2-u1-X02"},{"t":"2개","mis":"M6-2-u1-X03"},{"t":"15개","mis":"M6-2-u1-X02"}],"explanation":["⟨3/5⟩은 ⟨1/5⟩ 조각 3개예요.","분자가 조각의 개수예요.","⟨1/5⟩이 3개예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1}]}},{"stem":"⟨7/10⟩은 ⟨1/10⟩이 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"10개","mis":"M6-2-u1-X02"},{"t":"3개","mis":"M6-2-u1-X03"},{"t":"70개","mis":"M6-2-u1-X02"}],"explanation":["⟨7/10⟩은 ⟨1/10⟩ 조각 7개예요.","분자가 조각의 개수예요.","⟨1/10⟩이 7개예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":7,"grp":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#5','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'sa','auto','색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.","explanation":["⟨10/20⟩을 ⟨2/20⟩씩 나누는 식은 ⟨10/20⟩ ÷ ⟨2/20⟩예요.","분모가 같으니 분자끼리 나눠요 — 10 ÷ 2 = 5.","친구는 5명 필요해요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["5","5명"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#6','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'ox','auto','⟨6/7⟩ ÷ ⟨2/7⟩ = ⟨3/7⟩이에요.',ARRAY['M6-2-u1-X02']::text[],false,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":2,"kind":"ox","stem":"⟨6/7⟩ ÷ ⟨2/7⟩ = ⟨3/7⟩이에요.","answer":"X","reason_options":[{"t":"같은 조각의 개수끼리 나누는 것이라 6 ÷ 2 = 3, 분모는 답에 남지 않아서","correct":true},{"t":"분자끼리 나누고 분모는 그대로 두어야 해서","mis":"M6-2-u1-X02"}],"mis":"M6-2-u1-X02","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","같은 크기의 조각이니 6 ÷ 2 = 3이에요.","몫은 3 — 분모 7은 답에 남지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":6,"grp":2,"label":"⟨6/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#7','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C2","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨8/9⟩ ÷ ⟨2/9⟩","r":"4"},{"l":"⟨9/10⟩ ÷ ⟨3/10⟩","r":"3"},{"l":"⟨10/11⟩ ÷ ⟨5/11⟩","r":"2"}],"mis":"M6-2-u1-X02","explanation":["분모가 같으면 분자끼리 나눠요.","8 ÷ 2 = 4, 9 ÷ 3 = 3, 10 ÷ 5 = 2예요.","분모는 몫에 남지 않아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨6/7⟩ ÷ ⟨3/7⟩","r":"2"},{"l":"⟨12/13⟩ ÷ ⟨2/13⟩","r":"6"},{"l":"⟨15/16⟩ ÷ ⟨3/16⟩","r":"5"}],"explanation":["분자끼리 나눠요.","6 ÷ 3 = 2, 12 ÷ 2 = 6, 15 ÷ 3 = 5예요.","분모는 몫에 남지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#8','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C1',2,'mc','auto','6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3의 몫은 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X10','M6-2-u1-X02']::text[],true,'{"seq":8,"concept":"M6-2-u1-C1","difficulty":2,"kind":"mc","stem":"6학년 1학기에 배운 (분수)÷(자연수)예요. ⟨6/7⟩ ÷ 3의 몫은 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨6/21⟩","mis":"M6-2-u1-X03"},{"t":"⟨18/7⟩","mis":"M6-2-u1-X10"},{"t":"2","mis":"M6-2-u1-X02"}],"explanation":["분자 6을 3으로 나눌 수 있어요 — 6 ÷ 3 = 2.","분모는 그대로 7이에요.","그래서 ⟨6/7⟩ ÷ 3 = ⟨2/7⟩예요."],"variant_rule":{"alt":[{"stem":"6학년 1학기에 배운 (자연수)÷(자연수)예요. 4 ÷ 5의 몫을 분수로 나타내면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨5/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/5⟩","mis":"M6-2-u1-X05"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["나누어지는 수가 분자, 나누는 수가 분모예요.","4 ÷ 5 = ⟨4/5⟩예요.","⟨5/4⟩로 거꾸로 적지 않도록 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#9','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',2,'mc','auto','⟨14/15⟩ ÷ ⟨7/15⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":2,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨7/15⟩의 몫은 얼마인가요?","explanation":["⟨14/15⟩는 ⟨1/15⟩이 14개, ⟨7/15⟩은 ⟨1/15⟩이 7개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 14 ÷ 7 = 2.","분모 15는 답에 남지 않아요. 몫은 2예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"2","correct":true},{"t":"⟨2/15⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/2⟩","mis":"M6-2-u1-X05"},{"t":"7","mis":"M6-2-u1-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_basic#10','math',6,2,'u1','L02','g6_2_math_u1_L02_basic','lesson_basic','M6-2-u1-C2',3,'mc','auto','⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":10,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 14 ÷ □예요.","14를 나누어떨어지게 하는 수를 찾아요.","14 ÷ 2 = 7이라 □는 2예요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"2","correct":true},{"t":"11","mis":"M6-2-u1-X02"},{"t":"5","mis":"M6-2-u1-X02"},{"t":"12","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#1','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',2,'sa','auto','끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 쓰려고 해요. 편지는 몇 장 꾸밀 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 쓰려고 해요. 편지는 몇 장 꾸밀 수 있나요? 숫자로 쓰세요.","explanation":["⟨4/5⟩를 ⟨1/5⟩씩 나누는 식은 ⟨4/5⟩ ÷ ⟨1/5⟩이에요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 1 = 4.","편지는 4장 꾸밀 수 있어요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["4","4장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#2','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',2,'error','auto','잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 병에 담는 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X20']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"error","stem":"잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 병에 담는 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「나누는 수가 분수니까 나눗셈이 아니라 곱셈으로 풀어야 해.」","correct":true,"mis_target":"M6-2-u1-X03"},{"t":"도윤 — 「구슬 6개를 2개씩 담는 것과 똑같은 물음이야.」","mis":"M6-2-u1-X20"},{"t":"하린 — 「⟨3/5⟩은 ⟨1/5⟩이 3개니까 병은 3개야.」","mis":"M6-2-u1-X20"}],"explanation":["같은 양을 몇 번 덜어 낼 수 있는지 묻는 것은 늘 나눗셈이에요.","단위가 분수로 바뀌었을 뿐 묻는 방식은 6 ÷ 2와 같아요.","수아는 나누는 수가 분수라고 연산을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#3','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 9 ÷ □예요.","9를 나누어떨어지게 하는 수를 찾아요.","9 ÷ 3 = 3이라 □는 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"3","correct":true},{"t":"7","mis":"M6-2-u1-X02"},{"t":"2","mis":"M6-2-u1-X02"},{"t":"6","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#4','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["분모가 같으니 분자끼리 나누어 몫을 구해요.","⟨10/11⟩ ÷ ⟨9/11⟩ = ⟨1 1/9⟩, ⟨5/6⟩ ÷ ⟨4/6⟩ = ⟨1 1/4⟩, ⟨8/9⟩ ÷ ⟨5/9⟩ = ⟨1 3/5⟩, ⟨8/9⟩ ÷ ⟨7/9⟩ = ⟨1 1/7⟩이에요.","가장 큰 몫은 ⟨8/9⟩ ÷ ⟨5/9⟩예요."],"variant_rule":{"fd":{"ask":"cmp","kind":"same"}},"options":[{"t":"⟨8/9⟩ ÷ ⟨5/9⟩","correct":true},{"t":"⟨5/6⟩ ÷ ⟨4/6⟩","mis":"M6-2-u1-X16"},{"t":"⟨8/9⟩ ÷ ⟨7/9⟩","mis":"M6-2-u1-X16"},{"t":"⟨10/11⟩ ÷ ⟨9/11⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#5','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',3,'mc','auto','끈 ⟨8/9⟩ m로 한 장에 ⟨2/9⟩ m씩 쓰는 편지를 꾸며요. 다음 중 꾸밀 수 있는 편지 수를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],false,'{"seq":5,"concept":"M6-2-u1-C1","difficulty":3,"kind":"mc","stem":"끈 ⟨8/9⟩ m로 한 장에 ⟨2/9⟩ m씩 쓰는 편지를 꾸며요. 다음 중 꾸밀 수 있는 편지 수를 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"⟨8/9⟩ − ⟨2/9⟩를 계산한다","correct":true},{"t":"⟨8/9⟩에서 ⟨2/9⟩를 몇 번 덜어 낼 수 있는지 센다","mis":"M6-2-u1-X20"},{"t":"⟨8/9⟩ ÷ ⟨2/9⟩를 계산한다","mis":"M6-2-u1-X20"},{"t":"⟨1/9⟩이 8개인 것을 ⟨1/9⟩ 2개씩 묶어 본다","mis":"M6-2-u1-X20"}],"explanation":["몇 장인지는 ⟨8/9⟩에서 ⟨2/9⟩를 몇 번 덜어 내는지 세는 거예요.","덜어 내기 · 나눗셈 · 조각 묶기는 모두 같은 생각이에요.","뺄셈 ⟨8/9⟩ − ⟨2/9⟩는 한 번 덜어 내고 남은 양일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#6','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 3이 되게 하려면 □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X02','M6-2-u1-X19']::text[],true,'{"seq":6,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 3이 되게 하려면 □에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M6-2-u1-X03"},{"t":"2","mis":"M6-2-u1-X02"},{"t":"27","mis":"M6-2-u1-X19"}],"explanation":["분모가 같으니 몫은 9 ÷ □예요.","9 ÷ □ = 3이 되는 □는 3이에요.","⟨9/11⟩ ÷ ⟨3/11⟩ = 3이에요."],"variant_rule":{"alt":[{"stem":"⟨10/13⟩ ÷ ⟨□/13⟩의 몫이 5가 되게 하려면 □에 알맞은 수는 얼마인가요?","options":[{"t":"2","correct":true},{"t":"5","mis":"M6-2-u1-X03"},{"t":"50","mis":"M6-2-u1-X19"},{"t":"8","mis":"M6-2-u1-X02"}],"explanation":["몫은 10 ÷ □예요.","10 ÷ □ = 5이면 □ = 2예요.","⟨10/13⟩ ÷ ⟨2/13⟩ = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#7','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',3,'mc','auto','분모가 모두 13인 분수 ⟨12/13⟩ · ⟨3/13⟩ · ⟨4/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":7,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"분모가 모두 13인 분수 ⟨12/13⟩ · ⟨3/13⟩ · ⟨4/13⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?","explanation":["가장 큰 분수는 ⟨12/13⟩, 가장 작은 분수는 ⟨3/13⟩이에요.","분모가 같으니 분자끼리 나눠요 — 12 ÷ 3 = 4.","그래서 몫은 4예요."],"variant_rule":{"fd":{"ask":"maxmin"}},"options":[{"t":"4","correct":true},{"t":"⟨1/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨9/13⟩","mis":"M6-2-u1-X03"},{"t":"⟨12/39⟩","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#8','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C1',4,'essay','teacher','구슬 6개를 2개씩 담으면 6 ÷ 2 = 3봉지예요. 잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 담는 것도 왜 나눗셈으로 풀 수 있는지, 두 상황의 같은 점을 들어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C1","difficulty":4,"kind":"essay","stem":"구슬 6개를 2개씩 담으면 6 ÷ 2 = 3봉지예요. 잼 ⟨3/5⟩ kg을 ⟨1/5⟩ kg씩 담는 것도 왜 나눗셈으로 풀 수 있는지, 두 상황의 같은 점을 들어 설명해 보세요.","answer_guide":{"answer":"예: 두 상황 모두 「전체를 같은 양씩 덜어 내면 몇 번(몇 개) 되는가」를 묻는다. 구슬은 2개씩, 잼은 ⟨1/5⟩ kg씩 덜어 낸다는 단위만 다를 뿐 묻는 방식이 같으므로 ⟨3/5⟩ ÷ ⟨1/5⟩ = 3으로 나눗셈이 된다.","scoring_points":["같은 양씩 덜어 내는 횟수를 묻는다는 공통점을 썼는가","단위만 다르다는 점을 밝혔는가","⟨3/5⟩ ÷ ⟨1/5⟩ = 3을 식으로 썼는가"]},"explanation":["두 상황 모두 같은 양씩 몇 번 덜어 내는지 물어요.","덜어 내는 단위가 2개에서 ⟨1/5⟩ kg으로 바뀌었을 뿐이에요.","그래서 ⟨3/5⟩ ÷ ⟨1/5⟩ = 3으로 나눗셈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#9','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',4,'essay','teacher','⟨9/10⟩ ÷ ⟨3/10⟩을 계산하면 몫은 3이에요. 몫에 분모 10이 남지 않는 까닭을 ⟨1/10⟩ 조각의 개수를 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C2","difficulty":4,"kind":"essay","stem":"⟨9/10⟩ ÷ ⟨3/10⟩을 계산하면 몫은 3이에요. 몫에 분모 10이 남지 않는 까닭을 ⟨1/10⟩ 조각의 개수를 들어 설명해 보세요.","answer_guide":{"answer":"예: ⟨9/10⟩는 ⟨1/10⟩ 조각 9개이고 ⟨3/10⟩은 ⟨1/10⟩ 조각 3개이다. 조각의 크기가 같으니 조각의 개수만 견주면 되어 9 ÷ 3 = 3이다. 분모 10은 조각의 크기를 나타낼 뿐 개수를 세는 데는 쓰이지 않으므로 답에 남지 않는다.","scoring_points":["두 분수를 ⟨1/10⟩ 조각의 개수로 바꾸었는가","9 ÷ 3 = 3을 썼는가","분모는 조각 크기라 답에 남지 않음을 설명했는가"]},"explanation":["⟨9/10⟩는 ⟨1/10⟩이 9개, ⟨3/10⟩은 ⟨1/10⟩이 3개예요.","같은 조각이라 개수끼리 9 ÷ 3 = 3이에요.","분모 10은 조각 크기일 뿐이라 답에 남지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L02_challenge#10','math',6,2,'u1','L02','g6_2_math_u1_L02_challenge','lesson_challenge','M6-2-u1-C2',4,'mc','auto','⟨8/15⟩ ÷ ⟨□/15⟩의 몫이 4이고, ⟨12/15⟩ ÷ ⟨□/15⟩의 몫이 6이에요. 두 식의 □는 같은 수예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X03']::text[],true,'{"seq":10,"concept":"M6-2-u1-C2","difficulty":4,"kind":"mc","stem":"⟨8/15⟩ ÷ ⟨□/15⟩의 몫이 4이고, ⟨12/15⟩ ÷ ⟨□/15⟩의 몫이 6이에요. 두 식의 □는 같은 수예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"2","correct":true},{"t":"4","mis":"M6-2-u1-X02"},{"t":"3","mis":"M6-2-u1-X02"},{"t":"1","mis":"M6-2-u1-X03"}],"explanation":["첫 식에서 8 ÷ □ = 4니 □ = 2예요.","둘째 식에서도 12 ÷ 2 = 6으로 맞아요.","그래서 □는 2예요."],"variant_rule":{"alt":[{"stem":"⟨9/14⟩ ÷ ⟨□/14⟩의 몫이 3이고, ⟨12/14⟩ ÷ ⟨□/14⟩의 몫이 4예요. 두 식의 □는 같은 수예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M6-2-u1-X02"},{"t":"6","mis":"M6-2-u1-X02"},{"t":"2","mis":"M6-2-u1-X03"}],"explanation":["9 ÷ □ = 3이니 □ = 3이에요.","12 ÷ 3 = 4로 둘째 식도 맞아요.","□는 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#1','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨3/10⟩ ÷ ⟨7/10⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":1,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3/10⟩ ÷ ⟨7/10⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 3 ÷ 7.","나누어떨어지지 않으면 몫을 분수로 적어요 — 3 ÷ 7 = ⟨3/7⟩.","몫 ⟨3/7⟩은 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X05"},{"t":"⟨4/10⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/70⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":10,"num":3,"grp":7,"label":"⟨3/10⟩에서 ⟨7/10⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#2','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'sa','auto','⟨3/10⟩ ÷ ⟨7/10⟩의 몫을 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨3/10⟩ ÷ ⟨7/10⟩의 몫을 가분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","explanation":["분자끼리 나누면 3 ÷ 7 = ⟨3/7⟩이에요.","더 약분할 수 없어요.","분자는 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"num"}},"answer":["3"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#3','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨4/13⟩ ÷ ⟨11/13⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":3,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨4/13⟩ ÷ ⟨11/13⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 4 ÷ 11.","나누어떨어지지 않으면 몫을 분수로 적어요 — 4 ÷ 11 = ⟨4/11⟩.","몫 ⟨4/11⟩는 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨4/11⟩","correct":true},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨7/13⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/143⟩","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#4','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',1,'mc','auto','⟨5/7⟩ ÷ ⟨4/7⟩의 몫을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":4,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨5/7⟩ ÷ ⟨4/7⟩의 몫을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1 1/4⟩","correct":true},{"t":"⟨4/5⟩","mis":"M6-2-u1-X05"},{"t":"⟨1/7⟩","mis":"M6-2-u1-X03"},{"t":"⟨5/28⟩","mis":"M6-2-u1-X02"}],"explanation":["분모가 같으니 분자끼리 나눠요 — 5 ÷ 4.","나누어떨어지지 않으니 몫을 ⟨5/4⟩로 적어요.","가분수 ⟨5/4⟩를 대분수로 고치면 ⟨1 1/4⟩이에요."],"asset":{"type":"fbar","bars":[{"den":7,"num":5,"grp":4,"label":"⟨5/7⟩에서 ⟨4/7⟩씩 덜어 내기"}]},"variant_rule":{"alt":[{"stem":"⟨7/9⟩ ÷ ⟨5/9⟩의 몫을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨1 2/5⟩","correct":true},{"t":"⟨5/7⟩","mis":"M6-2-u1-X05"},{"t":"⟨2/9⟩","mis":"M6-2-u1-X03"},{"t":"⟨7/45⟩","mis":"M6-2-u1-X02"}],"explanation":["분자끼리 나눠요 — 7 ÷ 5.","몫은 ⟨7/5⟩이에요.","대분수로 고치면 ⟨1 2/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":7,"grp":5,"label":"⟨7/9⟩에서 ⟨5/9⟩씩 덜어 내기"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#5','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'sa','auto','⟨5/7⟩ ÷ ⟨2/7⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨5/7⟩ ÷ ⟨2/7⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.","explanation":["분자끼리 나누면 5 ÷ 2 = ⟨5/2⟩예요.","더 약분할 수 없어요.","분자와 분모의 합은 7이에요."],"variant_rule":{"fd":{"ask":"same","form":"sum"}},"answer":["7"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#6','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'ox','auto','친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우면 ⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩컵이에요. 여기서 ⟨1/2⟩은 비료가 ⟨1/2⟩ L 남았다는 뜻이에요.',ARRAY['M6-2-u1-X04']::text[],false,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":2,"kind":"ox","stem":"친환경 비료 ⟨5/6⟩ L를 ⟨2/6⟩ L짜리 컵에 나누어 채우면 ⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩컵이에요. 여기서 ⟨1/2⟩은 비료가 ⟨1/2⟩ L 남았다는 뜻이에요.","answer":"X","reason_options":[{"t":"몫은 컵의 수를 세는 자리라 ⟨1/2⟩은 컵 하나의 절반을 채운다는 뜻이어서","correct":true},{"t":"남은 비료는 ⟨1/6⟩ L이지 ⟨1/2⟩ L가 아니어서","mis":"M6-2-u1-X04"}],"mis":"M6-2-u1-X04","explanation":["가득 찬 컵이 2컵이고 ⟨1/6⟩ L가 남아요.","남은 ⟨1/6⟩ L는 ⟨2/6⟩ L 컵의 절반을 채워요.","그래서 ⟨1/2⟩은 남은 양이 아니라 컵 하나의 절반이라는 뜻이에요."],"asset":{"type":"fbar","bars":[{"den":6,"num":5,"grp":2,"label":"⟨5/6⟩에서 ⟨2/6⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#7','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨4/9⟩ ÷ ⟨7/9⟩","r":"⟨4/7⟩"},{"l":"⟨7/9⟩ ÷ ⟨4/9⟩","r":"⟨1 3/4⟩"},{"l":"⟨8/9⟩ ÷ ⟨2/9⟩","r":"4"}],"mis":"M6-2-u1-X05","explanation":["분모가 같으면 분자끼리 나눠요.","4 ÷ 7 = ⟨4/7⟩, 7 ÷ 4 = ⟨7/4⟩ = ⟨1 3/4⟩이에요.","8 ÷ 2 = 4예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"⟨3/11⟩ ÷ ⟨5/11⟩","r":"⟨3/5⟩"},{"l":"⟨5/11⟩ ÷ ⟨3/11⟩","r":"⟨1 2/3⟩"},{"l":"⟨10/11⟩ ÷ ⟨5/11⟩","r":"2"}],"explanation":["분자끼리 나눠요.","3 ÷ 5 = ⟨3/5⟩, 5 ÷ 3 = ⟨1 2/3⟩예요.","10 ÷ 5 = 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#8','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'mc','auto','⟨5/7⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":2,"kind":"mc","stem":"⟨5/7⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 5 ÷ 2.","나누어떨어지지 않으면 몫을 분수로 적어요 — 5 ÷ 2 = ⟨5/2⟩ = ⟨2 1/2⟩.","몫 ⟨2 1/2⟩은 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-2-u1-X05"},{"t":"⟨3/7⟩","mis":"M6-2-u1-X03"},{"t":"⟨5/14⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":7,"num":5,"grp":2,"label":"⟨5/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#9','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',2,'mc','auto','연주는 물 ⟨13/15⟩ L, 진우는 물 ⟨8/15⟩ L를 마셨어요. 연주가 마신 양은 진우가 마신 양의 몇 배인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X18']::text[],true,'{"seq":9,"concept":"M6-2-u1-C3","difficulty":2,"kind":"mc","stem":"연주는 물 ⟨13/15⟩ L, 진우는 물 ⟨8/15⟩ L를 마셨어요. 연주가 마신 양은 진우가 마신 양의 몇 배인가요?","options":[{"t":"⟨1 5/8⟩배","correct":true},{"t":"⟨8/13⟩배","mis":"M6-2-u1-X05"},{"t":"⟨5/15⟩배","mis":"M6-2-u1-X03"},{"t":"⟨13/15⟩배","mis":"M6-2-u1-X18"}],"explanation":["몇 배인지는 ⟨13/15⟩ ÷ ⟨8/15⟩로 구해요.","분모가 같으니 13 ÷ 8 = ⟨13/8⟩이에요.","대분수로 고치면 ⟨1 5/8⟩배예요."],"variant_rule":{"alt":[{"stem":"빨간 끈은 ⟨11/12⟩ m, 파란 끈은 ⟨7/12⟩ m예요. 빨간 끈의 길이는 파란 끈의 몇 배인가요?","options":[{"t":"⟨1 4/7⟩배","correct":true},{"t":"⟨7/11⟩배","mis":"M6-2-u1-X05"},{"t":"⟨4/12⟩배","mis":"M6-2-u1-X03"},{"t":"⟨11/12⟩배","mis":"M6-2-u1-X18"}],"explanation":["⟨11/12⟩ ÷ ⟨7/12⟩로 구해요.","11 ÷ 7 = ⟨11/7⟩이에요.","대분수로 ⟨1 4/7⟩배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_basic#10','math',6,2,'u1','L03','g6_2_math_u1_L03_basic','lesson_basic','M6-2-u1-C3',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":10,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["분모가 같으니 분자끼리 나누어 몫을 구해요.","⟨4/10⟩ ÷ ⟨1/10⟩ = 4, ⟨7/13⟩ ÷ ⟨1/13⟩ = 7, ⟨9/13⟩ ÷ ⟨3/13⟩ = 3, ⟨2/7⟩ ÷ ⟨1/7⟩ = 2예요.","가장 큰 몫은 ⟨7/13⟩ ÷ ⟨1/13⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"same"}},"options":[{"t":"⟨7/13⟩ ÷ ⟨1/13⟩","correct":true},{"t":"⟨4/10⟩ ÷ ⟨1/10⟩","mis":"M6-2-u1-X16"},{"t":"⟨9/13⟩ ÷ ⟨3/13⟩","mis":"M6-2-u1-X16"},{"t":"⟨2/7⟩ ÷ ⟨1/7⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#1','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',2,'mc','auto','⟨7/12⟩ ÷ ⟨5/12⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":1,"concept":"M6-2-u1-C3","difficulty":2,"kind":"mc","stem":"⟨7/12⟩ ÷ ⟨5/12⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 7 ÷ 5.","나누어떨어지지 않으면 몫을 분수로 적어요 — 7 ÷ 5 = ⟨7/5⟩ = ⟨1 2/5⟩.","몫 ⟨1 2/5⟩는 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨1 2/5⟩","correct":true},{"t":"⟨5/7⟩","mis":"M6-2-u1-X05"},{"t":"⟨2/12⟩","mis":"M6-2-u1-X03"},{"t":"⟨7/60⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":12,"num":7,"grp":5,"label":"⟨7/12⟩에서 ⟨5/12⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
