INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#2','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',2,'sa','auto','⟨5/6⟩ ÷ ⟨4/9⟩를 통분해 계산할 때 몫 ⟨□/8⟩의 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":2,"kind":"sa","stem":"⟨5/6⟩ ÷ ⟨4/9⟩를 통분해 계산할 때 몫 ⟨□/8⟩의 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","explanation":["공통분모 18로 통분하면 ⟨15/18⟩ ÷ ⟨8/18⟩이에요.","분자끼리 나누면 15 ÷ 8 = ⟨15/8⟩예요.","분자에 오는 수는 15예요."],"variant_rule":{"fd":{"ask":"diff","form":"num"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#3','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'error','auto','⟨8/9⟩ ÷ ⟨5/8⟩를 통분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X07','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C4","difficulty":3,"kind":"error","stem":"⟨8/9⟩ ÷ ⟨5/8⟩를 통분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「⟨8/72⟩ ÷ ⟨45/72⟩로 고치면 돼.」","correct":true,"mis_target":"M6-2-u1-X07"},{"t":"채윤 — 「9와 8의 최소공배수 72를 공통분모로 해.」","mis":"M6-2-u1-X20"},{"t":"태오 — 「⟨64/72⟩ ÷ ⟨45/72⟩로 고치면 돼.」","mis":"M6-2-u1-X20"}],"explanation":["공통분모는 72예요.","⟨8/9⟩은 분모가 8배 커졌으니 분자도 8배 — ⟨64/72⟩예요.","예준이는 분모만 바꾸고 분자 8을 그대로 두었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#4','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":4,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["분모가 다르니 통분한 뒤 분자끼리 나누어 몫을 구해요.","⟨6/7⟩ ÷ ⟨1/5⟩ = ⟨4 2/7⟩, ⟨3/7⟩ ÷ ⟨1/3⟩ = ⟨1 2/7⟩, ⟨3/4⟩ ÷ ⟨2/3⟩ = ⟨1 1/8⟩, ⟨1/4⟩ ÷ ⟨5/8⟩ = ⟨2/5⟩예요.","가장 큰 몫은 ⟨6/7⟩ ÷ ⟨1/5⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"diff"}},"options":[{"t":"⟨6/7⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨3/7⟩ ÷ ⟨1/3⟩","mis":"M6-2-u1-X16"},{"t":"⟨3/4⟩ ÷ ⟨2/3⟩","mis":"M6-2-u1-X16"},{"t":"⟨1/4⟩ ÷ ⟨5/8⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#5','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','⟨7/8⟩, ⟨3/4⟩, ⟨2/3⟩ 가운데 가장 큰 수를 가장 작은 수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X15','M6-2-u1-X20']::text[],true,'{"seq":5,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"⟨7/8⟩, ⟨3/4⟩, ⟨2/3⟩ 가운데 가장 큰 수를 가장 작은 수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨1 5/16⟩","correct":true},{"t":"⟨1 3/16⟩","mis":"M6-2-u1-X15"},{"t":"⟨1 1/4⟩","mis":"M6-2-u1-X20"},{"t":"⟨2 1/16⟩","mis":"M6-2-u1-X15"}],"explanation":["가장 큰 수는 ⟨7/8⟩, 가장 작은 수는 ⟨2/3⟩예요.","통분하면 ⟨21/24⟩ ÷ ⟨16/24⟩ = 21 ÷ 16이에요.","⟨21/16⟩ = ⟨1 5/16⟩예요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩, ⟨2/3⟩, ⟨3/5⟩ 가운데 가장 큰 수를 가장 작은 수로 나눈 몫은 얼마인가요?","options":[{"t":"⟨1 7/18⟩","correct":true},{"t":"⟨1 1/4⟩","mis":"M6-2-u1-X20"},{"t":"⟨1 5/18⟩","mis":"M6-2-u1-X15"},{"t":"⟨1 1/9⟩","mis":"M6-2-u1-X20"}],"explanation":["가장 큰 수 ⟨5/6⟩, 가장 작은 수 ⟨3/5⟩이에요.","⟨25/30⟩ ÷ ⟨18/30⟩ = 25 ÷ 18이에요.","⟨25/18⟩ = ⟨1 7/18⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#6','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','물 양은 ⟨5/6⟩ L, 주스 양은 ⟨5/9⟩ L예요. 물 양은 주스 양의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":6,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"물 양은 ⟨5/6⟩ L, 주스 양은 ⟨5/9⟩ L예요. 물 양은 주스 양의 몇 배인가요?","explanation":["몇 배인지는 ⟨5/6⟩ ÷ ⟨5/9⟩로 구해요.","통분하면 ⟨15/18⟩ ÷ ⟨10/18⟩ = 15 ÷ 10이에요.","그래서 ⟨1 1/2⟩배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"⟨1 1/2⟩배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨2/3⟩배","mis":"M6-2-u1-X05"},{"t":"⟨25/54⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#7','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',3,'mc','auto','⟨5/12⟩ ÷ ⟨7/18⟩을 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":7,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"⟨5/12⟩ ÷ ⟨7/18⟩을 통분한 것은 어느 것인가요?","explanation":["12와 18의 최소공배수 36을 공통분모로 해요.","⟨5/12⟩는 ⟨15/36⟩, ⟨7/18⟩은 ⟨14/36⟩가 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨15/36⟩ ÷ ⟨14/36⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨15/36⟩ ÷ ⟨14/36⟩","correct":true},{"t":"⟨5/36⟩ ÷ ⟨7/36⟩","mis":"M6-2-u1-X07"},{"t":"⟨15/36⟩ ÷ ⟨7/18⟩","mis":"M6-2-u1-X07"},{"t":"⟨5/12⟩ ÷ ⟨14/36⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#8','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',4,'essay','teacher','⟨3/4⟩ ÷ ⟨2/5⟩를 통분해서 계산하는 과정을 두 걸음으로 쓰고, 왜 통분부터 해야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C4","difficulty":4,"kind":"essay","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 통분해서 계산하는 과정을 두 걸음으로 쓰고, 왜 통분부터 해야 하는지 설명해 보세요.","answer_guide":{"answer":"예: ① 분모 4와 5의 최소공배수 20으로 통분한다 — ⟨15/20⟩ ÷ ⟨8/20⟩. ② 분자끼리 나눈다 — 15 ÷ 8 = ⟨15/8⟩ = ⟨1 7/8⟩. 분모가 다르면 두 분수가 센 조각의 크기가 달라 개수끼리 견줄 수 없으므로 같은 조각으로 다시 세는 통분을 먼저 한다.","scoring_points":["통분한 식 ⟨15/20⟩ ÷ ⟨8/20⟩을 썼는가","몫 ⟨1 7/8⟩을 바르게 구했는가","조각 크기를 같게 하려고 통분한다는 까닭을 썼는가"]},"explanation":["4와 5의 최소공배수 20으로 통분해요.","⟨15/20⟩ ÷ ⟨8/20⟩ = 15 ÷ 8 = ⟨1 7/8⟩이에요.","조각 크기가 같아야 개수끼리 나눌 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#9','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',4,'essay','teacher','지민이는 ⟨2/5⟩ ÷ ⟨3/8⟩을 분자끼리 바로 나누어 ⟨2/3⟩이라고 답했어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":4,"kind":"essay","stem":"지민이는 ⟨2/5⟩ ÷ ⟨3/8⟩을 분자끼리 바로 나누어 ⟨2/3⟩이라고 답했어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: ⟨2/5⟩와 ⟨3/8⟩은 분모가 달라 조각의 크기가 다르므로 분자끼리 바로 나누면 안 된다. 40으로 통분하면 ⟨16/40⟩ ÷ ⟨15/40⟩ = 16 ÷ 15 = ⟨1 1/15⟩이다.","scoring_points":["분모가 달라 바로 나눌 수 없음을 지적했는가","⟨16/40⟩ ÷ ⟨15/40⟩로 통분했는가","몫 ⟨1 1/15⟩을 구했는가"]},"explanation":["분모가 다르면 조각의 크기가 달라요.","40으로 통분하면 ⟨16/40⟩ ÷ ⟨15/40⟩예요.","16 ÷ 15 = ⟨1 1/15⟩이 바른 몫이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_challenge#10','math',6,2,'u1','L04','g6_2_math_u1_L04_challenge','lesson_challenge','M6-2-u1-C4',4,'mc','auto','어떤 수를 ⟨2/3⟩로 나누었더니 몫이 ⟨3/4⟩이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19','M6-2-u1-X03']::text[],true,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨2/3⟩로 나누었더니 몫이 ⟨3/4⟩이 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1 1/8⟩","mis":"M6-2-u1-X19"},{"t":"⟨8/9⟩","mis":"M6-2-u1-X19"},{"t":"⟨1/12⟩","mis":"M6-2-u1-X03"}],"explanation":["어떤 수를 □라 하면 □ ÷ ⟨2/3⟩ = ⟨3/4⟩이에요.","나눗셈은 곱셈으로 되돌릴 수 있어요 — □ = ⟨3/4⟩ × ⟨2/3⟩.","⟨3/4⟩ × ⟨2/3⟩ = ⟨6/12⟩ = ⟨1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 ⟨3/5⟩으로 나누었더니 몫이 ⟨5/6⟩가 되었어요. 어떤 수는 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1 7/18⟩","mis":"M6-2-u1-X19"},{"t":"⟨1 1/5⟩","mis":"M6-2-u1-X19"},{"t":"⟨7/30⟩","mis":"M6-2-u1-X03"}],"explanation":["□ ÷ ⟨3/5⟩ = ⟨5/6⟩예요.","□ = ⟨5/6⟩ × ⟨3/5⟩이에요.","⟨15/30⟩ = ⟨1/2⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#1','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'mc','auto','5 ÷ ⟨1/3⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X08','M6-2-u1-X03']::text[],true,'{"seq":1,"concept":"M6-2-u1-C5","difficulty":1,"kind":"mc","stem":"5 ÷ ⟨1/3⟩의 몫은 얼마인가요?","explanation":["⟨1/3⟩은 1 안에 3번 들어가요.","5 안에는 3번씩 5개 — 5 × 3이에요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 15예요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"options":[{"t":"15","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X08"},{"t":"8","mis":"M6-2-u1-X03"},{"t":"3","mis":"M6-2-u1-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#2','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'sa','auto','4 ÷ ⟨1/2⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"4 ÷ ⟨1/2⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/2⟩은 1 안에 2번 들어가요.","4 안에는 2번씩 4개 — 4 × 2예요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 8이에요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["8"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#3','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'mc','auto','(자연수)÷(단위분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X08','M6-2-u1-X10','M6-2-u1-X03']::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":1,"kind":"mc","stem":"(자연수)÷(단위분수)를 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자연수에 단위분수의 분모를 곱한다","correct":true},{"t":"자연수를 단위분수의 분모로 나눈다","mis":"M6-2-u1-X08"},{"t":"자연수에 단위분수의 분자를 곱한다","mis":"M6-2-u1-X10"},{"t":"자연수에서 단위분수의 분모를 뺀다","mis":"M6-2-u1-X03"}],"explanation":["⟨1/3⟩은 1 안에 3번 들어가요.","5 안에는 3번씩 5개 — 5 × 3이에요.","그래서 자연수에 단위분수의 분모를 곱해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#4','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',1,'sa','auto','6 ÷ ⟨1/5⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"6 ÷ ⟨1/5⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/5⟩은 1 안에 5번 들어가요.","6 안에는 5번씩 6개 — 6 × 5예요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 30이에요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["30"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#5','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'ox','auto','5 ÷ ⟨1/3⟩ = 15는 잘못된 계산이에요. 나눗셈을 하면 몫은 늘 나누어지는 수보다 작아져야 하기 때문이에요.',ARRAY['M6-2-u1-X09']::text[],false,'{"seq":5,"concept":"M6-2-u1-C5","difficulty":2,"kind":"ox","stem":"5 ÷ ⟨1/3⟩ = 15는 잘못된 계산이에요. 나눗셈을 하면 몫은 늘 나누어지는 수보다 작아져야 하기 때문이에요.","answer":"X","reason_options":[{"t":"⟨1/3⟩은 1보다 작아서 5 안에 여러 번 들어가므로 몫이 5보다 커질 수 있어서","correct":true},{"t":"나눗셈이 아니라 곱셈 5 × 3을 한 것이어서","mis":"M6-2-u1-X09"}],"mis":"M6-2-u1-X09","explanation":["⟨1/3⟩은 1 안에 3번 들어가는 작은 수예요.","5 안에는 15번 들어가니 5 ÷ ⟨1/3⟩ = 15가 맞아요.","1보다 작은 수로 나누면 몫은 더 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#6','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'sa','auto','물 3 L를 한 컵에 ⟨1/5⟩ L씩 나누어 담으면 컵은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"물 3 L를 한 컵에 ⟨1/5⟩ L씩 나누어 담으면 컵은 몇 개 필요한가요? 숫자로 쓰세요.","explanation":["3 L를 ⟨1/5⟩ L씩 나누는 식은 3 ÷ ⟨1/5⟩이에요.","3 ÷ ⟨1/5⟩ = 3 × 5 = 15예요.","컵은 15개 필요해요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["15","15개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#7','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C5","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"4 ÷ ⟨1/2⟩","r":"8"},{"l":"6 ÷ ⟨1/5⟩","r":"30"},{"l":"11 ÷ ⟨1/4⟩","r":"44"}],"mis":"M6-2-u1-X08","explanation":["(자연수)÷(단위분수)는 분모를 곱해요.","4 × 2 = 8, 6 × 5 = 30, 11 × 4 = 44예요.","나누는 단위분수의 분모가 그대로 곱해져요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"3 ÷ ⟨1/6⟩","r":"18"},{"l":"7 ÷ ⟨1/3⟩","r":"21"},{"l":"9 ÷ ⟨1/5⟩","r":"45"}],"explanation":["분모를 곱해요.","3 × 6 = 18, 7 × 3 = 21, 9 × 5 = 45예요.","단위분수의 분모가 그대로 곱해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#8','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'mc','auto','11 ÷ ⟨1/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X08','M6-2-u1-X03']::text[],true,'{"seq":8,"concept":"M6-2-u1-C5","difficulty":2,"kind":"mc","stem":"11 ÷ ⟨1/4⟩의 몫은 얼마인가요?","explanation":["⟨1/4⟩은 1 안에 4번 들어가요.","11 안에는 4번씩 11개 — 11 × 4예요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 44예요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"options":[{"t":"44","correct":true},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X08"},{"t":"15","mis":"M6-2-u1-X03"},{"t":"4","mis":"M6-2-u1-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#9','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',2,'sa','auto','로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 1시간 동안에는 몇 L를 만들 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 1시간 동안에는 몇 L를 만들 수 있나요? 숫자로 쓰세요.","explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15예요.","그래서 1시간 동안에는 15 L예요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["15","15L"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_basic#10','math',6,2,'u1','L05','g6_2_math_u1_L05_basic','lesson_basic','M6-2-u1-C5',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":10,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["(자연수)÷(단위분수)는 분모를 곱해요 — 분모가 클수록 몫이 커요.","7 ÷ ⟨1/4⟩ = 28, 2 ÷ ⟨1/2⟩ = 4, 3 ÷ ⟨1/8⟩ = 24, 6 ÷ ⟨1/9⟩ = 54예요.","가장 큰 몫은 6 ÷ ⟨1/9⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"nunit"}},"options":[{"t":"6 ÷ ⟨1/9⟩","correct":true},{"t":"7 ÷ ⟨1/4⟩","mis":"M6-2-u1-X16"},{"t":"3 ÷ ⟨1/8⟩","mis":"M6-2-u1-X16"},{"t":"2 ÷ ⟨1/2⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#1','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',2,'sa','auto','걸어서 8 km를 가는 데 ⟨1/4⟩시간이 걸렸어요. 1시간 동안에는 몇 km를 갈 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"걸어서 8 km를 가는 데 ⟨1/4⟩시간이 걸렸어요. 1시간 동안에는 몇 km를 갈 수 있나요? 숫자로 쓰세요.","explanation":["1시간은 ⟨1/4⟩시간의 4배예요.","8 ÷ ⟨1/4⟩ = 8 × 4 = 32예요.","그래서 1시간 동안에는 32 km예요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["32","32km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#2','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',2,'sa','auto','12 ÷ ⟨1/8⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C5","difficulty":2,"kind":"sa","stem":"12 ÷ ⟨1/8⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/8⟩은 1 안에 8번 들어가요.","12 안에는 8번씩 12개 — 12 × 8이에요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 96이에요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["96"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#3','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'error','auto','7 ÷ ⟨1/3⟩과 7 ÷ ⟨1/6⟩의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X16','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C5","difficulty":3,"kind":"error","stem":"7 ÷ ⟨1/3⟩과 7 ÷ ⟨1/6⟩의 몫을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「⟨1/6⟩이 ⟨1/3⟩보다 작으니까 7 ÷ ⟨1/6⟩의 몫이 더 작아.」","correct":true,"mis_target":"M6-2-u1-X16"},{"t":"지호 — 「7 ÷ ⟨1/3⟩ = 21, 7 ÷ ⟨1/6⟩ = 42야.」","mis":"M6-2-u1-X20"},{"t":"소율 — 「⟨1/6⟩은 7 안에 더 여러 번 들어가니까 몫이 더 커.」","mis":"M6-2-u1-X20"}],"explanation":["7 ÷ ⟨1/3⟩ = 7 × 3 = 21, 7 ÷ ⟨1/6⟩ = 7 × 6 = 42예요.","나누는 수가 작을수록 7 안에 더 여러 번 들어가 몫이 커요.","유나는 나누는 수가 작으면 몫도 작다고 거꾸로 생각했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#4','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','몫이 가장 작은 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":4,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"몫이 가장 작은 것은 어느 것인가요?","explanation":["(자연수)÷(단위분수)는 분모를 곱해요 — 분모가 클수록 몫이 커요.","8 ÷ ⟨1/9⟩ = 72, 8 ÷ ⟨1/2⟩ = 16, 9 ÷ ⟨1/6⟩ = 54, 5 ÷ ⟨1/7⟩ = 35예요.","가장 작은 몫은 8 ÷ ⟨1/2⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"nunit"}},"options":[{"t":"8 ÷ ⟨1/2⟩","correct":true},{"t":"5 ÷ ⟨1/7⟩","mis":"M6-2-u1-X16"},{"t":"9 ÷ ⟨1/6⟩","mis":"M6-2-u1-X16"},{"t":"8 ÷ ⟨1/9⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#5','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','다음 설명 중 잘못된 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],false,'{"seq":5,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"다음 설명 중 잘못된 것은 어느 것인가요?","options":[{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아진다","correct":true},{"t":"5 ÷ ⟨1/3⟩ = 15이다","mis":"M6-2-u1-X20"},{"t":"1보다 작은 수로 나누면 몫이 더 커질 수 있다","mis":"M6-2-u1-X20"},{"t":"(자연수)÷(단위분수)는 분모를 곱해 구한다","mis":"M6-2-u1-X20"}],"explanation":["⟨1/3⟩은 1보다 작아 5 안에 15번 들어가요.","그래서 5 ÷ ⟨1/3⟩ = 15 — 몫이 5보다 커요.","「나눗셈을 하면 작아진다」는 자연수로 나눌 때 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#6','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','5 ÷ ⟨1/3⟩의 몫이 5보다 커지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u1-X09','M6-2-u1-X08']::text[],false,'{"seq":6,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"5 ÷ ⟨1/3⟩의 몫이 5보다 커지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨1/3⟩은 1보다 작은 수라 5 안에 여러 번 들어가기 때문에","correct":true},{"t":"나눗셈 대신 곱셈을 했기 때문에","mis":"M6-2-u1-X09"},{"t":"분모 3이 5보다 작기 때문에","mis":"M6-2-u1-X08"},{"t":"단위분수는 늘 몫을 작게 만들기 때문에","mis":"M6-2-u1-X09"}],"explanation":["1은 ⟨1/3⟩이 3개예요.","5는 ⟨1/3⟩이 15개 — 5 안에 ⟨1/3⟩이 15번 들어가요.","작은 수로 나누면 그만큼 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#7','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',3,'mc','auto','□ ÷ ⟨1/4⟩ = 36이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X19','M6-2-u1-X03']::text[],true,'{"seq":7,"concept":"M6-2-u1-C5","difficulty":3,"kind":"mc","stem":"□ ÷ ⟨1/4⟩ = 36이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"9","correct":true},{"t":"144","mis":"M6-2-u1-X19"},{"t":"40","mis":"M6-2-u1-X03"},{"t":"32","mis":"M6-2-u1-X03"}],"explanation":["□ ÷ ⟨1/4⟩ = □ × 4예요.","□ × 4 = 36이니 □ = 36 ÷ 4예요.","그래서 □는 9예요."],"variant_rule":{"alt":[{"stem":"□ ÷ ⟨1/6⟩ = 42예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"252","mis":"M6-2-u1-X19"},{"t":"48","mis":"M6-2-u1-X03"},{"t":"36","mis":"M6-2-u1-X03"}],"explanation":["□ ÷ ⟨1/6⟩ = □ × 6이에요.","□ × 6 = 42예요.","□ = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#8','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',4,'essay','teacher','로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸려요. 1시간 동안 만들 수 있는 주스의 양을 구하는 식을 세우고, 그 몫이 5 L보다 커지는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C5","difficulty":4,"kind":"essay","stem":"로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸려요. 1시간 동안 만들 수 있는 주스의 양을 구하는 식을 세우고, 그 몫이 5 L보다 커지는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 5 ÷ ⟨1/3⟩ = 5 × 3 = 15 L. 1시간은 ⟨1/3⟩시간의 3배이므로 5 L를 3배 하면 된다. ⟨1/3⟩은 1보다 작은 수라 작은 수로 나누면 그 수가 1 안에 여러 번 들어가므로 몫이 나누어지는 수보다 커진다.","scoring_points":["5 ÷ ⟨1/3⟩ = 15를 썼는가","1시간이 ⟨1/3⟩시간의 3배임을 밝혔는가","1보다 작은 수로 나누면 몫이 커지는 까닭을 썼는가"]},"explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15 L예요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#9','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',4,'essay','teacher','4 ÷ ⟨1/2⟩ = 8, 6 ÷ ⟨1/5⟩ = 30, 11 ÷ ⟨1/4⟩ = 44예요. 세 식에서 찾을 수 있는 공통된 계산 규칙을 쓰고, 그 규칙이 성립하는 까닭을 ⟨1/2⟩이 1 안에 몇 번 들어가는지를 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C5","difficulty":4,"kind":"essay","stem":"4 ÷ ⟨1/2⟩ = 8, 6 ÷ ⟨1/5⟩ = 30, 11 ÷ ⟨1/4⟩ = 44예요. 세 식에서 찾을 수 있는 공통된 계산 규칙을 쓰고, 그 규칙이 성립하는 까닭을 ⟨1/2⟩이 1 안에 몇 번 들어가는지를 들어 설명해 보세요.","answer_guide":{"answer":"예: 자연수에 단위분수의 분모를 곱하면 몫이 된다(4 × 2, 6 × 5, 11 × 4). ⟨1/2⟩은 1 안에 2번 들어가므로 4 안에는 2번씩 4개, 곧 4 × 2 = 8번 들어간다. 그래서 분모를 곱한 것이 몫이 된다.","scoring_points":["분모를 곱한다는 규칙을 썼는가","⟨1/2⟩이 1 안에 2번 들어감을 설명했는가","4 × 2 = 8번 들어간다고 까닭을 밝혔는가"]},"explanation":["세 식 모두 자연수 × 분모예요.","⟨1/2⟩은 1 안에 2번, 4 안에는 8번 들어가요.","그래서 분모를 곱하면 몫이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L05_challenge#10','math',6,2,'u1','L05','g6_2_math_u1_L05_challenge','lesson_challenge','M6-2-u1-C5',4,'mc','auto','□ ÷ ⟨1/△⟩ = 48이에요. □와 △가 모두 한 자리 자연수일 때, (□, △)가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u1-X20','M6-2-u1-X08']::text[],true,'{"seq":10,"concept":"M6-2-u1-C5","difficulty":4,"kind":"mc","stem":"□ ÷ ⟨1/△⟩ = 48이에요. □와 △가 모두 한 자리 자연수일 때, (□, △)가 될 수 있는 것은 어느 것인가요?","options":[{"t":"(8, 6)","correct":true},{"t":"(4, 12)","mis":"M6-2-u1-X20"},{"t":"(48, 1)","mis":"M6-2-u1-X20"},{"t":"(6, 9)","mis":"M6-2-u1-X08"}],"explanation":["□ ÷ ⟨1/△⟩ = □ × △ = 48이에요.","한 자리 수끼리 곱해 48이 되는 짝은 6 × 8, 8 × 6뿐이에요.","(8, 6)은 8 × 6 = 48로 맞아요."],"variant_rule":{"alt":[{"stem":"□ ÷ ⟨1/△⟩ = 35예요. □와 △가 모두 한 자리 자연수일 때, (□, △)가 될 수 있는 것은 어느 것인가요?","options":[{"t":"(7, 5)","correct":true},{"t":"(35, 1)","mis":"M6-2-u1-X20"},{"t":"(5, 6)","mis":"M6-2-u1-X08"},{"t":"(3, 12)","mis":"M6-2-u1-X20"}],"explanation":["□ × △ = 35예요.","한 자리 수 짝은 5 × 7, 7 × 5예요.","(7, 5)가 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#1','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'mc','auto','4 ÷ ⟨2/3⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":1,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"4 ÷ ⟨2/3⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 4 × ⟨3/2⟩.","4 × 3 = 12, 12 ÷ 2 = 6이에요.","그래서 몫은 6이에요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans"}},"options":[{"t":"6","correct":true},{"t":"⟨2 2/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨2/3⟩","mis":"M6-2-u1-X11"},{"t":"8","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#2','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'sa','auto','7 ÷ ⟨7/9⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C6","difficulty":1,"kind":"sa","stem":"7 ÷ ⟨7/9⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 7 × ⟨9/7⟩.","7 × 9 = 63, 63 ÷ 7 = 9예요.","그래서 몫은 9예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans"}},"answer":["9"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#3','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'mc','auto','4 ÷ ⟨2/3⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X01']::text[],true,'{"seq":3,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"4 ÷ ⟨2/3⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["4 ÷ ⟨2/3⟩는 4를 2로 나누고 3을 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨3/2⟩을 곱하는 것과 같아요.","나누는 분수의 분모와 분자를 바꾸어 곱해요 — 4 × ⟨3/2⟩."],"variant_rule":{"fd":{"ask":"nfrac","form":"expr"}},"options":[{"t":"4 × ⟨3/2⟩","correct":true},{"t":"4 × ⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"4 ÷ 3 × 2","mis":"M6-2-u1-X11"},{"t":"⟨3/2⟩ ÷ 4","mis":"M6-2-u1-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#4','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',1,'mc','auto','자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간에 갈 수 있는 거리를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X10','M6-2-u1-X03']::text[],true,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간에 갈 수 있는 거리를 구하는 식은 어느 것인가요?","options":[{"t":"4 ÷ ⟨2/3⟩","correct":true},{"t":"⟨2/3⟩ ÷ 4","mis":"M6-2-u1-X01"},{"t":"4 × ⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"4 − ⟨2/3⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨2/3⟩시간에 4 km — 1시간에 갈 거리를 찾아요.","⟨2/3⟩에 해당하는 양이 4니 1에 해당하는 양은 4 ÷ ⟨2/3⟩예요.","거리가 앞, 시간이 뒤예요."],"variant_rule":{"alt":[{"stem":"수도꼭지에서 물 6 L를 받는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 받을 수 있는 물의 양을 구하는 식은 어느 것인가요?","options":[{"t":"6 ÷ ⟨3/4⟩","correct":true},{"t":"⟨3/4⟩ ÷ 6","mis":"M6-2-u1-X01"},{"t":"6 × ⟨3/4⟩","mis":"M6-2-u1-X10"},{"t":"6 + ⟨3/4⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/4⟩시간에 6 L예요.","1시간 동안의 양은 6 ÷ ⟨3/4⟩이에요.","양이 앞, 시간이 뒤예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#5','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'sa','auto','자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","explanation":["⟨1/3⟩시간 동안에는 4 ÷ 2 = 2 km를 가요.","1시간은 ⟨1/3⟩시간의 3배라 2 × 3 = 6이에요.","4 ÷ ⟨2/3⟩ = 4 × ⟨3/2⟩ = 6 — 6 km예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["6","6km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#6','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'ox','auto','4 ÷ ⟨2/3⟩는 4 × ⟨2/3⟩와 같아요.',ARRAY['M6-2-u1-X10']::text[],false,'{"seq":6,"concept":"M6-2-u1-C6","difficulty":2,"kind":"ox","stem":"4 ÷ ⟨2/3⟩는 4 × ⟨2/3⟩와 같아요.","answer":"X","reason_options":[{"t":"나누는 분수의 분모와 분자를 바꾸어 4 × ⟨3/2⟩으로 계산해야 해서","correct":true},{"t":"나눗셈은 곱셈으로 바꿀 수 없어서","mis":"M6-2-u1-X10"}],"mis":"M6-2-u1-X10","explanation":["4 ÷ ⟨2/3⟩는 4를 2로 나누고 3을 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨3/2⟩을 곱하는 것과 같아요.","그래서 4 × ⟨3/2⟩ = 6 — 4 × ⟨2/3⟩가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#7','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C6","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"9 ÷ ⟨3/7⟩","r":"21"},{"l":"15 ÷ ⟨5/6⟩","r":"18"},{"l":"10 ÷ ⟨2/3⟩","r":"15"}],"mis":"M6-2-u1-X10","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요.","9 × ⟨7/3⟩ = 21, 15 × ⟨6/5⟩ = 18이에요.","10 × ⟨3/2⟩ = 15예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"6 ÷ ⟨3/4⟩","r":"8"},{"l":"12 ÷ ⟨4/5⟩","r":"15"},{"l":"14 ÷ ⟨7/9⟩","r":"18"}],"explanation":["분모와 분자를 바꾸어 곱해요.","6 × ⟨4/3⟩ = 8, 12 × ⟨5/4⟩ = 15예요.","14 × ⟨9/7⟩ = 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#8','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'mc','auto','5 ÷ ⟨2/3⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":8,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"5 ÷ ⟨2/3⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 5 × ⟨3/2⟩.","5 × 3 = 15, 15 ÷ 2 = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","그래서 몫은 ⟨7 1/2⟩이에요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans","exact":false}},"options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/6⟩","mis":"M6-2-u1-X11"},{"t":"10","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#9','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',2,'sa','auto','자전거를 타고 12 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"자전거를 타고 12 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","explanation":["⟨1/3⟩시간 동안에는 12 ÷ 2 = 6 km를 가요.","1시간은 ⟨1/3⟩시간의 3배라 6 × 3 = 18이에요.","12 ÷ ⟨2/3⟩ = 12 × ⟨3/2⟩ = 18 — 18 km예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["18","18km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_basic#10','math',6,2,'u1','L06','g6_2_math_u1_L06_basic','lesson_basic','M6-2-u1-C6',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":10,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해 몫을 구해요.","9 ÷ ⟨7/8⟩ = ⟨10 2/7⟩, 2 ÷ ⟨1/3⟩ = 6, 2 ÷ ⟨3/5⟩ = ⟨3 1/3⟩, 3 ÷ ⟨4/5⟩ = ⟨3 3/4⟩이에요.","가장 큰 몫은 9 ÷ ⟨7/8⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"nfrac"}},"options":[{"t":"9 ÷ ⟨7/8⟩","correct":true},{"t":"2 ÷ ⟨1/3⟩","mis":"M6-2-u1-X16"},{"t":"3 ÷ ⟨4/5⟩","mis":"M6-2-u1-X16"},{"t":"2 ÷ ⟨3/5⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#1','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',2,'mc','auto','7 ÷ ⟨4/5⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":1,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"7 ÷ ⟨4/5⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 7 × ⟨5/4⟩.","7 × 5 = 35, 35 ÷ 4 = ⟨35/4⟩ = ⟨8 3/4⟩이에요.","그래서 몫은 ⟨8 3/4⟩이에요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans","exact":false}},"options":[{"t":"⟨8 3/4⟩","correct":true},{"t":"⟨5 3/5⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/20⟩","mis":"M6-2-u1-X11"},{"t":"28","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#2','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',2,'sa','auto','걸어서 9 km를 가는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 걸을 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C6","difficulty":2,"kind":"sa","stem":"걸어서 9 km를 가는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 걸을 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","explanation":["⟨1/4⟩시간 동안에는 9 ÷ 3 = 3 km를 가요.","1시간은 ⟨1/4⟩시간의 4배라 3 × 4 = 12예요.","9 ÷ ⟨3/4⟩ = 9 × ⟨4/3⟩ = 12 — 12 km예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["12","12km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#3','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'error','auto','4 ÷ ⟨2/3⟩를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X11','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C6","difficulty":3,"kind":"error","stem":"4 ÷ ⟨2/3⟩를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도영 — 「4를 3으로 나누고 2를 곱해서 ⟨2 2/3⟩야.」","correct":true,"mis_target":"M6-2-u1-X11"},{"t":"나린 — 「4를 2로 나누면 2, 거기에 3을 곱해서 6이야.」","mis":"M6-2-u1-X20"},{"t":"하람 — 「4 × ⟨3/2⟩ = 6이야.」","mis":"M6-2-u1-X20"}],"explanation":["⟨1/3⟩시간 동안 간 거리는 4 ÷ 2 = 2 km, 1시간은 그 3배라 6 km예요.","분자로 나누고 분모를 곱해요 — 4 × ⟨3/2⟩ = 6.","도영이는 두 걸음의 순서를 거꾸로 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#4','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','몫이 가장 작은 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":4,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"몫이 가장 작은 것은 어느 것인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해 몫을 구해요.","8 ÷ ⟨6/7⟩ = ⟨9 1/3⟩, 6 ÷ ⟨2/3⟩ = 9, 7 ÷ ⟨3/5⟩ = ⟨11 2/3⟩, 3 ÷ ⟨4/5⟩ = ⟨3 3/4⟩이에요.","가장 작은 몫은 3 ÷ ⟨4/5⟩예요."],"variant_rule":{"fd":{"ask":"cmp","kind":"nfrac"}},"options":[{"t":"3 ÷ ⟨4/5⟩","correct":true},{"t":"6 ÷ ⟨2/3⟩","mis":"M6-2-u1-X16"},{"t":"8 ÷ ⟨6/7⟩","mis":"M6-2-u1-X16"},{"t":"7 ÷ ⟨3/5⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#5','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','다음 중 몫이 다른 하나는 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],true,'{"seq":5,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"다음 중 몫이 다른 하나는 어느 것인가요?","options":[{"t":"12 ÷ ⟨4/5⟩","correct":true},{"t":"15 ÷ ⟨5/6⟩","mis":"M6-2-u1-X20"},{"t":"6 ÷ ⟨1/3⟩","mis":"M6-2-u1-X20"},{"t":"8 ÷ ⟨4/9⟩","mis":"M6-2-u1-X20"}],"explanation":["15 × ⟨6/5⟩ = 18, 6 × 3 = 18, 8 × ⟨9/4⟩ = 18이에요.","12 × ⟨5/4⟩ = 15예요.","몫이 다른 하나는 12 ÷ ⟨4/5⟩예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 몫이 다른 하나는 어느 것인가요?","options":[{"t":"10 ÷ ⟨2/3⟩","correct":true},{"t":"9 ÷ ⟨3/4⟩","mis":"M6-2-u1-X20"},{"t":"4 ÷ ⟨1/3⟩","mis":"M6-2-u1-X20"},{"t":"8 ÷ ⟨2/3⟩","mis":"M6-2-u1-X20"}],"explanation":["9 × ⟨4/3⟩ = 12, 4 × 3 = 12, 8 × ⟨3/2⟩ = 12예요.","10 × ⟨3/2⟩ = 15예요.","몫이 다른 하나는 10 ÷ ⟨2/3⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#6','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','흙 15 kg을 화분 한 개에 ⟨3/20⟩ kg씩 나누어 담으면 화분은 몇 개 필요한가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":6,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"흙 15 kg을 화분 한 개에 ⟨3/20⟩ kg씩 나누어 담으면 화분은 몇 개 필요한가요?","options":[{"t":"100개","correct":true},{"t":"⟨2 1/4⟩개","mis":"M6-2-u1-X10"},{"t":"45개","mis":"M6-2-u1-X11"},{"t":"5개","mis":"M6-2-u1-X11"}],"explanation":["15 ÷ ⟨3/20⟩ = 15 × ⟨20/3⟩이에요.","15 × 20 = 300, 300 ÷ 3 = 100이에요.","화분은 100개 필요해요."],"variant_rule":{"alt":[{"stem":"밀가루 12 kg을 봉지 한 개에 ⟨3/25⟩ kg씩 나누어 담으면 봉지는 몇 개 필요한가요?","options":[{"t":"100개","correct":true},{"t":"⟨1 11/25⟩개","mis":"M6-2-u1-X10"},{"t":"36개","mis":"M6-2-u1-X11"},{"t":"4개","mis":"M6-2-u1-X11"}],"explanation":["12 ÷ ⟨3/25⟩ = 12 × ⟨25/3⟩예요.","12 × 25 = 300, 300 ÷ 3 = 100이에요.","봉지는 100개 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#7','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',3,'mc','auto','9 ÷ ⟨3/7⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X01']::text[],true,'{"seq":7,"concept":"M6-2-u1-C6","difficulty":3,"kind":"mc","stem":"9 ÷ ⟨3/7⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["9 ÷ ⟨3/7⟩은 9를 3으로 나누고 7을 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨7/3⟩을 곱하는 것과 같아요.","나누는 분수의 분모와 분자를 바꾸어 곱해요 — 9 × ⟨7/3⟩."],"variant_rule":{"fd":{"ask":"nfrac","form":"expr"}},"options":[{"t":"9 × ⟨7/3⟩","correct":true},{"t":"9 × ⟨3/7⟩","mis":"M6-2-u1-X10"},{"t":"9 ÷ 7 × 3","mis":"M6-2-u1-X11"},{"t":"⟨7/3⟩ ÷ 9","mis":"M6-2-u1-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#8','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',4,'essay','teacher','4 ÷ ⟨2/3⟩를 「⟨1/3⟩시간 동안 간 거리」와 「1시간 동안 간 거리」의 두 걸음으로 계산하고, 왜 결국 4 × ⟨3/2⟩과 같아지는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C6","difficulty":4,"kind":"essay","stem":"4 ÷ ⟨2/3⟩를 「⟨1/3⟩시간 동안 간 거리」와 「1시간 동안 간 거리」의 두 걸음으로 계산하고, 왜 결국 4 × ⟨3/2⟩과 같아지는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨2/3⟩시간에 4 km이므로 ⟨1/3⟩시간에는 4 ÷ 2 = 2 km, 1시간은 ⟨1/3⟩시간의 3배이므로 2 × 3 = 6 km이다. 분자 2로 나누고 분모 3을 곱하는 두 걸음은 ⟨3/2⟩을 한 번 곱하는 것과 같으므로 4 ÷ ⟨2/3⟩ = 4 × ⟨3/2⟩ = 6이다.","scoring_points":["4 ÷ 2 = 2(첫 걸음)를 썼는가","2 × 3 = 6(둘째 걸음)을 썼는가","두 걸음이 ⟨3/2⟩ 곱하기와 같음을 설명했는가"]},"explanation":["⟨1/3⟩시간에는 4 ÷ 2 = 2 km예요.","1시간에는 2 × 3 = 6 km예요.","÷2 하고 ×3 하는 것은 ×⟨3/2⟩과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#9','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',4,'essay','teacher','현우는 전기 자전거로 12 km를 가는 데 ⟨2/3⟩시간이 걸렸고, 유나는 자전거로 6 km를 가는 데 ⟨3/4⟩시간이 걸렸어요. 1시간 동안 갈 수 있는 거리를 각각 구하고 누가 더 빠른지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C6","difficulty":4,"kind":"essay","stem":"현우는 전기 자전거로 12 km를 가는 데 ⟨2/3⟩시간이 걸렸고, 유나는 자전거로 6 km를 가는 데 ⟨3/4⟩시간이 걸렸어요. 1시간 동안 갈 수 있는 거리를 각각 구하고 누가 더 빠른지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 현우는 12 ÷ ⟨2/3⟩ = 12 × ⟨3/2⟩ = 18 km, 유나는 6 ÷ ⟨3/4⟩ = 6 × ⟨4/3⟩ = 8 km. 1시간에 가는 거리가 긴 현우가 더 빠르다.","scoring_points":["현우 18 km를 구했는가","유나 8 km를 구했는가","1시간 거리를 견주어 현우가 빠르다고 썼는가"]},"explanation":["현우: 12 × ⟨3/2⟩ = 18 km예요.","유나: 6 × ⟨4/3⟩ = 8 km예요.","1시간에 더 멀리 가는 현우가 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L06_challenge#10','math',6,2,'u1','L06','g6_2_math_u1_L06_challenge','lesson_challenge','M6-2-u1-C6',4,'mc','auto','□ ÷ ⟨3/4⟩ = 12예요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":10,"concept":"M6-2-u1-C6","difficulty":4,"kind":"mc","stem":"□ ÷ ⟨3/4⟩ = 12예요. □에 알맞은 수는 얼마인가요?","options":[{"t":"9","correct":true},{"t":"16","mis":"M6-2-u1-X19"},{"t":"36","mis":"M6-2-u1-X19"},{"t":"⟨1 1/3⟩","mis":"M6-2-u1-X19"}],"explanation":["□ ÷ ⟨3/4⟩ = □ × ⟨4/3⟩ = 12예요.","□ = 12 ÷ ⟨4/3⟩ = 12 × ⟨3/4⟩이에요.","그래서 □는 9예요."],"variant_rule":{"alt":[{"stem":"□ ÷ ⟨2/5⟩ = 20이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"8","correct":true},{"t":"50","mis":"M6-2-u1-X19"},{"t":"40","mis":"M6-2-u1-X19"},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X19"}],"explanation":["□ × ⟨5/2⟩ = 20이에요.","□ = 20 × ⟨2/5⟩예요.","□는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#1','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','⟨2/5⟩ ÷ ⟨3/4⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X12']::text[],true,'{"seq":1,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨3/4⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["나누는 분수 ⟨3/4⟩만 분모와 분자를 바꿔요.","나누어지는 분수 ⟨2/5⟩는 그대로 두어야 양이 바뀌지 않아요.","그래서 ⟨2/5⟩ × ⟨4/3⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"expr"}},"options":[{"t":"⟨2/5⟩ × ⟨4/3⟩","correct":true},{"t":"⟨2/5⟩ × ⟨3/4⟩","mis":"M6-2-u1-X12"},{"t":"⟨5/2⟩ × ⟨4/3⟩","mis":"M6-2-u1-X12"},{"t":"⟨5/2⟩ × ⟨3/4⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#2','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','⟨2/5⟩ ÷ ⟨3/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":2,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨3/4⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — ⟨2/5⟩ × ⟨4/3⟩.","분자끼리, 분모끼리 곱하면 ⟨8/15⟩이에요.","그래서 몫은 ⟨8/15⟩이에요."],"variant_rule":{"fd":{"ask":"mul","form":"ans"}},"options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 7/8⟩","mis":"M6-2-u1-X05"},{"t":"⟨3 1/3⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#3','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'sa','auto','⟨1/6⟩ ÷ ⟨4/7⟩의 몫을 기약분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-2-u1-C7","difficulty":1,"kind":"sa","stem":"⟨1/6⟩ ÷ ⟨4/7⟩의 몫을 기약분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/6⟩ ÷ ⟨4/7⟩ = ⟨1/6⟩ × ⟨7/4⟩이에요.","곱하면 ⟨7/24⟩이에요.","분모는 24예요."],"variant_rule":{"fd":{"ask":"mul","form":"den"}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#4','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',1,'mc','auto','⟨2/5⟩ ÷ ⟨3/4⟩을 곱셈으로 바꿀 때 ⟨3/4⟩만 뒤집어 ⟨2/5⟩ × ⟨4/3⟩로 쓰는 까닭은 무엇인가요?',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":4,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨3/4⟩을 곱셈으로 바꿀 때 ⟨3/4⟩만 뒤집어 ⟨2/5⟩ × ⟨4/3⟩로 쓰는 까닭은 무엇인가요?","options":[{"t":"나누어지는 양 ⟨2/5⟩는 그대로 두어야 양이 바뀌지 않기 때문에","correct":true},{"t":"앞 분수를 뒤집으면 분모가 너무 커지기 때문에","mis":"M6-2-u1-X12"},{"t":"두 분수를 다 뒤집어도 답은 같기 때문에","mis":"M6-2-u1-X12"},{"t":"곱셈에서는 늘 뒤 분수만 뒤집기 때문에","mis":"M6-2-u1-X12"}],"explanation":["뒤집는 것은 나누는 분수뿐이에요.","나누어지는 분수를 뒤집으면 나누는 양 자체가 달라져요.","두 분수를 다 뒤집거나 그대로 곱하면 답이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#5','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'ox','auto','⟨5/8⟩ ÷ ⟨5/9⟩ = ⟨5/8⟩ × ⟨5/9⟩ = ⟨25/72⟩예요.',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":5,"concept":"M6-2-u1-C7","difficulty":2,"kind":"ox","stem":"⟨5/8⟩ ÷ ⟨5/9⟩ = ⟨5/8⟩ × ⟨5/9⟩ = ⟨25/72⟩예요.","answer":"X","reason_options":[{"t":"나누는 분수 ⟨5/9⟩의 분모와 분자를 바꾸어 ⟨5/8⟩ × ⟨9/5⟩ = ⟨1 1/8⟩로 계산해야 해서","correct":true},{"t":"두 분수의 분모와 분자를 모두 바꾸어 곱해야 해서","mis":"M6-2-u1-X12"}],"mis":"M6-2-u1-X12","explanation":["나눗셈을 곱셈으로 바꿀 때는 나누는 분수만 뒤집어요.","⟨5/8⟩ × ⟨9/5⟩ = ⟨45/40⟩ = ⟨9/8⟩예요.","대분수로 고치면 ⟨1 1/8⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#6','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'match','auto','나눗셈식과 곱셈으로 바꾼 식을 알맞게 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":2,"kind":"match","stem":"나눗셈식과 곱셈으로 바꾼 식을 알맞게 이으세요.","pairs":[{"l":"⟨1/6⟩ ÷ ⟨4/7⟩","r":"⟨1/6⟩ × ⟨7/4⟩"},{"l":"⟨3/10⟩ ÷ ⟨5/8⟩","r":"⟨3/10⟩ × ⟨8/5⟩"},{"l":"⟨4/7⟩ ÷ ⟨1/6⟩","r":"⟨4/7⟩ × 6"}],"mis":"M6-2-u1-X12","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요.","⟨4/7⟩는 ⟨7/4⟩로, ⟨5/8⟩는 ⟨8/5⟩로 뒤집어요.","⟨1/6⟩을 뒤집으면 6이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 곱셈으로 바꾼 식을 알맞게 이으세요.","pairs":[{"l":"⟨2/9⟩ ÷ ⟨3/5⟩","r":"⟨2/9⟩ × ⟨5/3⟩"},{"l":"⟨3/5⟩ ÷ ⟨2/9⟩","r":"⟨3/5⟩ × ⟨9/2⟩"},{"l":"⟨5/7⟩ ÷ ⟨1/4⟩","r":"⟨5/7⟩ × 4"}],"explanation":["나누는 분수만 뒤집어요.","⟨3/5⟩은 ⟨5/3⟩, ⟨2/9⟩는 ⟨9/2⟩예요.","⟨1/4⟩을 뒤집으면 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
