INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#9','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',2,'sa','auto','⟨3/10⟩ ÷ ⟨5/8⟩의 몫을 기약분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":2,"kind":"sa","stem":"⟨3/10⟩ ÷ ⟨5/8⟩의 몫을 기약분수로 나타낼 때 분자는 얼마인가요? 숫자로 쓰세요.","explanation":["⟨3/10⟩ ÷ ⟨5/8⟩ = ⟨3/10⟩ × ⟨8/5⟩이에요.","곱하면 ⟨24/50⟩, 약분하면 ⟨12/25⟩예요.","분자는 12예요."],"variant_rule":{"fd":{"ask":"mul","form":"numr"}},"answer":["12"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_basic#10','math',6,2,'u1','L07','g6_2_math_u1_L07_basic','lesson_basic','M6-2-u1-C7',3,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":10,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해 몫을 구해요.","⟨1/7⟩ ÷ ⟨1/5⟩ = ⟨5/7⟩, ⟨1/9⟩ ÷ ⟨2/9⟩ = ⟨1/2⟩, ⟨2/3⟩ ÷ ⟨1/5⟩ = ⟨3 1/3⟩, ⟨6/7⟩ ÷ ⟨8/9⟩ = ⟨27/28⟩이에요.","가장 큰 몫은 ⟨2/3⟩ ÷ ⟨1/5⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"mul"}},"options":[{"t":"⟨2/3⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨6/7⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X16"},{"t":"⟨1/7⟩ ÷ ⟨1/5⟩","mis":"M6-2-u1-X16"},{"t":"⟨1/9⟩ ÷ ⟨2/9⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#1','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',2,'mc','auto','⟨8/15⟩ ÷ ⟨4/5⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":1,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨8/15⟩ ÷ ⟨4/5⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — ⟨8/15⟩ × ⟨5/4⟩.","분자끼리, 분모끼리 곱하면 ⟨40/60⟩ = ⟨2/3⟩예요.","그래서 몫은 ⟨2/3⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"ans"}},"options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨32/75⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X05"},{"t":"⟨2 11/32⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#2','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',2,'mc','auto','굵기가 일정한 나무 막대 ⟨3/7⟩ m의 무게가 ⟨3/5⟩ kg이에요. 이 막대 1 kg은 몇 m인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":2,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"굵기가 일정한 나무 막대 ⟨3/7⟩ m의 무게가 ⟨3/5⟩ kg이에요. 이 막대 1 kg은 몇 m인가요?","explanation":["1 kg의 길이는 ⟨3/7⟩ ÷ ⟨3/5⟩으로 구해요.","⟨3/7⟩ ÷ ⟨3/5⟩ = ⟨3/7⟩ × ⟨5/3⟩ = ⟨15/21⟩ = ⟨5/7⟩예요.","그래서 ⟨5/7⟩ m예요."],"variant_rule":{"fd":{"ask":"mul","form":"story"}},"options":[{"t":"⟨5/7⟩ m","correct":true},{"t":"⟨9/35⟩ m","mis":"M6-2-u1-X12"},{"t":"⟨1 2/5⟩ m","mis":"M6-2-u1-X05"},{"t":"⟨3 8/9⟩ m","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#3','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'error','auto','⟨8/15⟩ ÷ ⟨4/5⟩를 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":3,"concept":"M6-2-u1-C7","difficulty":3,"kind":"error","stem":"⟨8/15⟩ ÷ ⟨4/5⟩를 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨8/15⟩ × ⟨5/4⟩ = ⟨2/3⟩야.」","correct":true,"mis_target":"M6-2-u1-X12"},{"t":"준서 — 「⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩야.」","mis":"M6-2-u1-X12"},{"t":"가은 — 「⟨15/8⟩ × ⟨5/4⟩ = ⟨75/32⟩야.」","mis":"M6-2-u1-X12"}],"explanation":["나누는 분수 ⟨4/5⟩만 뒤집어 ⟨8/15⟩ × ⟨5/4⟩예요.","⟨40/60⟩ = ⟨2/3⟩예요.","준서는 뒤집지 않았고 가은이는 두 분수를 다 뒤집었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#4','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','몫이 가장 작은 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":4,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"몫이 가장 작은 것은 어느 것인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해 몫을 구해요.","⟨6/7⟩ ÷ ⟨1/5⟩ = ⟨4 2/7⟩, ⟨3/7⟩ ÷ ⟨1/3⟩ = ⟨1 2/7⟩, ⟨3/4⟩ ÷ ⟨2/3⟩ = ⟨1 1/8⟩, ⟨1/4⟩ ÷ ⟨5/8⟩ = ⟨2/5⟩예요.","가장 작은 몫은 ⟨1/4⟩ ÷ ⟨5/8⟩예요."],"variant_rule":{"fd":{"ask":"cmp","kind":"mul"}},"options":[{"t":"⟨1/4⟩ ÷ ⟨5/8⟩","correct":true},{"t":"⟨3/4⟩ ÷ ⟨2/3⟩","mis":"M6-2-u1-X16"},{"t":"⟨3/7⟩ ÷ ⟨1/3⟩","mis":"M6-2-u1-X16"},{"t":"⟨6/7⟩ ÷ ⟨1/5⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#5','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','세호는 ⟨3/4⟩ ÷ ⟨8/9⟩을 ⟨3/4⟩ × ⟨8/9⟩로 계산했어요. 바르게 고치면 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05','M6-2-u1-X15']::text[],true,'{"seq":5,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"세호는 ⟨3/4⟩ ÷ ⟨8/9⟩을 ⟨3/4⟩ × ⟨8/9⟩로 계산했어요. 바르게 고치면 몫은 얼마인가요?","options":[{"t":"⟨27/32⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u1-X12"},{"t":"⟨32/27⟩","mis":"M6-2-u1-X05"},{"t":"⟨24/36⟩","mis":"M6-2-u1-X15"}],"explanation":["나누는 분수 ⟨8/9⟩을 뒤집어 ⟨3/4⟩ × ⟨9/8⟩로 고쳐요.","분자끼리, 분모끼리 곱하면 ⟨27/32⟩이에요.","⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩는 뒤집지 않은 잘못된 계산이에요."],"variant_rule":{"alt":[{"stem":"아진이는 ⟨5/6⟩ ÷ ⟨7/8⟩을 ⟨5/6⟩ × ⟨7/8⟩로 계산했어요. 바르게 고치면 몫은 얼마인가요?","options":[{"t":"⟨20/21⟩","correct":true},{"t":"⟨35/48⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 1/20⟩","mis":"M6-2-u1-X05"},{"t":"⟨40/42⟩","mis":"M6-2-u1-X15"}],"explanation":["⟨7/8⟩을 뒤집어 ⟨5/6⟩ × ⟨8/7⟩이에요.","⟨40/42⟩ = ⟨20/21⟩이에요.","⟨35/48⟩는 뒤집지 않은 계산이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#6','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'sa','auto','⟨12/13⟩ ÷ ⟨2/7⟩의 몫을 기약분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-2-u1-C7","difficulty":3,"kind":"sa","stem":"⟨12/13⟩ ÷ ⟨2/7⟩의 몫을 기약분수로 나타낼 때 분모는 얼마인가요? 숫자로 쓰세요.","explanation":["⟨12/13⟩ ÷ ⟨2/7⟩ = ⟨12/13⟩ × ⟨7/2⟩이에요.","곱하면 ⟨84/26⟩, 약분하면 ⟨42/13⟩예요.","분모는 13이에요."],"variant_rule":{"fd":{"ask":"mul","form":"den"}},"answer":["13"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#7','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',3,'mc','auto','다음 중 몫이 1보다 큰 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":7,"concept":"M6-2-u1-C7","difficulty":3,"kind":"mc","stem":"다음 중 몫이 1보다 큰 것은 어느 것인가요?","options":[{"t":"⟨12/13⟩ ÷ ⟨2/7⟩","correct":true},{"t":"⟨7/10⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X16"},{"t":"⟨5/12⟩ ÷ ⟨3/4⟩","mis":"M6-2-u1-X16"},{"t":"⟨1/6⟩ ÷ ⟨4/7⟩","mis":"M6-2-u1-X16"}],"explanation":["나누어지는 수가 나누는 수보다 크면 몫이 1보다 커요.","⟨12/13⟩는 ⟨2/7⟩보다 커요 — 몫은 ⟨42/13⟩ = ⟨3 3/13⟩이에요.","나머지는 나누어지는 수가 더 작아 몫이 1보다 작아요."],"variant_rule":{"alt":[{"stem":"다음 중 몫이 1보다 작은 것은 어느 것인가요?","options":[{"t":"⟨2/9⟩ ÷ ⟨3/5⟩","correct":true},{"t":"⟨3/5⟩ ÷ ⟨2/9⟩","mis":"M6-2-u1-X16"},{"t":"⟨7/8⟩ ÷ ⟨1/3⟩","mis":"M6-2-u1-X16"},{"t":"⟨5/6⟩ ÷ ⟨4/7⟩","mis":"M6-2-u1-X16"}],"explanation":["나누어지는 수가 나누는 수보다 작으면 몫이 1보다 작아요.","⟨2/9⟩는 ⟨3/5⟩보다 작아요 — 몫은 ⟨10/27⟩이에요.","나머지는 나누어지는 수가 더 커 몫이 1보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#8','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',4,'essay','teacher','⟨2/5⟩ ÷ ⟨3/4⟩을 「통의 ⟨1/4⟩을 채우는 쌀」과 「한 통을 가득 채우는 쌀」의 두 걸음으로 계산하고, 왜 ⟨2/5⟩ × ⟨4/3⟩와 같아지는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C7","difficulty":4,"kind":"essay","stem":"⟨2/5⟩ ÷ ⟨3/4⟩을 「통의 ⟨1/4⟩을 채우는 쌀」과 「한 통을 가득 채우는 쌀」의 두 걸음으로 계산하고, 왜 ⟨2/5⟩ × ⟨4/3⟩와 같아지는지 설명해 보세요.","answer_guide":{"answer":"예: 통의 ⟨3/4⟩을 채운 쌀이 ⟨2/5⟩ kg이므로 ⟨1/4⟩을 채우는 쌀은 ⟨2/5⟩ ÷ 3 = ⟨2/15⟩ kg, 한 통(⟨1/4⟩의 4배)은 ⟨2/15⟩ × 4 = ⟨8/15⟩ kg이다. 3으로 나누고 4를 곱하는 두 걸음은 ⟨4/3⟩를 곱하는 것과 같으므로 ⟨2/5⟩ ÷ ⟨3/4⟩ = ⟨2/5⟩ × ⟨4/3⟩ = ⟨8/15⟩이다.","scoring_points":["⟨2/5⟩ ÷ 3 = ⟨2/15⟩(첫 걸음)를 썼는가","⟨2/15⟩ × 4 = ⟨8/15⟩(둘째 걸음)을 썼는가","÷3 ×4가 ×⟨4/3⟩와 같음을 설명했는가"]},"explanation":["⟨1/4⟩을 채우는 쌀은 ⟨2/5⟩ ÷ 3 = ⟨2/15⟩ kg이에요.","한 통은 ⟨2/15⟩ × 4 = ⟨8/15⟩ kg이에요.","÷3 하고 ×4 하는 것은 ×⟨4/3⟩와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#9','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',4,'essay','teacher','수호는 ⟨3/4⟩ ÷ ⟨8/9⟩을 ⟨4/3⟩ × ⟨9/8⟩로 계산했어요. 무엇이 잘못되었는지 설명하고 바른 식과 몫을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C7","difficulty":4,"kind":"essay","stem":"수호는 ⟨3/4⟩ ÷ ⟨8/9⟩을 ⟨4/3⟩ × ⟨9/8⟩로 계산했어요. 무엇이 잘못되었는지 설명하고 바른 식과 몫을 써 보세요.","answer_guide":{"answer":"예: 뒤집어야 하는 것은 나누는 분수 ⟨8/9⟩뿐인데 수호는 나누어지는 분수 ⟨3/4⟩까지 뒤집었다. 바른 식은 ⟨3/4⟩ × ⟨9/8⟩이고 몫은 ⟨27/32⟩이다.","scoring_points":["나누어지는 분수를 뒤집은 것이 잘못임을 밝혔는가","바른 식 ⟨3/4⟩ × ⟨9/8⟩를 썼는가","몫 ⟨27/32⟩을 구했는가"]},"explanation":["뒤집는 것은 나누는 분수 하나뿐이에요.","⟨3/4⟩은 그대로 두고 ⟨8/9⟩만 ⟨9/8⟩로 뒤집어요.","⟨3/4⟩ × ⟨9/8⟩ = ⟨27/32⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L07_challenge#10','math',6,2,'u1','L07','g6_2_math_u1_L07_challenge','lesson_challenge','M6-2-u1-C7',4,'mc','auto','어떤 수를 ⟨2/3⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨1/2⟩이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":10,"concept":"M6-2-u1-C7","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨2/3⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨1/2⟩이 되었어요. 어떤 수는 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨2/3⟩ = ⟨1/2⟩이에요.","□ = ⟨1/2⟩ ÷ ⟨2/3⟩ = ⟨1/2⟩ × ⟨3/2⟩ = ⟨3/4⟩이에요.","그래서 어떤 수는 ⟨3/4⟩이에요."],"variant_rule":{"fd":{"ask":"back","form":"x"}},"options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/8⟩","mis":"M6-2-u1-X19"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X19"},{"t":"⟨1/2⟩","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#1','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','⟨2 5/6⟩를 가분수로 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u1-X14']::text[],true,'{"seq":1,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨2 5/6⟩를 가분수로 바르게 고친 것은 어느 것인가요?","explanation":["⟨2 5/6⟩는 2와 ⟨5/6⟩를 더한 수예요.","2는 ⟨12/6⟩니 2 × 6 + 5 = 17이 분자예요.","가분수로 고치면 ⟨17/6⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨7/6⟩","mis":"M6-2-u1-X14"},{"t":"⟨16/6⟩","mis":"M6-2-u1-X14"},{"t":"⟨12/6⟩","mis":"M6-2-u1-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#2','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'sa','auto','⟨1 4/5⟩를 가분수로 고칠 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C8","difficulty":1,"kind":"sa","stem":"⟨1 4/5⟩를 가분수로 고칠 때 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1 4/5⟩는 1과 ⟨4/5⟩를 더한 수예요.","1은 ⟨5/5⟩니 1 × 5 + 4 = 9가 분자예요.","가분수로 고치면 ⟨9/5⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"answer":["9"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#3','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','⟨1 1/3⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":3,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨1 1/3⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨4/3⟩ ÷ ⟨2/7⟩.","⟨4/3⟩ × ⟨7/2⟩ = ⟨28/6⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","그래서 몫은 ⟨4 2/3⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans"}},"options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨2 1/6⟩","mis":"M6-2-u1-X13"},{"t":"⟨8/21⟩","mis":"M6-2-u1-X12"},{"t":"⟨3/14⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#4','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',1,'mc','auto','대분수의 나눗셈을 계산하는 방법으로 옳은 것은 어느 것인가요?',ARRAY['M6-2-u1-X13']::text[],false,'{"seq":4,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"대분수의 나눗셈을 계산하는 방법으로 옳은 것은 어느 것인가요?","options":[{"t":"먼저 가분수로 고친 뒤 나눈다","correct":true},{"t":"자연수 부분과 분수 부분을 따로 나눈다","mis":"M6-2-u1-X13"},{"t":"대분수 그대로 분자끼리 나눈다","mis":"M6-2-u1-X13"},{"t":"대분수 그대로 분모와 분자를 바꾸어 곱한다","mis":"M6-2-u1-X13"}],"explanation":["대분수 ⟨1 4/5⟩는 1과 ⟨4/5⟩를 더한 꼴이에요.","더해진 꼴 그대로는 분자끼리 셀 수도, 뒤집을 수도 없어요.","가분수 ⟨9/5⟩로 고쳐야 한 덩어리 분수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#5','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'ox','auto','⟨1 4/5⟩ ÷ ⟨1 1/2⟩은 자연수끼리 1 ÷ 1 = 1, 분수끼리 ⟨4/5⟩ ÷ ⟨1/2⟩ = ⟨1 3/5⟩을 더해 ⟨2 3/5⟩이에요.',ARRAY['M6-2-u1-X13']::text[],false,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":2,"kind":"ox","stem":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩은 자연수끼리 1 ÷ 1 = 1, 분수끼리 ⟨4/5⟩ ÷ ⟨1/2⟩ = ⟨1 3/5⟩을 더해 ⟨2 3/5⟩이에요.","answer":"X","reason_options":[{"t":"대분수는 먼저 가분수로 고쳐 ⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨1 1/5⟩로 계산해야 해서","correct":true},{"t":"분수끼리 나눌 때 ⟨4/5⟩ ÷ ⟨1/2⟩의 계산이 틀려서","mis":"M6-2-u1-X13"}],"mis":"M6-2-u1-X13","explanation":["대분수는 더해진 꼴이라 따로 나누면 안 돼요.","⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨9/5⟩ × ⟨2/3⟩ = ⟨6/5⟩이에요.","몫은 ⟨1 1/5⟩ — ⟨2 3/5⟩이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#6','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'mc','auto','⟨1 4/5⟩ ÷ ⟨1 1/2⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":6,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨9/5⟩ ÷ ⟨3/2⟩.","⟨9/5⟩ × ⟨2/3⟩ = ⟨18/15⟩ = ⟨6/5⟩ = ⟨1 1/5⟩이에요.","그래서 몫은 ⟨1 1/5⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans2"}},"options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨2 3/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨5 2/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨5/6⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#7','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'match','auto','대분수와 가분수를 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C8","difficulty":2,"kind":"match","stem":"대분수와 가분수를 알맞게 이으세요.","pairs":[{"l":"⟨2 5/6⟩","r":"⟨17/6⟩"},{"l":"⟨3 1/4⟩","r":"⟨13/4⟩"},{"l":"⟨1 7/8⟩","r":"⟨15/8⟩"}],"mis":"M6-2-u1-X14","explanation":["자연수 × 분모 + 분자가 가분수의 분자예요.","2 × 6 + 5 = 17, 3 × 4 + 1 = 13이에요.","1 × 8 + 7 = 15예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 대분수와 가분수를 알맞게 이으세요.","pairs":[{"l":"⟨2 3/5⟩","r":"⟨13/5⟩"},{"l":"⟨1 5/9⟩","r":"⟨14/9⟩"},{"l":"⟨3 1/2⟩","r":"⟨7/2⟩"}],"explanation":["자연수 × 분모 + 분자예요.","2 × 5 + 3 = 13, 1 × 9 + 5 = 14예요.","3 × 2 + 1 = 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#8','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'mc','auto','⟨3 3/8⟩을 가분수로 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u1-X14']::text[],true,'{"seq":8,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨3 3/8⟩을 가분수로 바르게 고친 것은 어느 것인가요?","explanation":["⟨3 3/8⟩은 3과 ⟨3/8⟩을 더한 수예요.","3은 ⟨24/8⟩니 3 × 8 + 3 = 27이 분자예요.","가분수로 고치면 ⟨27/8⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"options":[{"t":"⟨27/8⟩","correct":true},{"t":"⟨6/8⟩","mis":"M6-2-u1-X14"},{"t":"⟨17/8⟩","mis":"M6-2-u1-X14"},{"t":"⟨24/8⟩","mis":"M6-2-u1-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#9','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',2,'mc','auto','직사각형 모양 천의 넓이는 ⟨1 4/5⟩ m², 가로는 ⟨1 1/2⟩ m예요. 세로는 몇 m인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":9,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"직사각형 모양 천의 넓이는 ⟨1 4/5⟩ m², 가로는 ⟨1 1/2⟩ m예요. 세로는 몇 m인가요?","explanation":["직사각형의 넓이는 가로 × 세로이니 세로는 넓이 ÷ 가로로 구해요.","가분수로 고쳐 ⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨9/5⟩ × ⟨2/3⟩ = ⟨18/15⟩이에요.","약분·대분수로 고치면 ⟨1 1/5⟩ — 세로는 ⟨1 1/5⟩ m예요."],"variant_rule":{"fd":{"ask":"mixed","form":"story"}},"options":[{"t":"⟨1 1/5⟩ m","correct":true},{"t":"⟨2 3/5⟩ m","mis":"M6-2-u1-X13"},{"t":"⟨5 2/5⟩ m","mis":"M6-2-u1-X13"},{"t":"⟨5/6⟩ m","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_basic#10','math',6,2,'u1','L08','g6_2_math_u1_L08_basic','lesson_basic','M6-2-u1-C8',3,'mc','auto','⟨2 3/5⟩ ÷ ⟨2/3⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":10,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"⟨2 3/5⟩ ÷ ⟨2/3⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨13/5⟩ ÷ ⟨2/3⟩.","⟨13/5⟩ × ⟨3/2⟩ = ⟨39/10⟩ = ⟨3 9/10⟩예요.","그래서 몫은 ⟨3 9/10⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans"}},"options":[{"t":"⟨3 9/10⟩","correct":true},{"t":"⟨2 9/10⟩","mis":"M6-2-u1-X13"},{"t":"⟨1 11/15⟩","mis":"M6-2-u1-X12"},{"t":"⟨10/39⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
