INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#2','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',2,'mc','auto','직사각형 모양 꽃밭의 넓이는 ⟨2 1/4⟩ m², 세로는 ⟨1 1/2⟩ m예요. 가로는 몇 m인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":2,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"직사각형 모양 꽃밭의 넓이는 ⟨2 1/4⟩ m², 세로는 ⟨1 1/2⟩ m예요. 가로는 몇 m인가요?","explanation":["직사각형의 넓이는 가로 × 세로이니 가로는 넓이 ÷ 세로로 구해요.","가분수로 고쳐 ⟨9/4⟩ ÷ ⟨3/2⟩ = ⟨9/4⟩ × ⟨2/3⟩ = ⟨18/12⟩이에요.","약분·대분수로 고치면 ⟨1 1/2⟩ — 가로는 ⟨1 1/2⟩ m예요."],"variant_rule":{"fd":{"ask":"mixed","form":"story"}},"options":[{"t":"⟨1 1/2⟩ m","correct":true},{"t":"⟨2 1/2⟩ m","mis":"M6-2-u1-X13"},{"t":"⟨6 3/4⟩ m","mis":"M6-2-u1-X13"},{"t":"⟨2/3⟩ m","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#3','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'error','auto','⟨2 5/6⟩ ÷ ⟨2/3⟩를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C8","difficulty":3,"kind":"error","stem":"⟨2 5/6⟩ ÷ ⟨2/3⟩를 두고 친구들이 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"유나 — 「⟨2 5/6⟩ × ⟨3/2⟩ = ⟨2 15/12⟩야.」","correct":true,"mis_target":"M6-2-u1-X13"},{"t":"지호 — 「⟨17/6⟩ × ⟨3/2⟩ = ⟨17/4⟩ = ⟨4 1/4⟩이야.」","mis":"M6-2-u1-X20"},{"t":"민서 — 「⟨17/6⟩ ÷ ⟨4/6⟩ = 17 ÷ 4 = ⟨4 1/4⟩이야.」","mis":"M6-2-u1-X20"}],"explanation":["대분수는 먼저 가분수 ⟨17/6⟩로 고쳐요.","통분해 17 ÷ 4로 가든, ⟨17/6⟩ × ⟨3/2⟩으로 가든 ⟨4 1/4⟩이에요.","유나는 대분수를 고치지 않고 분수 부분에만 곱했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#4','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','⟨2 3/5⟩ ÷ ⟨1 2/5⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":4,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"⟨2 3/5⟩ ÷ ⟨1 2/5⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨13/5⟩ ÷ ⟨7/5⟩.","⟨13/5⟩ × ⟨5/7⟩ = ⟨65/35⟩ = ⟨13/7⟩ = ⟨1 6/7⟩이에요.","그래서 몫은 ⟨1 6/7⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans2"}},"options":[{"t":"⟨1 6/7⟩","correct":true},{"t":"⟨3 1/2⟩","mis":"M6-2-u1-X13"},{"t":"⟨9 1/10⟩","mis":"M6-2-u1-X13"},{"t":"⟨7/13⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#5','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','7 ÷ ⟨2 5/8⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":5,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"7 ÷ ⟨2 5/8⟩의 몫은 얼마인가요?","options":[{"t":"⟨2 2/3⟩","correct":true},{"t":"⟨18 3/8⟩","mis":"M6-2-u1-X13"},{"t":"⟨2 1/8⟩","mis":"M6-2-u1-X13"},{"t":"⟨3/8⟩","mis":"M6-2-u1-X05"}],"explanation":["⟨2 5/8⟩를 가분수로 고치면 ⟨21/8⟩이에요.","7 ÷ ⟨21/8⟩ = 7 × ⟨8/21⟩ = ⟨56/21⟩ = ⟨8/3⟩이에요.","대분수로 고치면 ⟨2 2/3⟩예요."],"variant_rule":{"alt":[{"stem":"5 ÷ ⟨1 2/3⟩의 몫은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨8 1/3⟩","mis":"M6-2-u1-X13"},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X13"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"}],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩예요.","5 ÷ ⟨5/3⟩ = 5 × ⟨3/5⟩ = 3이에요.","몫은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#6','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','무게가 ⟨3/4⟩ kg인 천 ⟨3 1/6⟩ m가 있어요. 이 천 1 m의 무게는 몇 kg인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05','M6-2-u1-X13']::text[],true,'{"seq":6,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"무게가 ⟨3/4⟩ kg인 천 ⟨3 1/6⟩ m가 있어요. 이 천 1 m의 무게는 몇 kg인가요?","explanation":["1 m의 무게는 ⟨3/4⟩ ÷ ⟨3 1/6⟩로 구해요.","대분수를 가분수로 고쳐 ⟨3/4⟩ ÷ ⟨19/6⟩ = ⟨3/4⟩ × ⟨6/19⟩ = ⟨18/76⟩ = ⟨9/38⟩예요.","그래서 1 m의 무게는 ⟨9/38⟩ kg이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"story"}},"options":[{"t":"⟨9/38⟩ kg","correct":true},{"t":"⟨2 3/8⟩ kg","mis":"M6-2-u1-X12"},{"t":"⟨4 2/9⟩ kg","mis":"M6-2-u1-X05"},{"t":"⟨2 1/2⟩ kg","mis":"M6-2-u1-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#7','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',3,'mc','auto','어떤 수를 ⟨4 1/3⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 8/9⟩이 되었어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":7,"concept":"M6-2-u1-C8","difficulty":3,"kind":"mc","stem":"어떤 수를 ⟨4 1/3⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 8/9⟩이 되었어요. 바르게 계산한 값은 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨4 1/3⟩ = ⟨2 8/9⟩이에요.","□ = ⟨2 8/9⟩ ÷ ⟨4 1/3⟩ = ⟨2 8/9⟩ × ⟨3/13⟩ = ⟨2/3⟩예요.","바르게 계산하면 ⟨2/3⟩ ÷ ⟨4 1/3⟩ = ⟨2/3⟩ × ⟨3/13⟩ = ⟨2/13⟩예요."],"variant_rule":{"fd":{"ask":"back","form":"right"}},"options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u1-X19"},{"t":"⟨12 14/27⟩","mis":"M6-2-u1-X19"},{"t":"⟨2 8/9⟩","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#8','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',4,'essay','teacher','⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 유나는 통분으로, 지호는 곱셈으로 계산했어요. 두 길을 각각 식으로 쓰고, 두 길이 모두 먼저 해야 하는 일과 답이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C8","difficulty":4,"kind":"essay","stem":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩을 유나는 통분으로, 지호는 곱셈으로 계산했어요. 두 길을 각각 식으로 쓰고, 두 길이 모두 먼저 해야 하는 일과 답이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 유나 — ⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨18/10⟩ ÷ ⟨15/10⟩ = 18 ÷ 15 = ⟨1 1/5⟩. 지호 — ⟨9/5⟩ ÷ ⟨3/2⟩ = ⟨9/5⟩ × ⟨2/3⟩ = ⟨6/5⟩ = ⟨1 1/5⟩. 둘 다 먼저 대분수를 가분수로 고쳐야 하고, 통분은 같은 조각의 개수를 나누는 것·뒤집어 곱하기는 나누고 곱하는 두 걸음을 한 번에 적은 것이라 같은 답이 나온다.","scoring_points":["통분 길 식과 몫 ⟨1 1/5⟩을 썼는가","곱셈 길 식과 몫 ⟨1 1/5⟩을 썼는가","먼저 가분수로 고쳐야 함을 밝혔는가"]},"explanation":["두 길 모두 먼저 ⟨9/5⟩ ÷ ⟨3/2⟩으로 고쳐요.","통분: 18 ÷ 15, 곱셈: ⟨9/5⟩ × ⟨2/3⟩ — 둘 다 ⟨1 1/5⟩이에요.","어느 길로 가도 답은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#9','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',4,'essay','teacher','대분수 ⟨1 4/5⟩를 가분수로 고치지 않고 그대로 나누면 안 되는 까닭을 「더해진 꼴」이라는 말을 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C8","difficulty":4,"kind":"essay","stem":"대분수 ⟨1 4/5⟩를 가분수로 고치지 않고 그대로 나누면 안 되는 까닭을 「더해진 꼴」이라는 말을 써서 설명해 보세요.","answer_guide":{"answer":"예: ⟨1 4/5⟩는 1과 ⟨4/5⟩가 더해진 꼴이다. 더해진 꼴 그대로는 분자끼리 셀 수도 없고 분모와 분자를 뒤집을 수도 없다. 가분수 ⟨9/5⟩로 고쳐야 ⟨1/5⟩ 조각 9개라는 한 덩어리 분수가 되어 나눌 수 있다.","scoring_points":["더해진 꼴이라는 말을 썼는가","그대로는 분자끼리 세거나 뒤집을 수 없음을 설명했는가","가분수 ⟨9/5⟩로 고쳐야 하는 까닭을 썼는가"]},"explanation":["⟨1 4/5⟩는 1 + ⟨4/5⟩예요.","더해진 꼴은 분자끼리 셀 수도 뒤집을 수도 없어요.","⟨9/5⟩로 고쳐야 한 덩어리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L08_challenge#10','math',6,2,'u1','L08','g6_2_math_u1_L08_challenge','lesson_challenge','M6-2-u1-C8',4,'mc','auto','어떤 수를 ⟨5 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 3/4⟩이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":10,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨5 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 3/4⟩이 되었어요. 어떤 수는 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨5 1/2⟩ = ⟨2 3/4⟩이에요.","□ = ⟨2 3/4⟩ ÷ ⟨5 1/2⟩ = ⟨2 3/4⟩ × ⟨2/11⟩ = ⟨1/2⟩이에요.","그래서 어떤 수는 ⟨1/2⟩이에요."],"variant_rule":{"fd":{"ask":"back","form":"x"}},"options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/11⟩","mis":"M6-2-u1-X19"},{"t":"⟨15 1/8⟩","mis":"M6-2-u1-X19"},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#1','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 가로 60 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u1-C9","difficulty":1,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 가로 60 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 60 ÷ ⟨7 1/2⟩로 구해요.","⟨7 1/2⟩ = ⟨15/2⟩니 60 ÷ ⟨15/2⟩ = 60 × ⟨2/15⟩ = 8이에요.","그래서 8개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["8","8개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#2','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 세로 ⟨82 1/2⟩ cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C9","difficulty":1,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 세로 ⟨82 1/2⟩ cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 ⟨82 1/2⟩ ÷ ⟨7 1/2⟩로 구해요.","⟨7 1/2⟩ = ⟨15/2⟩니 ⟨82 1/2⟩ ÷ ⟨15/2⟩ = ⟨165/2⟩ × ⟨2/15⟩ = 11이에요.","그래서 11개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["11","11개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#3','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'mc','auto','가로에 타일 8개, 세로에 타일 11개가 들어가요. 벽을 가득 채우려면 타일은 모두 몇 개 필요한가요?',ARRAY['M6-2-u1-X17']::text[],true,'{"seq":3,"concept":"M6-2-u1-C9","difficulty":1,"kind":"mc","stem":"가로에 타일 8개, 세로에 타일 11개가 들어가요. 벽을 가득 채우려면 타일은 모두 몇 개 필요한가요?","explanation":["가로 8개짜리 줄이 세로로 11줄 늘어선 거예요.","8 + 11은 테두리 한 줄의 개수일 뿐이에요.","8 × 11 = 88 — 타일은 88개 필요해요."],"variant_rule":{"fd":{"ask":"tile","form":"total"}},"options":[{"t":"88개","correct":true},{"t":"19개","mis":"M6-2-u1-X17"},{"t":"38개","mis":"M6-2-u1-X17"},{"t":"80개","mis":"M6-2-u1-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#4','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',1,'mc','auto','가로에 8개, 세로에 11개가 들어가는 벽을 타일 100개로 겹치지 않게 가득 붙일 수 있나요?',ARRAY['M6-2-u1-X20','M6-2-u1-X17']::text[],true,'{"seq":4,"concept":"M6-2-u1-C9","difficulty":1,"kind":"mc","stem":"가로에 8개, 세로에 11개가 들어가는 벽을 타일 100개로 겹치지 않게 가득 붙일 수 있나요?","explanation":["필요한 타일은 8 × 11 = 88개예요.","100개는 88개보다 많아요.","88개면 되니 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"fit"}},"options":[{"t":"88개면 되니 붙일 수 있어요","correct":true},{"t":"88개가 필요해 12개 모자라요","mis":"M6-2-u1-X20"},{"t":"19개면 되니 붙일 수 있어요","mis":"M6-2-u1-X17"},{"t":"벽의 넓이를 알아야 해요","mis":"M6-2-u1-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#5','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'mc','auto','가로에 타일 8개, 세로에 타일 11개가 들어가는 벽을 꾸밀 때 8 + 11이 아니라 8 × 11로 계산하는 까닭은 무엇인가요?',ARRAY['M6-2-u1-X17']::text[],false,'{"seq":5,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"가로에 타일 8개, 세로에 타일 11개가 들어가는 벽을 꾸밀 때 8 + 11이 아니라 8 × 11로 계산하는 까닭은 무엇인가요?","options":[{"t":"8개짜리 줄이 11줄 늘어서 있기 때문에","correct":true},{"t":"8 + 11은 벽 테두리 전체의 개수라서","mis":"M6-2-u1-X17"},{"t":"곱하면 수가 커져 넉넉하기 때문에","mis":"M6-2-u1-X17"},{"t":"가로와 세로를 더하면 넓이가 되기 때문에","mis":"M6-2-u1-X17"}],"explanation":["가로 한 줄에 8개가 들어가요.","그런 줄이 세로로 11줄 늘어서요.","8 + 11 = 19는 테두리 한 줄의 개수일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#6','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'ox','auto','가로에 타일 6개, 세로에 타일 9개가 들어가는 게시판을 가득 채우려면 타일은 6 + 9 = 15개 필요해요.',ARRAY['M6-2-u1-X17']::text[],false,'{"seq":6,"concept":"M6-2-u1-C9","difficulty":2,"kind":"ox","stem":"가로에 타일 6개, 세로에 타일 9개가 들어가는 게시판을 가득 채우려면 타일은 6 + 9 = 15개 필요해요.","answer":"X","reason_options":[{"t":"6개짜리 줄이 9줄이라 6 × 9 = 54개가 필요해서","correct":true},{"t":"15개보다 많으면 어떤 수든 상관없어서","mis":"M6-2-u1-X17"}],"mis":"M6-2-u1-X17","explanation":["가로 한 줄에 6개, 그런 줄이 9줄이에요.","6 × 9 = 54개예요.","6 + 9 = 15는 테두리 한 줄의 개수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#7','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'match','auto','벽의 길이와 한 변이 ⟨2 1/2⟩ cm인 타일이 들어가는 개수를 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C9","difficulty":2,"kind":"match","stem":"벽의 길이와 한 변이 ⟨2 1/2⟩ cm인 타일이 들어가는 개수를 알맞게 이으세요.","pairs":[{"l":"20 cm","r":"8개"},{"l":"30 cm","r":"12개"},{"l":"45 cm","r":"18개"}],"mis":"M6-2-u1-X13","explanation":["⟨2 1/2⟩ = ⟨5/2⟩니 길이 × ⟨2/5⟩로 구해요.","20 × ⟨2/5⟩ = 8, 30 × ⟨2/5⟩ = 12예요.","45 × ⟨2/5⟩ = 18이에요."],"variant_rule":{"alt":[{"stem":"벽의 길이와 한 변이 ⟨1 1/2⟩ cm인 타일이 들어가는 개수를 알맞게 이으세요.","pairs":[{"l":"12 cm","r":"8개"},{"l":"18 cm","r":"12개"},{"l":"30 cm","r":"20개"}],"explanation":["⟨3/2⟩으로 나누면 길이 × ⟨2/3⟩예요.","12 × ⟨2/3⟩ = 8, 18 × ⟨2/3⟩ = 12예요.","30 × ⟨2/3⟩ = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#8','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨4 1/2⟩ cm인 정사각형 타일을 게시판의 가로 45 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨4 1/2⟩ cm인 정사각형 타일을 게시판의 가로 45 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 45 ÷ ⟨4 1/2⟩로 구해요.","⟨4 1/2⟩ = ⟨9/2⟩니 45 ÷ ⟨9/2⟩ = 45 × ⟨2/9⟩ = 10이에요.","그래서 10개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["10","10개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#9','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',2,'mc','auto','가로에 타일 10개, 세로에 타일 6개가 들어가요. 게시판을 가득 채우려면 타일은 모두 몇 개 필요한가요?',ARRAY['M6-2-u1-X17']::text[],true,'{"seq":9,"concept":"M6-2-u1-C9","difficulty":2,"kind":"mc","stem":"가로에 타일 10개, 세로에 타일 6개가 들어가요. 게시판을 가득 채우려면 타일은 모두 몇 개 필요한가요?","explanation":["가로 10개짜리 줄이 세로로 6줄 늘어선 거예요.","10 + 6은 테두리 한 줄의 개수일 뿐이에요.","10 × 6 = 60 — 타일은 60개 필요해요."],"variant_rule":{"fd":{"ask":"tile","form":"total"}},"options":[{"t":"60개","correct":true},{"t":"16개","mis":"M6-2-u1-X17"},{"t":"32개","mis":"M6-2-u1-X17"},{"t":"50개","mis":"M6-2-u1-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_basic#10','math',6,2,'u1','L09','g6_2_math_u1_L09_basic','lesson_basic','M6-2-u1-C9',3,'mc','auto','가로에 9개, 세로에 7개가 들어가는 벽을 타일 60개로 겹치지 않게 가득 붙일 수 있나요?',ARRAY['M6-2-u1-X20','M6-2-u1-X17']::text[],true,'{"seq":10,"concept":"M6-2-u1-C9","difficulty":3,"kind":"mc","stem":"가로에 9개, 세로에 7개가 들어가는 벽을 타일 60개로 겹치지 않게 가득 붙일 수 있나요?","explanation":["필요한 타일은 9 × 7 = 63개예요.","60개는 63개보다 적어요.","63개가 필요해 3개 모자라요."],"variant_rule":{"fd":{"ask":"tile","form":"fit"}},"options":[{"t":"63개가 필요해 3개 모자라요","correct":true},{"t":"63개면 되니 붙일 수 있어요","mis":"M6-2-u1-X20"},{"t":"16개면 되니 붙일 수 있어요","mis":"M6-2-u1-X17"},{"t":"벽의 넓이를 알아야 해요","mis":"M6-2-u1-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#1','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 게시판의 가로 350 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 게시판의 가로 350 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 350 ÷ ⟨8 3/4⟩으로 구해요.","⟨8 3/4⟩ = ⟨35/4⟩니 350 ÷ ⟨35/4⟩ = 350 × ⟨4/35⟩ = 40이에요.","그래서 40개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["40","40개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#2','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',2,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 게시판의 세로 140 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-2-u1-C9","difficulty":2,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 게시판의 세로 140 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 140 ÷ ⟨8 3/4⟩으로 구해요.","⟨8 3/4⟩ = ⟨35/4⟩니 140 ÷ ⟨35/4⟩ = 140 × ⟨4/35⟩ = 16이에요.","그래서 16개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["16","16개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#3','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'mc','auto','가로에 타일 40개, 세로에 타일 16개가 들어가요. 게시판을 가득 채우려면 타일은 모두 몇 개 필요한가요?',ARRAY['M6-2-u1-X17']::text[],true,'{"seq":3,"concept":"M6-2-u1-C9","difficulty":3,"kind":"mc","stem":"가로에 타일 40개, 세로에 타일 16개가 들어가요. 게시판을 가득 채우려면 타일은 모두 몇 개 필요한가요?","explanation":["가로 40개짜리 줄이 세로로 16줄 늘어선 거예요.","40 + 16은 테두리 한 줄의 개수일 뿐이에요.","40 × 16 = 640 — 타일은 640개 필요해요."],"variant_rule":{"fd":{"ask":"tile","form":"total"}},"options":[{"t":"640개","correct":true},{"t":"56개","mis":"M6-2-u1-X17"},{"t":"112개","mis":"M6-2-u1-X17"},{"t":"600개","mis":"M6-2-u1-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#4','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'error','auto','한 변이 ⟨8 3/4⟩ cm인 타일로 가로 350 cm, 세로 140 cm인 게시판을 꾸미는 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u1-X17','M6-2-u1-X20']::text[],false,'{"seq":4,"concept":"M6-2-u1-C9","difficulty":3,"kind":"error","stem":"한 변이 ⟨8 3/4⟩ cm인 타일로 가로 350 cm, 세로 140 cm인 게시판을 꾸미는 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「가로 40개와 세로 16개를 더하면 필요한 타일은 56개야.」","correct":true,"mis_target":"M6-2-u1-X17"},{"t":"지안 — 「350 ÷ ⟨8 3/4⟩ = 350 × ⟨4/35⟩ = 40개야.」","mis":"M6-2-u1-X20"},{"t":"현우 — 「세로는 140 × ⟨4/35⟩ = 16개야.」","mis":"M6-2-u1-X20"}],"explanation":["가로 40개, 세로 16개가 들어가요.","필요한 타일은 40 × 16 = 640개예요.","하은이는 가로 수와 세로 수를 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#5','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'mc','auto','한 변이 ⟨8 3/4⟩ cm인 타일로 한 변이 ⟨52 1/2⟩ cm인 정사각형 사물함 문을 가득 채우려면 타일이 몇 개 필요한가요?',ARRAY['M6-2-u1-X17']::text[],true,'{"seq":5,"concept":"M6-2-u1-C9","difficulty":3,"kind":"mc","stem":"한 변이 ⟨8 3/4⟩ cm인 타일로 한 변이 ⟨52 1/2⟩ cm인 정사각형 사물함 문을 가득 채우려면 타일이 몇 개 필요한가요?","options":[{"t":"36개","correct":true},{"t":"6개","mis":"M6-2-u1-X17"},{"t":"12개","mis":"M6-2-u1-X17"},{"t":"26개","mis":"M6-2-u1-X17"}],"explanation":["한 변에 들어가는 타일은 ⟨52 1/2⟩ ÷ ⟨8 3/4⟩ = ⟨105/2⟩ × ⟨4/35⟩ = 6개예요.","정사각형이라 가로도 세로도 6개예요.","6 × 6 = 36개 필요해요."],"variant_rule":{"alt":[{"stem":"한 변이 ⟨7 1/2⟩ cm인 타일로 한 변이 60 cm인 정사각형 창문을 가득 채우려면 타일이 몇 개 필요한가요?","options":[{"t":"64개","correct":true},{"t":"8개","mis":"M6-2-u1-X17"},{"t":"16개","mis":"M6-2-u1-X17"},{"t":"32개","mis":"M6-2-u1-X17"}],"explanation":["60 ÷ ⟨7 1/2⟩ = 60 × ⟨2/15⟩ = 8개예요.","가로도 세로도 8개예요.","8 × 8 = 64개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#6','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'mc','auto','가로에 12개, 세로에 9개가 들어가는 벽을 타일 120개로 겹치지 않게 가득 붙일 수 있나요?',ARRAY['M6-2-u1-X20','M6-2-u1-X17']::text[],true,'{"seq":6,"concept":"M6-2-u1-C9","difficulty":3,"kind":"mc","stem":"가로에 12개, 세로에 9개가 들어가는 벽을 타일 120개로 겹치지 않게 가득 붙일 수 있나요?","explanation":["필요한 타일은 12 × 9 = 108개예요.","120개는 108개보다 많아요.","108개면 되니 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"fit"}},"options":[{"t":"108개면 되니 붙일 수 있어요","correct":true},{"t":"108개가 필요해 12개 모자라요","mis":"M6-2-u1-X20"},{"t":"21개면 되니 붙일 수 있어요","mis":"M6-2-u1-X17"},{"t":"벽의 넓이를 알아야 해요","mis":"M6-2-u1-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#7','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',3,'mc','auto','가로 90 cm인 벽에 한 변이 ⟨7 1/2⟩ cm인 타일과 한 변이 ⟨4 1/2⟩ cm인 타일을 각각 한 줄로 붙일 때, 들어가는 개수의 차는 몇 개인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X13']::text[],true,'{"seq":7,"concept":"M6-2-u1-C9","difficulty":3,"kind":"mc","stem":"가로 90 cm인 벽에 한 변이 ⟨7 1/2⟩ cm인 타일과 한 변이 ⟨4 1/2⟩ cm인 타일을 각각 한 줄로 붙일 때, 들어가는 개수의 차는 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"12개","mis":"M6-2-u1-X18"},{"t":"20개","mis":"M6-2-u1-X18"},{"t":"3개","mis":"M6-2-u1-X13"}],"explanation":["⟨7 1/2⟩ cm 타일은 90 × ⟨2/15⟩ = 12개예요.","⟨4 1/2⟩ cm 타일은 90 × ⟨2/9⟩ = 20개예요.","차는 20 − 12 = 8개예요."],"variant_rule":{"alt":[{"stem":"가로 60 cm인 벽에 한 변이 ⟨7 1/2⟩ cm인 타일과 한 변이 ⟨2 1/2⟩ cm인 타일을 각각 한 줄로 붙일 때, 들어가는 개수의 차는 몇 개인가요?","options":[{"t":"16개","correct":true},{"t":"8개","mis":"M6-2-u1-X18"},{"t":"24개","mis":"M6-2-u1-X18"},{"t":"5개","mis":"M6-2-u1-X13"}],"explanation":["⟨7 1/2⟩ cm 타일은 8개예요.","⟨2 1/2⟩ cm 타일은 24개예요.","차는 16개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#8','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 가득 꾸미려고 해요. 타일 100개로 충분한지 계산 과정과 함께 판단해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 벽을 가득 꾸미려고 해요. 타일 100개로 충분한지 계산 과정과 함께 판단해 보세요.","answer_guide":{"answer":"예: 가로 60 ÷ ⟨7 1/2⟩ = 60 × ⟨2/15⟩ = 8개, 세로 ⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = ⟨165/2⟩ × ⟨2/15⟩ = 11개. 필요한 타일은 8 × 11 = 88개이므로 100개면 충분하다.","scoring_points":["가로 8개를 구했는가","세로 11개를 구했는가","8 × 11 = 88개로 100개면 충분하다고 판단했는가"]},"explanation":["가로에는 60 ÷ ⟨7 1/2⟩ = 8개예요.","세로에는 ⟨82 1/2⟩ ÷ ⟨7 1/2⟩ = 11개예요.","8 × 11 = 88개라 100개면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#9','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',4,'essay','teacher','타일 문제에서 조건(타일 한 변의 길이·벽의 크기)이 바뀌어도 푸는 방법은 같아요. 그 방법을 세 단계로 정리하고, 단계마다 어떤 계산을 하는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"타일 문제에서 조건(타일 한 변의 길이·벽의 크기)이 바뀌어도 푸는 방법은 같아요. 그 방법을 세 단계로 정리하고, 단계마다 어떤 계산을 하는지 써 보세요.","answer_guide":{"answer":"예: ① 가로 길이 ÷ 타일 한 변 → 가로에 들어가는 개수(대분수는 가분수로 고쳐 뒤집어 곱한다) ② 세로 길이 ÷ 타일 한 변 → 세로에 들어가는 개수 ③ 가로 개수 × 세로 개수 → 필요한 타일 수. 조건이 바뀌어도 이 세 단계는 그대로다.","scoring_points":["길이 ÷ 타일 한 변으로 가로·세로 개수를 구한다고 썼는가","가로 개수 × 세로 개수로 전체를 구한다고 썼는가","대분수 나눗셈의 계산 방법을 언급했는가"]},"explanation":["가로·세로에 들어가는 개수는 길이 ÷ 타일 한 변이에요.","필요한 타일 수는 가로 수 × 세로 수예요.","조건이 바뀌어도 방법은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L09_challenge#10','math',6,2,'u1','L09','g6_2_math_u1_L09_challenge','lesson_challenge','M6-2-u1-C9',4,'mc','auto','한 변이 ⟨7 1/2⟩ cm인 타일로 가로 60 cm인 벽을 꾸미는 데 타일이 모두 96개 필요했어요. 이 벽의 세로 길이는 몇 cm인가요?',ARRAY['M6-2-u1-X18','M6-2-u1-X20']::text[],true,'{"seq":10,"concept":"M6-2-u1-C9","difficulty":4,"kind":"mc","stem":"한 변이 ⟨7 1/2⟩ cm인 타일로 가로 60 cm인 벽을 꾸미는 데 타일이 모두 96개 필요했어요. 이 벽의 세로 길이는 몇 cm인가요?","options":[{"t":"90 cm","correct":true},{"t":"12 cm","mis":"M6-2-u1-X18"},{"t":"⟨82 1/2⟩ cm","mis":"M6-2-u1-X20"},{"t":"720 cm","mis":"M6-2-u1-X18"}],"explanation":["가로에는 60 ÷ ⟨7 1/2⟩ = 8개가 들어가요.","96 ÷ 8 = 12 — 세로에 12줄이 들어가요.","세로 길이는 ⟨7 1/2⟩ × 12 = 90 cm예요."],"variant_rule":{"alt":[{"stem":"한 변이 ⟨2 1/2⟩ cm인 타일로 가로 30 cm인 게시판을 꾸미는 데 타일이 모두 96개 필요했어요. 이 게시판의 세로 길이는 몇 cm인가요?","options":[{"t":"20 cm","correct":true},{"t":"8 cm","mis":"M6-2-u1-X18"},{"t":"12 cm","mis":"M6-2-u1-X18"},{"t":"240 cm","mis":"M6-2-u1-X18"}],"explanation":["가로에는 30 ÷ ⟨2 1/2⟩ = 12개예요.","96 ÷ 12 = 8줄이에요.","세로는 ⟨2 1/2⟩ × 8 = 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#1','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C1',1,'mc','auto','잼 ⟨3/5⟩ kg을 유리병 하나에 ⟨1/5⟩ kg씩 나누어 담으려고 해요. 필요한 유리병의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"잼 ⟨3/5⟩ kg을 유리병 하나에 ⟨1/5⟩ kg씩 나누어 담으려고 해요. 필요한 유리병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨3/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨3/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨3/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨3/5⟩에서 ⟨1/5⟩씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈이에요.","나누어지는 양이 앞, 얼마씩이 뒤 — ⟨3/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#2','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C1',2,'ox','auto','⟨3/5⟩ ÷ ⟨1/5⟩은 「⟨3/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.',ARRAY['M6-2-u1-X03']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"ox","stem":"⟨3/5⟩ ÷ ⟨1/5⟩은 「⟨3/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.","answer":"O","reason_options":[{"t":"같은 종류의 양으로 몇 번 덜어 낼 수 있는지 묻는 것이 나눗셈이어서","correct":true},{"t":"나누는 수가 분수이면 덜어 내기가 아니라 곱하기여서","mis":"M6-2-u1-X03"}],"mis":"M6-2-u1-X03","explanation":["구슬 6개를 2개씩 담는 6 ÷ 2와 같은 물음이에요.","⟨3/5⟩은 ⟨1/5⟩이 3개라 ⟨1/5⟩씩 3번 덜어 낼 수 있어요.","단위가 분수여도 묻는 방식은 그대로예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":3,"grp":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#3','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C2',1,'mc','auto','⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨1/4⟩의 몫은 얼마인가요?","explanation":["⟨3/4⟩은 ⟨1/4⟩이 3개, ⟨1/4⟩은 ⟨1/4⟩이 1개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 3 ÷ 1 = 3.","분모 4는 답에 남지 않아요. 몫은 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"3","correct":true},{"t":"⟨3/4⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"},{"t":"2","mis":"M6-2-u1-X03"}],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"grp":1,"label":"⟨3/4⟩에서 ⟨1/4⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#4','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C2',2,'sa','auto','색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"색 모래 ⟨10/20⟩ kg을 친구 하나에 ⟨2/20⟩ kg씩 나누어 담으려고 해요. 친구는 몇 명 필요한가요? 숫자로 쓰세요.","explanation":["⟨10/20⟩을 ⟨2/20⟩씩 나누는 식은 ⟨10/20⟩ ÷ ⟨2/20⟩예요.","분모가 같으니 분자끼리 나눠요 — 10 ÷ 2 = 5.","친구는 5명 필요해요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["5","5명"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#5','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C2',3,'mc','auto','⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨14/15⟩ ÷ ⟨□/15⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 14 ÷ □예요.","14를 나누어떨어지게 하는 수를 찾아요.","14 ÷ 7 = 2라 □는 7이에요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"7","correct":true},{"t":"9","mis":"M6-2-u1-X02"},{"t":"12","mis":"M6-2-u1-X02"},{"t":"4","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#6','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C3',1,'mc','auto','⟨3/10⟩ ÷ ⟨7/10⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨3/10⟩ ÷ ⟨7/10⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 3 ÷ 7.","나누어떨어지지 않으면 몫을 분수로 적어요 — 3 ÷ 7 = ⟨3/7⟩.","몫 ⟨3/7⟩은 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M6-2-u1-X05"},{"t":"⟨4/10⟩","mis":"M6-2-u1-X03"},{"t":"⟨3/70⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":10,"num":3,"grp":7,"label":"⟨3/10⟩에서 ⟨7/10⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#7','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C3',2,'sa','auto','⟨5/7⟩ ÷ ⟨2/7⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨5/7⟩ ÷ ⟨2/7⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.","explanation":["분자끼리 나누면 5 ÷ 2 = ⟨5/2⟩예요.","더 약분할 수 없어요.","분자와 분모의 합은 7이에요."],"variant_rule":{"fd":{"ask":"same","form":"sum"}},"answer":["7"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#8','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C3',3,'error','auto','⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X20']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":3,"kind":"error","stem":"⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨1/2⟩은 ⟨1/2⟩ L가 남았다는 뜻이야.」","correct":true,"mis_target":"M6-2-u1-X04"},{"t":"서아 — 「가득 찬 컵이 2컵이야.」","mis":"M6-2-u1-X20"},{"t":"지호 — 「몫은 컵의 수를 나타내.」","mis":"M6-2-u1-X20"}],"explanation":["⟨5/6⟩에서 ⟨2/6⟩를 2번 덜어 내면 ⟨1/6⟩ L가 남아요.","남은 ⟨1/6⟩ L는 한 컵 ⟨2/6⟩의 ⟨1/2⟩이에요.","⟨1/2⟩은 남은 양이 아니라 컵 하나의 얼마만큼인지를 뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#9','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C4',1,'mc','auto','⟨2/5⟩ ÷ ⟨2/15⟩를 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨2/15⟩를 통분한 것은 어느 것인가요?","explanation":["5와 15의 최소공배수 15를 공통분모로 해요.","⟨2/5⟩는 ⟨6/15⟩, ⟨2/15⟩는 ⟨2/15⟩가 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨6/15⟩ ÷ ⟨2/15⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨6/15⟩ ÷ ⟨2/15⟩","correct":true},{"t":"⟨2/15⟩ ÷ ⟨2/15⟩","mis":"M6-2-u1-X07"},{"t":"⟨2/5⟩ ÷ ⟨2/15⟩","mis":"M6-2-u1-X07"},{"t":"⟨30/15⟩ ÷ ⟨10/15⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#10','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C4',2,'mc','auto','⟨3/4⟩ ÷ ⟨2/5⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨2/5⟩의 몫은 얼마인가요?","explanation":["분모가 다르니 먼저 통분해요 — ⟨15/20⟩ ÷ ⟨8/20⟩.","분자끼리 나누면 15 ÷ 8 = ⟨15/8⟩ = ⟨1 7/8⟩이에요.","그래서 몫은 ⟨1 7/8⟩이에요."],"variant_rule":{"fd":{"ask":"diff","form":"ans"}},"options":[{"t":"⟨1 7/8⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X06"},{"t":"⟨8/15⟩","mis":"M6-2-u1-X05"},{"t":"⟨3/10⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#11','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C4',3,'mc','auto','종이 팩 무게는 ⟨7/9⟩ kg, 우유 팩 무게는 ⟨7/12⟩ kg이에요. 종이 팩 무게는 우유 팩 무게의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":11,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"종이 팩 무게는 ⟨7/9⟩ kg, 우유 팩 무게는 ⟨7/12⟩ kg이에요. 종이 팩 무게는 우유 팩 무게의 몇 배인가요?","explanation":["몇 배인지는 ⟨7/9⟩ ÷ ⟨7/12⟩로 구해요.","통분하면 ⟨28/36⟩ ÷ ⟨21/36⟩ = 28 ÷ 21이에요.","그래서 ⟨1 1/3⟩배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"⟨1 1/3⟩배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨3/4⟩배","mis":"M6-2-u1-X05"},{"t":"⟨49/108⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#12','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C5',1,'sa','auto','9 ÷ ⟨1/6⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"9 ÷ ⟨1/6⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/6⟩은 1 안에 6번 들어가요.","9 안에는 6번씩 9개 — 9 × 6이에요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 54예요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["54"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#13','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C5',2,'ox','auto','5 ÷ ⟨1/3⟩의 몫은 5보다 커요.',ARRAY['M6-2-u1-X09']::text[],false,'{"seq":13,"concept":"M6-2-u1-C5","difficulty":2,"kind":"ox","stem":"5 ÷ ⟨1/3⟩의 몫은 5보다 커요.","answer":"O","reason_options":[{"t":"⟨1/3⟩은 1보다 작은 수라 5 안에 여러 번(15번) 들어가서","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아져서","mis":"M6-2-u1-X09"}],"mis":"M6-2-u1-X09","explanation":["⟨1/3⟩은 1 안에 3번 들어가요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15예요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#14','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C5',3,'sa','auto','로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 1시간 동안에는 몇 L를 만들 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"로봇이 주스 5 L를 만드는 데 ⟨1/3⟩시간이 걸렸어요. 1시간 동안에는 몇 L를 만들 수 있나요? 숫자로 쓰세요.","explanation":["1시간은 ⟨1/3⟩시간의 3배예요.","5 ÷ ⟨1/3⟩ = 5 × 3 = 15예요.","그래서 1시간 동안에는 15 L예요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["15","15L"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#15','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C6',1,'mc','auto','4 ÷ ⟨2/3⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X01']::text[],true,'{"seq":15,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"4 ÷ ⟨2/3⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["4 ÷ ⟨2/3⟩는 4를 2로 나누고 3을 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨3/2⟩을 곱하는 것과 같아요.","나누는 분수의 분모와 분자를 바꾸어 곱해요 — 4 × ⟨3/2⟩."],"variant_rule":{"fd":{"ask":"nfrac","form":"expr"}},"options":[{"t":"4 × ⟨3/2⟩","correct":true},{"t":"4 × ⟨2/3⟩","mis":"M6-2-u1-X10"},{"t":"4 ÷ 3 × 2","mis":"M6-2-u1-X11"},{"t":"⟨3/2⟩ ÷ 4","mis":"M6-2-u1-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#16','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C6',2,'mc','auto','5 ÷ ⟨2/3⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":16,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"5 ÷ ⟨2/3⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 5 × ⟨3/2⟩.","5 × 3 = 15, 15 ÷ 2 = ⟨15/2⟩ = ⟨7 1/2⟩이에요.","그래서 몫은 ⟨7 1/2⟩이에요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans","exact":false}},"options":[{"t":"⟨7 1/2⟩","correct":true},{"t":"⟨3 1/3⟩","mis":"M6-2-u1-X10"},{"t":"⟨5/6⟩","mis":"M6-2-u1-X11"},{"t":"10","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#17','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C6',3,'sa','auto','자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"자전거를 타고 4 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","explanation":["⟨1/3⟩시간 동안에는 4 ÷ 2 = 2 km를 가요.","1시간은 ⟨1/3⟩시간의 3배라 2 × 3 = 6이에요.","4 ÷ ⟨2/3⟩ = 4 × ⟨3/2⟩ = 6 — 6 km예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["6","6km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#18','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C7',1,'mc','auto','⟨2/5⟩ ÷ ⟨3/4⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X12']::text[],true,'{"seq":18,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨3/4⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["나누는 분수 ⟨3/4⟩만 분모와 분자를 바꿔요.","나누어지는 분수 ⟨2/5⟩는 그대로 두어야 양이 바뀌지 않아요.","그래서 ⟨2/5⟩ × ⟨4/3⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"expr"}},"options":[{"t":"⟨2/5⟩ × ⟨4/3⟩","correct":true},{"t":"⟨2/5⟩ × ⟨3/4⟩","mis":"M6-2-u1-X12"},{"t":"⟨5/2⟩ × ⟨4/3⟩","mis":"M6-2-u1-X12"},{"t":"⟨5/2⟩ × ⟨3/4⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#19','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C7',2,'mc','auto','⟨2/5⟩ ÷ ⟨3/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":19,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨3/4⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — ⟨2/5⟩ × ⟨4/3⟩.","분자끼리, 분모끼리 곱하면 ⟨8/15⟩이에요.","그래서 몫은 ⟨8/15⟩이에요."],"variant_rule":{"fd":{"ask":"mul","form":"ans"}},"options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨3/10⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 7/8⟩","mis":"M6-2-u1-X05"},{"t":"⟨3 1/3⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#20','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C7',3,'error','auto','⟨8/15⟩ ÷ ⟨4/5⟩를 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":20,"concept":"M6-2-u1-C7","difficulty":3,"kind":"error","stem":"⟨8/15⟩ ÷ ⟨4/5⟩를 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨8/15⟩ × ⟨5/4⟩ = ⟨2/3⟩야.」","correct":true,"mis_target":"M6-2-u1-X12"},{"t":"준서 — 「⟨8/15⟩ × ⟨4/5⟩ = ⟨32/75⟩야.」","mis":"M6-2-u1-X12"},{"t":"가은 — 「⟨15/8⟩ × ⟨5/4⟩ = ⟨75/32⟩야.」","mis":"M6-2-u1-X12"}],"explanation":["나누는 분수 ⟨4/5⟩만 뒤집어 ⟨8/15⟩ × ⟨5/4⟩예요.","분자끼리, 분모끼리 곱하면 ⟨2/3⟩예요.","준서는 뒤집지 않았고 가은이는 두 분수를 다 뒤집었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#21','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',1,'mc','auto','⟨2 5/6⟩를 가분수로 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u1-X14']::text[],true,'{"seq":21,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨2 5/6⟩를 가분수로 바르게 고친 것은 어느 것인가요?","explanation":["⟨2 5/6⟩는 2와 ⟨5/6⟩를 더한 수예요.","2는 ⟨12/6⟩니 2 × 6 + 5 = 17이 분자예요.","가분수로 고치면 ⟨17/6⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"options":[{"t":"⟨17/6⟩","correct":true},{"t":"⟨7/6⟩","mis":"M6-2-u1-X14"},{"t":"⟨16/6⟩","mis":"M6-2-u1-X14"},{"t":"⟨12/6⟩","mis":"M6-2-u1-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#22','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',2,'mc','auto','⟨1 4/5⟩ ÷ ⟨1 1/2⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":22,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨1 4/5⟩ ÷ ⟨1 1/2⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨9/5⟩ ÷ ⟨3/2⟩.","⟨9/5⟩ × ⟨2/3⟩ = ⟨18/15⟩ = ⟨6/5⟩ = ⟨1 1/5⟩이에요.","그래서 몫은 ⟨1 1/5⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans2"}},"options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨2 3/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨5 2/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨5/6⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#23','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C8',4,'mc','auto','어떤 수를 ⟨5 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 3/4⟩이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨5 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨2 3/4⟩이 되었어요. 어떤 수는 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨5 1/2⟩ = ⟨2 3/4⟩이에요.","□ = ⟨2 3/4⟩ ÷ ⟨5 1/2⟩ = ⟨2 3/4⟩ × ⟨2/11⟩ = ⟨1/2⟩이에요.","그래서 어떤 수는 ⟨1/2⟩이에요."],"variant_rule":{"fd":{"ask":"back","form":"x"}},"options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/11⟩","mis":"M6-2-u1-X19"},{"t":"⟨15 1/8⟩","mis":"M6-2-u1-X19"},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#24','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C9',4,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 가로 60 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u1-C9","difficulty":4,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 가로 60 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 60 ÷ ⟨7 1/2⟩로 구해요.","⟨7 1/2⟩ = ⟨15/2⟩니 60 ÷ ⟨15/2⟩ = 60 × ⟨2/15⟩ = 8이에요.","그래서 8개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["8","8개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_a#25','math',6,2,'u1','','g6_2_math_u1_review_a','unit_review','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 게시판을 가득 꾸미려고 해요. 타일 100개로 충분한지 계산 과정과 함께 판단해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일로 가로 60 cm, 세로 ⟨82 1/2⟩ cm인 게시판을 가득 꾸미려고 해요. 타일 100개로 충분한지 계산 과정과 함께 판단해 보세요.","answer_guide":{"answer":"예: 가로에 8개, 세로에 11개가 들어가므로 필요한 타일은 8 × 11 = 88개이다. 100개로 충분하다.","scoring_points":["가로 8개를 구했는가","세로 11개를 구했는가","8 × 11 = 88개로 충분하다고 판단했는가"]},"explanation":["가로·세로에 들어가는 개수는 길이 ÷ 타일 한 변이에요.","필요한 타일은 8 × 11 = 88개예요.","100개면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#1','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C1',1,'mc','auto','끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 담으려고 해요. 필요한 편지의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 담으려고 해요. 필요한 편지의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨4/5⟩ ÷ ⟨1/5⟩","correct":true},{"t":"⟨1/5⟩ ÷ ⟨4/5⟩","mis":"M6-2-u1-X01"},{"t":"⟨4/5⟩ × ⟨1/5⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/5⟩ − ⟨1/5⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨4/5⟩에서 ⟨1/5⟩씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈이에요.","나누어지는 양이 앞, 얼마씩이 뒤 — ⟨4/5⟩ ÷ ⟨1/5⟩이에요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#2','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C1',2,'ox','auto','⟨4/5⟩ ÷ ⟨1/5⟩은 「⟨4/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.',ARRAY['M6-2-u1-X03']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"ox","stem":"⟨4/5⟩ ÷ ⟨1/5⟩은 「⟨4/5⟩에서 ⟨1/5⟩을 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.","answer":"O","reason_options":[{"t":"같은 종류의 양으로 몇 번 덜어 낼 수 있는지 묻는 것이 나눗셈이어서","correct":true},{"t":"나누는 수가 분수이면 덜어 내기가 아니라 곱하기여서","mis":"M6-2-u1-X03"}],"mis":"M6-2-u1-X03","explanation":["구슬 6개를 2개씩 담는 6 ÷ 2와 같은 물음이에요.","⟨4/5⟩는 ⟨1/5⟩이 4개라 ⟨1/5⟩씩 4번 덜어 낼 수 있어요.","단위가 분수여도 묻는 방식은 그대로예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"grp":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#3','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C2',1,'mc','auto','⟨12/13⟩ ÷ ⟨3/13⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨12/13⟩ ÷ ⟨3/13⟩의 몫은 얼마인가요?","explanation":["⟨12/13⟩는 ⟨1/13⟩이 12개, ⟨3/13⟩은 ⟨1/13⟩이 3개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 12 ÷ 3 = 4.","분모 13은 답에 남지 않아요. 몫은 4예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"4","correct":true},{"t":"⟨4/13⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/4⟩","mis":"M6-2-u1-X05"},{"t":"9","mis":"M6-2-u1-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#4','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C2',2,'sa','auto','물 ⟨8/9⟩ L를 컵 하나에 ⟨2/9⟩ L씩 나누어 담으려고 해요. 컵은 몇 컵 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"물 ⟨8/9⟩ L를 컵 하나에 ⟨2/9⟩ L씩 나누어 담으려고 해요. 컵은 몇 컵 필요한가요? 숫자로 쓰세요.","explanation":["⟨8/9⟩을 ⟨2/9⟩씩 나누는 식은 ⟨8/9⟩ ÷ ⟨2/9⟩예요.","분모가 같으니 분자끼리 나눠요 — 8 ÷ 2 = 4.","컵은 4컵 필요해요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["4","4컵"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#5','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C2',3,'mc','auto','⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨9/11⟩ ÷ ⟨□/11⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 9 ÷ □예요.","9를 나누어떨어지게 하는 수를 찾아요.","9 ÷ 3 = 3이라 □는 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"3","correct":true},{"t":"7","mis":"M6-2-u1-X02"},{"t":"8","mis":"M6-2-u1-X02"},{"t":"4","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#6','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C3',1,'mc','auto','⟨4/13⟩ ÷ ⟨11/13⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨4/13⟩ ÷ ⟨11/13⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 4 ÷ 11.","나누어떨어지지 않으면 몫을 분수로 적어요 — 4 ÷ 11 = ⟨4/11⟩.","몫 ⟨4/11⟩는 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨4/11⟩","correct":true},{"t":"⟨2 3/4⟩","mis":"M6-2-u1-X05"},{"t":"⟨7/13⟩","mis":"M6-2-u1-X03"},{"t":"⟨4/143⟩","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#7','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C3',2,'sa','auto','⟨13/15⟩ ÷ ⟨8/15⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨13/15⟩ ÷ ⟨8/15⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.","explanation":["분자끼리 나누면 13 ÷ 8 = ⟨13/8⟩이에요.","더 약분할 수 없어요.","분자와 분모의 합은 21이에요."],"variant_rule":{"fd":{"ask":"same","form":"sum"}},"answer":["21"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#8','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C3',3,'error','auto','⟨7/8⟩ ÷ ⟨3/8⟩ = ⟨2 1/3⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X20']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":3,"kind":"error","stem":"⟨7/8⟩ ÷ ⟨3/8⟩ = ⟨2 1/3⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨1/3⟩은 ⟨1/3⟩ L가 남았다는 뜻이야.」","correct":true,"mis_target":"M6-2-u1-X04"},{"t":"서아 — 「가득 찬 컵이 2컵이야.」","mis":"M6-2-u1-X20"},{"t":"지호 — 「몫은 컵의 수를 나타내.」","mis":"M6-2-u1-X20"}],"explanation":["⟨7/8⟩에서 ⟨3/8⟩을 2번 덜어 내면 ⟨1/8⟩ L가 남아요.","남은 ⟨1/8⟩ L는 한 컵 ⟨3/8⟩의 ⟨1/3⟩이에요.","⟨1/3⟩은 남은 양이 아니라 컵 하나의 얼마만큼인지를 뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#9','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C4',1,'mc','auto','⟨8/9⟩ ÷ ⟨5/8⟩를 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨8/9⟩ ÷ ⟨5/8⟩를 통분한 것은 어느 것인가요?","explanation":["9와 8의 최소공배수 72를 공통분모로 해요.","⟨8/9⟩은 ⟨64/72⟩, ⟨5/8⟩는 ⟨45/72⟩가 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨64/72⟩ ÷ ⟨45/72⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨64/72⟩ ÷ ⟨45/72⟩","correct":true},{"t":"⟨8/72⟩ ÷ ⟨5/72⟩","mis":"M6-2-u1-X07"},{"t":"⟨64/72⟩ ÷ ⟨5/8⟩","mis":"M6-2-u1-X07"},{"t":"⟨8/9⟩ ÷ ⟨45/72⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#10','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C4',2,'mc','auto','⟨2/3⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨2/3⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?","explanation":["분모가 다르니 먼저 통분해요 — ⟨14/21⟩ ÷ ⟨6/21⟩.","분자끼리 나누면 14 ÷ 6 = ⟨7/3⟩ = ⟨2 1/3⟩이에요.","그래서 몫은 ⟨2 1/3⟩이에요."],"variant_rule":{"fd":{"ask":"diff","form":"ans"}},"options":[{"t":"⟨2 1/3⟩","correct":true},{"t":"1","mis":"M6-2-u1-X06"},{"t":"⟨3/7⟩","mis":"M6-2-u1-X05"},{"t":"⟨4/21⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#11','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C4',3,'mc','auto','대파 길이는 ⟨3/4⟩ m, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":11,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"대파 길이는 ⟨3/4⟩ m, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인가요?","explanation":["몇 배인지는 ⟨3/4⟩ ÷ ⟨3/8⟩으로 구해요.","통분하면 ⟨6/8⟩ ÷ ⟨3/8⟩ = 6 ÷ 3이에요.","그래서 2배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"2배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨1/2⟩배","mis":"M6-2-u1-X05"},{"t":"⟨9/32⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#12','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',1,'sa','auto','5 ÷ ⟨1/3⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"5 ÷ ⟨1/3⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/3⟩은 1 안에 3번 들어가요.","5 안에는 3번씩 5개 — 5 × 3이에요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 15예요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#13','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',2,'ox','auto','4 ÷ ⟨1/2⟩의 몫은 4보다 커요.',ARRAY['M6-2-u1-X09']::text[],false,'{"seq":13,"concept":"M6-2-u1-C5","difficulty":2,"kind":"ox","stem":"4 ÷ ⟨1/2⟩의 몫은 4보다 커요.","answer":"O","reason_options":[{"t":"⟨1/2⟩은 1보다 작은 수라 4 안에 여러 번(8번) 들어가서","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아져서","mis":"M6-2-u1-X09"}],"mis":"M6-2-u1-X09","explanation":["⟨1/2⟩은 1 안에 2번 들어가요.","4 ÷ ⟨1/2⟩ = 4 × 2 = 8이에요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#14','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C5',3,'sa','auto','물 3 L를 한 컵에 ⟨1/5⟩ L씩 나누어 담으면 컵은 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"물 3 L를 한 컵에 ⟨1/5⟩ L씩 나누어 담으면 컵은 몇 개 필요한가요? 숫자로 쓰세요.","explanation":["3 L를 ⟨1/5⟩ L씩 나누는 식은 3 ÷ ⟨1/5⟩이에요.","3 ÷ ⟨1/5⟩ = 3 × 5 = 15예요.","컵은 15개 필요해요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["15","15개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#15','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C6',1,'mc','auto','9 ÷ ⟨3/7⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X01']::text[],true,'{"seq":15,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"9 ÷ ⟨3/7⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["9 ÷ ⟨3/7⟩은 9를 3으로 나누고 7을 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨7/3⟩을 곱하는 것과 같아요.","나누는 분수의 분모와 분자를 바꾸어 곱해요 — 9 × ⟨7/3⟩."],"variant_rule":{"fd":{"ask":"nfrac","form":"expr"}},"options":[{"t":"9 × ⟨7/3⟩","correct":true},{"t":"9 × ⟨3/7⟩","mis":"M6-2-u1-X10"},{"t":"9 ÷ 7 × 3","mis":"M6-2-u1-X11"},{"t":"⟨7/3⟩ ÷ 9","mis":"M6-2-u1-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#16','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C6',2,'mc','auto','7 ÷ ⟨4/5⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":16,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"7 ÷ ⟨4/5⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 7 × ⟨5/4⟩.","7 × 5 = 35, 35 ÷ 4 = ⟨35/4⟩ = ⟨8 3/4⟩이에요.","그래서 몫은 ⟨8 3/4⟩이에요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans","exact":false}},"options":[{"t":"⟨8 3/4⟩","correct":true},{"t":"⟨5 3/5⟩","mis":"M6-2-u1-X10"},{"t":"⟨7/20⟩","mis":"M6-2-u1-X11"},{"t":"28","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#17','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C6',3,'sa','auto','자전거를 타고 12 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"자전거를 타고 12 km를 가는 데 ⟨2/3⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 갈 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","explanation":["⟨1/3⟩시간 동안에는 12 ÷ 2 = 6 km를 가요.","1시간은 ⟨1/3⟩시간의 3배라 6 × 3 = 18이에요.","12 ÷ ⟨2/3⟩ = 12 × ⟨3/2⟩ = 18 — 18 km예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["18","18km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#18','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',1,'mc','auto','⟨3/10⟩ ÷ ⟨5/8⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X12']::text[],true,'{"seq":18,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨3/10⟩ ÷ ⟨5/8⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["나누는 분수 ⟨5/8⟩만 분모와 분자를 바꿔요.","나누어지는 분수 ⟨3/10⟩은 그대로 두어야 양이 바뀌지 않아요.","그래서 ⟨3/10⟩ × ⟨8/5⟩이에요."],"variant_rule":{"fd":{"ask":"mul","form":"expr"}},"options":[{"t":"⟨3/10⟩ × ⟨8/5⟩","correct":true},{"t":"⟨3/10⟩ × ⟨5/8⟩","mis":"M6-2-u1-X12"},{"t":"⟨10/3⟩ × ⟨8/5⟩","mis":"M6-2-u1-X12"},{"t":"⟨10/3⟩ × ⟨5/8⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#19','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',2,'mc','auto','⟨3/10⟩ ÷ ⟨5/8⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":19,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨3/10⟩ ÷ ⟨5/8⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — ⟨3/10⟩ × ⟨8/5⟩.","분자끼리, 분모끼리 곱하면 ⟨24/50⟩ = ⟨12/25⟩예요.","그래서 몫은 ⟨12/25⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"ans"}},"options":[{"t":"⟨12/25⟩","correct":true},{"t":"⟨3/16⟩","mis":"M6-2-u1-X12"},{"t":"⟨2 1/12⟩","mis":"M6-2-u1-X05"},{"t":"⟨5 1/3⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#20','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C7',3,'error','auto','⟨3/4⟩ ÷ ⟨8/9⟩을 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":20,"concept":"M6-2-u1-C7","difficulty":3,"kind":"error","stem":"⟨3/4⟩ ÷ ⟨8/9⟩을 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨3/4⟩ × ⟨9/8⟩ = ⟨27/32⟩이야.」","correct":true,"mis_target":"M6-2-u1-X12"},{"t":"준서 — 「⟨3/4⟩ × ⟨8/9⟩ = ⟨2/3⟩야.」","mis":"M6-2-u1-X12"},{"t":"가은 — 「⟨4/3⟩ × ⟨9/8⟩ = ⟨36/24⟩이야.」","mis":"M6-2-u1-X12"}],"explanation":["나누는 분수 ⟨8/9⟩만 뒤집어 ⟨3/4⟩ × ⟨9/8⟩예요.","분자끼리, 분모끼리 곱하면 ⟨27/32⟩이에요.","준서는 뒤집지 않았고 가은이는 두 분수를 다 뒤집었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#21','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',1,'mc','auto','⟨1 4/5⟩를 가분수로 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u1-X14']::text[],true,'{"seq":21,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨1 4/5⟩를 가분수로 바르게 고친 것은 어느 것인가요?","explanation":["⟨1 4/5⟩는 1과 ⟨4/5⟩를 더한 수예요.","1은 ⟨5/5⟩니 1 × 5 + 4 = 9가 분자예요.","가분수로 고치면 ⟨9/5⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"options":[{"t":"⟨9/5⟩","correct":true},{"t":"⟨5/5⟩","mis":"M6-2-u1-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#22','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',2,'mc','auto','⟨1 1/3⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":22,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨1 1/3⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨4/3⟩ ÷ ⟨2/7⟩.","⟨4/3⟩ × ⟨7/2⟩ = ⟨28/6⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","그래서 몫은 ⟨4 2/3⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans"}},"options":[{"t":"⟨4 2/3⟩","correct":true},{"t":"⟨2 1/6⟩","mis":"M6-2-u1-X13"},{"t":"⟨8/21⟩","mis":"M6-2-u1-X12"},{"t":"⟨3/14⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#23','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C8',4,'mc','auto','어떤 수를 ⟨2 1/3⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨1 3/4⟩이 되었어요. 어떤 수는 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨2 1/3⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨1 3/4⟩이 되었어요. 어떤 수는 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨2 1/3⟩ = ⟨1 3/4⟩이에요.","□ = ⟨1 3/4⟩ ÷ ⟨2 1/3⟩ = ⟨1 3/4⟩ × ⟨3/7⟩ = ⟨3/4⟩이에요.","그래서 어떤 수는 ⟨3/4⟩이에요."],"variant_rule":{"fd":{"ask":"back","form":"x"}},"options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨9/28⟩","mis":"M6-2-u1-X19"},{"t":"⟨4 1/12⟩","mis":"M6-2-u1-X19"},{"t":"⟨1 3/4⟩","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#24','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C9',4,'sa','auto','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 게시판의 세로 140 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u1-C9","difficulty":4,"kind":"sa","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일을 게시판의 세로 140 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 140 ÷ ⟨8 3/4⟩으로 구해요.","⟨8 3/4⟩ = ⟨35/4⟩니 140 ÷ ⟨35/4⟩ = 140 × ⟨4/35⟩ = 16이에요.","그래서 16개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["16","16개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_b#25','math',6,2,'u1','','g6_2_math_u1_review_b','unit_review','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 가로 350 cm, 세로 140 cm인 벽을 가득 꾸미려고 해요. 타일 600개로 충분한지 계산 과정과 함께 판단해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨8 3/4⟩ cm인 정사각형 타일로 가로 350 cm, 세로 140 cm인 벽을 가득 꾸미려고 해요. 타일 600개로 충분한지 계산 과정과 함께 판단해 보세요.","answer_guide":{"answer":"예: 가로에 40개, 세로에 16개가 들어가므로 필요한 타일은 40 × 16 = 640개이다. 600개로 모자란다.","scoring_points":["가로 40개를 구했는가","세로 16개를 구했는가","40 × 16 = 640개로 모자라다고 판단했는가"]},"explanation":["가로·세로에 들어가는 개수는 길이 ÷ 타일 한 변이에요.","필요한 타일은 40 × 16 = 640개예요.","600개면 모자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#1','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C1',1,'mc','auto','물 ⟨8/9⟩ L를 컵 하나에 ⟨2/9⟩ L씩 나누어 담으려고 해요. 필요한 컵의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"물 ⟨8/9⟩ L를 컵 하나에 ⟨2/9⟩ L씩 나누어 담으려고 해요. 필요한 컵의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨8/9⟩ ÷ ⟨2/9⟩","correct":true},{"t":"⟨2/9⟩ ÷ ⟨8/9⟩","mis":"M6-2-u1-X01"},{"t":"⟨8/9⟩ × ⟨2/9⟩","mis":"M6-2-u1-X03"},{"t":"⟨8/9⟩ − ⟨2/9⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨8/9⟩에서 ⟨2/9⟩씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈이에요.","나누어지는 양이 앞, 얼마씩이 뒤 — ⟨8/9⟩ ÷ ⟨2/9⟩예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#2','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C1',2,'ox','auto','⟨8/9⟩ ÷ ⟨2/9⟩는 「⟨8/9⟩에서 ⟨2/9⟩를 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.',ARRAY['M6-2-u1-X03']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"ox","stem":"⟨8/9⟩ ÷ ⟨2/9⟩는 「⟨8/9⟩에서 ⟨2/9⟩를 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.","answer":"O","reason_options":[{"t":"같은 종류의 양으로 몇 번 덜어 낼 수 있는지 묻는 것이 나눗셈이어서","correct":true},{"t":"나누는 수가 분수이면 덜어 내기가 아니라 곱하기여서","mis":"M6-2-u1-X03"}],"mis":"M6-2-u1-X03","explanation":["구슬 6개를 2개씩 담는 6 ÷ 2와 같은 물음이에요.","⟨8/9⟩은 ⟨1/9⟩이 8개라 ⟨2/9⟩씩 4번 덜어 낼 수 있어요.","단위가 분수여도 묻는 방식은 그대로예요."],"asset":{"type":"fbar","bars":[{"den":9,"num":8,"grp":2}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#3','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C2',1,'mc','auto','⟨6/7⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨6/7⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?","explanation":["⟨6/7⟩은 ⟨1/7⟩이 6개, ⟨2/7⟩는 ⟨1/7⟩이 2개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 6 ÷ 2 = 3.","분모 7은 답에 남지 않아요. 몫은 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"3","correct":true},{"t":"⟨3/7⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/3⟩","mis":"M6-2-u1-X05"},{"t":"4","mis":"M6-2-u1-X03"}],"asset":{"type":"fbar","bars":[{"den":7,"num":6,"grp":2,"label":"⟨6/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#4','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C2',2,'sa','auto','끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 쓰려고 해요. 편지는 몇 장 꾸밀 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"끈 ⟨4/5⟩ m를 편지 하나에 ⟨1/5⟩ m씩 나누어 쓰려고 해요. 편지는 몇 장 꾸밀 수 있나요? 숫자로 쓰세요.","explanation":["⟨4/5⟩를 ⟨1/5⟩씩 나누는 식은 ⟨4/5⟩ ÷ ⟨1/5⟩이에요.","분모가 같으니 분자끼리 나눠요 — 4 ÷ 1 = 4.","편지는 4장 꾸밀 수 있어요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["4","4장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#5','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C2',3,'mc','auto','⟨12/13⟩ ÷ ⟨□/13⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨12/13⟩ ÷ ⟨□/13⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 12 ÷ □예요.","12를 나누어떨어지게 하는 수를 찾아요.","12 ÷ 2 = 6이라 □는 2예요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"2","correct":true},{"t":"7","mis":"M6-2-u1-X02"},{"t":"5","mis":"M6-2-u1-X02"},{"t":"9","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#6','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C3',1,'mc','auto','⟨5/7⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨5/7⟩ ÷ ⟨2/7⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 5 ÷ 2.","나누어떨어지지 않으면 몫을 분수로 적어요 — 5 ÷ 2 = ⟨5/2⟩ = ⟨2 1/2⟩.","몫 ⟨2 1/2⟩은 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨2/5⟩","mis":"M6-2-u1-X05"},{"t":"⟨3/7⟩","mis":"M6-2-u1-X03"},{"t":"⟨5/14⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":7,"num":5,"grp":2,"label":"⟨5/7⟩에서 ⟨2/7⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#7','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C3',2,'sa','auto','⟨9/11⟩ ÷ ⟨4/11⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨9/11⟩ ÷ ⟨4/11⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.","explanation":["분자끼리 나누면 9 ÷ 4 = ⟨9/4⟩예요.","더 약분할 수 없어요.","분자와 분모의 합은 13이에요."],"variant_rule":{"fd":{"ask":"same","form":"sum"}},"answer":["13"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#8','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C3',3,'error','auto','⟨7/9⟩ ÷ ⟨2/9⟩ = ⟨3 1/2⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X20']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":3,"kind":"error","stem":"⟨7/9⟩ ÷ ⟨2/9⟩ = ⟨3 1/2⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨1/2⟩은 ⟨1/2⟩ L가 남았다는 뜻이야.」","correct":true,"mis_target":"M6-2-u1-X04"},{"t":"서아 — 「가득 찬 컵이 3컵이야.」","mis":"M6-2-u1-X20"},{"t":"지호 — 「몫은 컵의 수를 나타내.」","mis":"M6-2-u1-X20"}],"explanation":["⟨7/9⟩에서 ⟨2/9⟩를 3번 덜어 내면 ⟨1/9⟩ L가 남아요.","남은 ⟨1/9⟩ L는 한 컵 ⟨2/9⟩의 ⟨1/2⟩이에요.","⟨1/2⟩은 남은 양이 아니라 컵 하나의 얼마만큼인지를 뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#9','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',1,'mc','auto','⟨1/3⟩ ÷ ⟨5/6⟩를 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨1/3⟩ ÷ ⟨5/6⟩를 통분한 것은 어느 것인가요?","explanation":["3과 6의 최소공배수 6을 공통분모로 해요.","⟨1/3⟩은 ⟨2/6⟩, ⟨5/6⟩는 ⟨5/6⟩가 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨2/6⟩ ÷ ⟨5/6⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨2/6⟩ ÷ ⟨5/6⟩","correct":true},{"t":"⟨1/6⟩ ÷ ⟨5/6⟩","mis":"M6-2-u1-X07"},{"t":"⟨1/3⟩ ÷ ⟨5/6⟩","mis":"M6-2-u1-X07"},{"t":"⟨6/6⟩ ÷ ⟨15/6⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#10','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',2,'mc','auto','⟨1/3⟩ ÷ ⟨5/6⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨1/3⟩ ÷ ⟨5/6⟩의 몫은 얼마인가요?","explanation":["분모가 다르니 먼저 통분해요 — ⟨2/6⟩ ÷ ⟨5/6⟩.","분자끼리 나누면 2 ÷ 5 = ⟨2/5⟩예요.","그래서 몫은 ⟨2/5⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"ans"}},"options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1/5⟩","mis":"M6-2-u1-X06"},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/18⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#11','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C4',3,'mc','auto','물 양은 ⟨5/6⟩ L, 주스 양은 ⟨5/9⟩ L예요. 물 양은 주스 양의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":11,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"물 양은 ⟨5/6⟩ L, 주스 양은 ⟨5/9⟩ L예요. 물 양은 주스 양의 몇 배인가요?","explanation":["몇 배인지는 ⟨5/6⟩ ÷ ⟨5/9⟩로 구해요.","통분하면 ⟨15/18⟩ ÷ ⟨10/18⟩ = 15 ÷ 10이에요.","그래서 ⟨1 1/2⟩배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"⟨1 1/2⟩배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨2/3⟩배","mis":"M6-2-u1-X05"},{"t":"⟨25/54⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#12','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C5',1,'sa','auto','11 ÷ ⟨1/4⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"11 ÷ ⟨1/4⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/4⟩은 1 안에 4번 들어가요.","11 안에는 4번씩 11개 — 11 × 4예요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 44예요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["44"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#13','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C5',2,'ox','auto','6 ÷ ⟨1/5⟩의 몫은 6보다 커요.',ARRAY['M6-2-u1-X09']::text[],false,'{"seq":13,"concept":"M6-2-u1-C5","difficulty":2,"kind":"ox","stem":"6 ÷ ⟨1/5⟩의 몫은 6보다 커요.","answer":"O","reason_options":[{"t":"⟨1/5⟩은 1보다 작은 수라 6 안에 여러 번(30번) 들어가서","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아져서","mis":"M6-2-u1-X09"}],"mis":"M6-2-u1-X09","explanation":["⟨1/5⟩은 1 안에 5번 들어가요.","6 ÷ ⟨1/5⟩ = 6 × 5 = 30이에요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#14','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C5',3,'sa','auto','걸어서 8 km를 가는 데 ⟨1/4⟩시간이 걸렸어요. 1시간 동안에는 몇 km를 갈 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"걸어서 8 km를 가는 데 ⟨1/4⟩시간이 걸렸어요. 1시간 동안에는 몇 km를 갈 수 있나요? 숫자로 쓰세요.","explanation":["1시간은 ⟨1/4⟩시간의 4배예요.","8 ÷ ⟨1/4⟩ = 8 × 4 = 32예요.","그래서 1시간 동안에는 32 km예요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["32","32km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#15','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',1,'mc','auto','6 ÷ ⟨4/5⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X01']::text[],true,'{"seq":15,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"6 ÷ ⟨4/5⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["6 ÷ ⟨4/5⟩는 6을 4로 나누고 5를 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨5/4⟩를 곱하는 것과 같아요.","나누는 분수의 분모와 분자를 바꾸어 곱해요 — 6 × ⟨5/4⟩."],"variant_rule":{"fd":{"ask":"nfrac","form":"expr"}},"options":[{"t":"6 × ⟨5/4⟩","correct":true},{"t":"6 × ⟨4/5⟩","mis":"M6-2-u1-X10"},{"t":"6 ÷ 5 × 4","mis":"M6-2-u1-X11"},{"t":"⟨5/4⟩ ÷ 6","mis":"M6-2-u1-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#16','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',2,'mc','auto','9 ÷ ⟨3/7⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":16,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"9 ÷ ⟨3/7⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 9 × ⟨7/3⟩.","9 × 7 = 63, 63 ÷ 3 = 21이에요.","그래서 몫은 21이에요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans"}},"options":[{"t":"21","correct":true},{"t":"⟨3 6/7⟩","mis":"M6-2-u1-X10"},{"t":"⟨3/7⟩","mis":"M6-2-u1-X11"},{"t":"27","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#17','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C6',3,'sa','auto','걸어서 9 km를 가는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 걸을 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"걸어서 9 km를 가는 데 ⟨3/4⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 걸을 수 있는 거리는 몇 km인가요? 숫자로 쓰세요.","explanation":["⟨1/4⟩시간 동안에는 9 ÷ 3 = 3 km를 가요.","1시간은 ⟨1/4⟩시간의 4배라 3 × 4 = 12예요.","9 ÷ ⟨3/4⟩ = 9 × ⟨4/3⟩ = 12 — 12 km예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["12","12km"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#18','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C7',1,'mc','auto','⟨5/8⟩ ÷ ⟨5/9⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X12']::text[],true,'{"seq":18,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨5/8⟩ ÷ ⟨5/9⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["나누는 분수 ⟨5/9⟩만 분모와 분자를 바꿔요.","나누어지는 분수 ⟨5/8⟩는 그대로 두어야 양이 바뀌지 않아요.","그래서 ⟨5/8⟩ × ⟨9/5⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"expr"}},"options":[{"t":"⟨5/8⟩ × ⟨9/5⟩","correct":true},{"t":"⟨5/8⟩ × ⟨5/9⟩","mis":"M6-2-u1-X12"},{"t":"⟨8/5⟩ × ⟨9/5⟩","mis":"M6-2-u1-X12"},{"t":"⟨8/5⟩ × ⟨5/9⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#19','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C7',2,'mc','auto','⟨5/8⟩ ÷ ⟨5/9⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":19,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨5/8⟩ ÷ ⟨5/9⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — ⟨5/8⟩ × ⟨9/5⟩.","분자끼리, 분모끼리 곱하면 ⟨45/40⟩ = ⟨9/8⟩ = ⟨1 1/8⟩이에요.","그래서 몫은 ⟨1 1/8⟩이에요."],"variant_rule":{"fd":{"ask":"mul","form":"ans"}},"options":[{"t":"⟨1 1/8⟩","correct":true},{"t":"⟨25/72⟩","mis":"M6-2-u1-X12"},{"t":"⟨8/9⟩","mis":"M6-2-u1-X05"},{"t":"⟨2 22/25⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#20','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C7',3,'error','auto','⟨5/6⟩ ÷ ⟨7/8⟩을 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":20,"concept":"M6-2-u1-C7","difficulty":3,"kind":"error","stem":"⟨5/6⟩ ÷ ⟨7/8⟩을 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨5/6⟩ × ⟨8/7⟩ = ⟨20/21⟩이야.」","correct":true,"mis_target":"M6-2-u1-X12"},{"t":"준서 — 「⟨5/6⟩ × ⟨7/8⟩ = ⟨35/48⟩야.」","mis":"M6-2-u1-X12"},{"t":"가은 — 「⟨6/5⟩ × ⟨8/7⟩ = ⟨48/35⟩이야.」","mis":"M6-2-u1-X12"}],"explanation":["나누는 분수 ⟨7/8⟩만 뒤집어 ⟨5/6⟩ × ⟨8/7⟩이에요.","분자끼리, 분모끼리 곱하면 ⟨20/21⟩이에요.","준서는 뒤집지 않았고 가은이는 두 분수를 다 뒤집었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#21','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',1,'mc','auto','⟨3 3/8⟩을 가분수로 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u1-X14']::text[],true,'{"seq":21,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨3 3/8⟩을 가분수로 바르게 고친 것은 어느 것인가요?","explanation":["⟨3 3/8⟩은 3과 ⟨3/8⟩을 더한 수예요.","3은 ⟨24/8⟩니 3 × 8 + 3 = 27이 분자예요.","가분수로 고치면 ⟨27/8⟩이에요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"options":[{"t":"⟨27/8⟩","correct":true},{"t":"⟨6/8⟩","mis":"M6-2-u1-X14"},{"t":"⟨17/8⟩","mis":"M6-2-u1-X14"},{"t":"⟨24/8⟩","mis":"M6-2-u1-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#22','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',2,'mc','auto','⟨3 1/3⟩ ÷ ⟨1 5/6⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X05']::text[],true,'{"seq":22,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨3 1/3⟩ ÷ ⟨1 5/6⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨10/3⟩ ÷ ⟨11/6⟩.","⟨10/3⟩ × ⟨6/11⟩ = ⟨60/33⟩ = ⟨20/11⟩ = ⟨1 9/11⟩예요.","그래서 몫은 ⟨1 9/11⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans2"}},"options":[{"t":"⟨1 9/11⟩","correct":true},{"t":"⟨3 2/5⟩","mis":"M6-2-u1-X13"},{"t":"⟨7 1/3⟩","mis":"M6-2-u1-X13"},{"t":"⟨11/20⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#23','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C8',4,'mc','auto','어떤 수를 ⟨1 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 1이 되었어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨1 1/2⟩로 나누어야 할 것을 잘못하여 곱했더니 1이 되었어요. 바르게 계산한 값은 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨1 1/2⟩ = 1이에요.","□ = 1 ÷ ⟨1 1/2⟩ = 1 × ⟨2/3⟩ = ⟨2/3⟩예요.","바르게 계산하면 ⟨2/3⟩ ÷ ⟨1 1/2⟩ = ⟨2/3⟩ × ⟨2/3⟩ = ⟨4/9⟩예요."],"variant_rule":{"fd":{"ask":"back","form":"right"}},"options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨2/3⟩","mis":"M6-2-u1-X19"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X19"},{"t":"1","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#24','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C9',4,'sa','auto','한 변이 ⟨4 1/2⟩ cm인 정사각형 타일을 게시판의 가로 45 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u1-C9","difficulty":4,"kind":"sa","stem":"한 변이 ⟨4 1/2⟩ cm인 정사각형 타일을 게시판의 가로 45 cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 45 ÷ ⟨4 1/2⟩로 구해요.","⟨4 1/2⟩ = ⟨9/2⟩니 45 ÷ ⟨9/2⟩ = 45 × ⟨2/9⟩ = 10이에요.","그래서 10개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["10","10개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_c#25','math',6,2,'u1','','g6_2_math_u1_review_c','unit_review','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨2 1/2⟩ cm인 정사각형 타일로 가로 30 cm, 세로 20 cm인 게시판을 가득 꾸미려고 해요. 타일 100개로 충분한지 계산 과정과 함께 판단해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨2 1/2⟩ cm인 정사각형 타일로 가로 30 cm, 세로 20 cm인 게시판을 가득 꾸미려고 해요. 타일 100개로 충분한지 계산 과정과 함께 판단해 보세요.","answer_guide":{"answer":"예: 가로에 12개, 세로에 8개가 들어가므로 필요한 타일은 12 × 8 = 96개이다. 100개로 충분하다.","scoring_points":["가로 12개를 구했는가","세로 8개를 구했는가","12 × 8 = 96개로 충분하다고 판단했는가"]},"explanation":["가로·세로에 들어가는 개수는 길이 ÷ 타일 한 변이에요.","필요한 타일은 12 × 8 = 96개예요.","100개면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#1','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C1',1,'mc','auto','모래 ⟨9/10⟩ kg을 봉지 하나에 ⟨3/10⟩ kg씩 나누어 담으려고 해요. 필요한 봉지의 수를 구하는 식은 어느 것인가요?',ARRAY['M6-2-u1-X01','M6-2-u1-X03']::text[],false,'{"seq":1,"concept":"M6-2-u1-C1","difficulty":1,"kind":"mc","stem":"모래 ⟨9/10⟩ kg을 봉지 하나에 ⟨3/10⟩ kg씩 나누어 담으려고 해요. 필요한 봉지의 수를 구하는 식은 어느 것인가요?","options":[{"t":"⟨9/10⟩ ÷ ⟨3/10⟩","correct":true},{"t":"⟨3/10⟩ ÷ ⟨9/10⟩","mis":"M6-2-u1-X01"},{"t":"⟨9/10⟩ × ⟨3/10⟩","mis":"M6-2-u1-X03"},{"t":"⟨9/10⟩ − ⟨3/10⟩","mis":"M6-2-u1-X03"}],"explanation":["⟨9/10⟩에서 ⟨3/10⟩씩 덜어 내는 거예요.","같은 양을 몇 번 덜어 낼 수 있는지는 나눗셈이에요.","나누어지는 양이 앞, 얼마씩이 뒤 — ⟨9/10⟩ ÷ ⟨3/10⟩이에요."],"asset":{"type":"fbar","bars":[{"den":10,"num":9,"grp":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#2','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C1',2,'ox','auto','⟨9/10⟩ ÷ ⟨3/10⟩은 「⟨9/10⟩에서 ⟨3/10⟩을 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.',ARRAY['M6-2-u1-X03']::text[],false,'{"seq":2,"concept":"M6-2-u1-C1","difficulty":2,"kind":"ox","stem":"⟨9/10⟩ ÷ ⟨3/10⟩은 「⟨9/10⟩에서 ⟨3/10⟩을 몇 번 덜어 낼 수 있는가」를 묻는 식이에요.","answer":"O","reason_options":[{"t":"같은 종류의 양으로 몇 번 덜어 낼 수 있는지 묻는 것이 나눗셈이어서","correct":true},{"t":"나누는 수가 분수이면 덜어 내기가 아니라 곱하기여서","mis":"M6-2-u1-X03"}],"mis":"M6-2-u1-X03","explanation":["구슬 6개를 2개씩 담는 6 ÷ 2와 같은 물음이에요.","⟨9/10⟩는 ⟨1/10⟩이 9개라 ⟨3/10⟩씩 3번 덜어 낼 수 있어요.","단위가 분수여도 묻는 방식은 그대로예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":9,"grp":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#3','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C2',1,'mc','auto','⟨10/17⟩ ÷ ⟨2/17⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X02','M6-2-u1-X05','M6-2-u1-X03']::text[],true,'{"seq":3,"concept":"M6-2-u1-C2","difficulty":1,"kind":"mc","stem":"⟨10/17⟩ ÷ ⟨2/17⟩의 몫은 얼마인가요?","explanation":["⟨10/17⟩은 ⟨1/17⟩이 10개, ⟨2/17⟩는 ⟨1/17⟩이 2개예요.","같은 크기의 조각이라 개수끼리 나눠요 — 10 ÷ 2 = 5.","분모 17은 답에 남지 않아요. 몫은 5예요."],"variant_rule":{"fd":{"ask":"same","form":"exact"}},"options":[{"t":"5","correct":true},{"t":"⟨5/17⟩","mis":"M6-2-u1-X02"},{"t":"⟨1/5⟩","mis":"M6-2-u1-X05"},{"t":"8","mis":"M6-2-u1-X03"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#4','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C2',2,'sa','auto','비료 ⟨12/15⟩ L를 컵 하나에 ⟨3/15⟩ L씩 나누어 담으려고 해요. 컵은 몇 컵 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u1-C2","difficulty":2,"kind":"sa","stem":"비료 ⟨12/15⟩ L를 컵 하나에 ⟨3/15⟩ L씩 나누어 담으려고 해요. 컵은 몇 컵 필요한가요? 숫자로 쓰세요.","explanation":["⟨12/15⟩를 ⟨3/15⟩씩 나누는 식은 ⟨12/15⟩ ÷ ⟨3/15⟩이에요.","분모가 같으니 분자끼리 나눠요 — 12 ÷ 3 = 4.","컵은 4컵 필요해요."],"variant_rule":{"fd":{"ask":"same","form":"story"}},"answer":["4","4컵"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#5','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C2',3,'mc','auto','⟨15/17⟩ ÷ ⟨□/17⟩의 몫이 자연수가 되는 □는 어느 것인가요?',ARRAY['M6-2-u1-X02']::text[],true,'{"seq":5,"concept":"M6-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨15/17⟩ ÷ ⟨□/17⟩의 몫이 자연수가 되는 □는 어느 것인가요?","explanation":["분모가 같으니 몫은 15 ÷ □예요.","15를 나누어떨어지게 하는 수를 찾아요.","15 ÷ 3 = 5라 □는 3이에요."],"variant_rule":{"fd":{"ask":"same","form":"blank"}},"options":[{"t":"3","correct":true},{"t":"13","mis":"M6-2-u1-X02"},{"t":"4","mis":"M6-2-u1-X02"},{"t":"11","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#6','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C3',1,'mc','auto','⟨9/11⟩ ÷ ⟨4/11⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨9/11⟩ ÷ ⟨4/11⟩의 몫은 얼마인가요?","explanation":["분모가 같으니 분자끼리 나눠요 — 9 ÷ 4.","나누어떨어지지 않으면 몫을 분수로 적어요 — 9 ÷ 4 = ⟨9/4⟩ = ⟨2 1/4⟩.","몫 ⟨2 1/4⟩은 남은 양이 아니라 한 몫의 얼마만큼인지를 뜻해요."],"variant_rule":{"fd":{"ask":"same","form":"frac"}},"options":[{"t":"⟨2 1/4⟩","correct":true},{"t":"⟨4/9⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/11⟩","mis":"M6-2-u1-X03"},{"t":"⟨9/44⟩","mis":"M6-2-u1-X02"}],"asset":{"type":"fbar","bars":[{"den":11,"num":9,"grp":4,"label":"⟨9/11⟩에서 ⟨4/11⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#7','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C3',2,'sa','auto','⟨10/13⟩ ÷ ⟨3/13⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":2,"kind":"sa","stem":"⟨10/13⟩ ÷ ⟨3/13⟩의 몫을 가분수로 나타낼 때 분자와 분모의 합은 얼마인가요? 숫자로 쓰세요.","explanation":["분자끼리 나누면 10 ÷ 3 = ⟨10/3⟩이에요.","더 약분할 수 없어요.","분자와 분모의 합은 13이에요."],"variant_rule":{"fd":{"ask":"same","form":"sum"}},"answer":["13"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#8','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C3',3,'error','auto','⟨11/12⟩ ÷ ⟨4/12⟩ = ⟨2 3/4⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X20']::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":3,"kind":"error","stem":"⟨11/12⟩ ÷ ⟨4/12⟩ = ⟨2 3/4⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨3/4⟩은 ⟨3/4⟩ L가 남았다는 뜻이야.」","correct":true,"mis_target":"M6-2-u1-X04"},{"t":"서아 — 「가득 찬 컵이 2컵이야.」","mis":"M6-2-u1-X20"},{"t":"지호 — 「몫은 컵의 수를 나타내.」","mis":"M6-2-u1-X20"}],"explanation":["⟨11/12⟩에서 ⟨4/12⟩를 2번 덜어 내면 ⟨3/12⟩ L가 남아요.","남은 ⟨3/12⟩ L는 한 컵 ⟨4/12⟩의 ⟨3/4⟩이에요.","⟨3/4⟩은 남은 양이 아니라 컵 하나의 얼마만큼인지를 뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#9','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C4',1,'mc','auto','⟨3/4⟩ ÷ ⟨2/5⟩를 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 통분한 것은 어느 것인가요?","explanation":["4와 5의 최소공배수 20을 공통분모로 해요.","⟨3/4⟩은 ⟨15/20⟩, ⟨2/5⟩는 ⟨8/20⟩이 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨15/20⟩ ÷ ⟨8/20⟩이에요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨15/20⟩ ÷ ⟨8/20⟩","correct":true},{"t":"⟨3/20⟩ ÷ ⟨2/20⟩","mis":"M6-2-u1-X07"},{"t":"⟨15/20⟩ ÷ ⟨2/5⟩","mis":"M6-2-u1-X07"},{"t":"⟨3/4⟩ ÷ ⟨8/20⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#10','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C4',2,'mc','auto','⟨5/6⟩ ÷ ⟨3/4⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨5/6⟩ ÷ ⟨3/4⟩의 몫은 얼마인가요?","explanation":["분모가 다르니 먼저 통분해요 — ⟨10/12⟩ ÷ ⟨9/12⟩.","분자끼리 나누면 10 ÷ 9 = ⟨10/9⟩ = ⟨1 1/9⟩이에요.","그래서 몫은 ⟨1 1/9⟩이에요."],"variant_rule":{"fd":{"ask":"diff","form":"ans"}},"options":[{"t":"⟨1 1/9⟩","correct":true},{"t":"⟨1 2/3⟩","mis":"M6-2-u1-X06"},{"t":"⟨9/10⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/8⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#11','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C4',3,'mc','auto','빨간 끈 길이는 ⟨4/5⟩ m, 파란 끈 길이는 ⟨2/3⟩ m예요. 빨간 끈 길이는 파란 끈 길이의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":11,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"빨간 끈 길이는 ⟨4/5⟩ m, 파란 끈 길이는 ⟨2/3⟩ m예요. 빨간 끈 길이는 파란 끈 길이의 몇 배인가요?","explanation":["몇 배인지는 ⟨4/5⟩ ÷ ⟨2/3⟩로 구해요.","통분하면 ⟨12/15⟩ ÷ ⟨10/15⟩ = 12 ÷ 10이에요.","그래서 ⟨1 1/5⟩배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"⟨1 1/5⟩배","correct":true},{"t":"2배","mis":"M6-2-u1-X06"},{"t":"⟨5/6⟩배","mis":"M6-2-u1-X05"},{"t":"⟨8/15⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#12','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C5',1,'sa','auto','7 ÷ ⟨1/8⟩의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-2-u1-C5","difficulty":1,"kind":"sa","stem":"7 ÷ ⟨1/8⟩의 몫은 얼마인가요? 숫자로 쓰세요.","explanation":["⟨1/8⟩은 1 안에 8번 들어가요.","7 안에는 8번씩 7개 — 7 × 8이에요.","(자연수)÷(단위분수)는 분모를 곱해요. 몫은 56이에요."],"variant_rule":{"fd":{"ask":"nunit","form":"ans"}},"answer":["56"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#13','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C5',2,'ox','auto','3 ÷ ⟨1/7⟩의 몫은 3보다 커요.',ARRAY['M6-2-u1-X09']::text[],false,'{"seq":13,"concept":"M6-2-u1-C5","difficulty":2,"kind":"ox","stem":"3 ÷ ⟨1/7⟩의 몫은 3보다 커요.","answer":"O","reason_options":[{"t":"⟨1/7⟩은 1보다 작은 수라 3 안에 여러 번(21번) 들어가서","correct":true},{"t":"나눗셈을 하면 몫은 늘 나누어지는 수보다 작아져서","mis":"M6-2-u1-X09"}],"mis":"M6-2-u1-X09","explanation":["⟨1/7⟩은 1 안에 7번 들어가요.","3 ÷ ⟨1/7⟩ = 3 × 7 = 21이에요.","1보다 작은 수로 나누면 몫이 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#14','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C5',3,'sa','auto','로봇이 주스 6 L를 만드는 데 ⟨1/7⟩시간이 걸렸어요. 1시간 동안에는 몇 L를 만들 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-2-u1-C5","difficulty":3,"kind":"sa","stem":"로봇이 주스 6 L를 만드는 데 ⟨1/7⟩시간이 걸렸어요. 1시간 동안에는 몇 L를 만들 수 있나요? 숫자로 쓰세요.","explanation":["1시간은 ⟨1/7⟩시간의 7배예요.","6 ÷ ⟨1/7⟩ = 6 × 7 = 42예요.","그래서 1시간 동안에는 42 L예요."],"variant_rule":{"fd":{"ask":"nunit","form":"story"}},"answer":["42","42L"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#15','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',1,'mc','auto','5 ÷ ⟨2/9⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11','M6-2-u1-X01']::text[],true,'{"seq":15,"concept":"M6-2-u1-C6","difficulty":1,"kind":"mc","stem":"5 ÷ ⟨2/9⟩를 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["5 ÷ ⟨2/9⟩는 5를 2로 나누고 9를 곱하는 두 걸음이에요.","두 걸음을 한 번에 적으면 ⟨9/2⟩를 곱하는 것과 같아요.","나누는 분수의 분모와 분자를 바꾸어 곱해요 — 5 × ⟨9/2⟩."],"variant_rule":{"fd":{"ask":"nfrac","form":"expr"}},"options":[{"t":"5 × ⟨9/2⟩","correct":true},{"t":"5 × ⟨2/9⟩","mis":"M6-2-u1-X10"},{"t":"5 ÷ 9 × 2","mis":"M6-2-u1-X11"},{"t":"⟨9/2⟩ ÷ 5","mis":"M6-2-u1-X01"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#16','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',2,'mc','auto','4 ÷ ⟨3/8⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X10','M6-2-u1-X11']::text[],true,'{"seq":16,"concept":"M6-2-u1-C6","difficulty":2,"kind":"mc","stem":"4 ÷ ⟨3/8⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — 4 × ⟨8/3⟩.","4 × 8 = 32, 32 ÷ 3 = ⟨32/3⟩ = ⟨10 2/3⟩예요.","그래서 몫은 ⟨10 2/3⟩예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"ans","exact":false}},"options":[{"t":"⟨10 2/3⟩","correct":true},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X10"},{"t":"⟨1/6⟩","mis":"M6-2-u1-X11"},{"t":"12","mis":"M6-2-u1-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#17','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C6',3,'sa','auto','수도꼭지에서 물 6 L를 받는 데 ⟨3/5⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 받을 수 있는 물은 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-2-u1-C6","difficulty":3,"kind":"sa","stem":"수도꼭지에서 물 6 L를 받는 데 ⟨3/5⟩시간이 걸렸어요. 같은 빠르기로 1시간 동안 받을 수 있는 물은 몇 L인가요? 숫자로 쓰세요.","explanation":["⟨1/5⟩시간 동안에는 6 ÷ 3 = 2 L를 받아요.","1시간은 ⟨1/5⟩시간의 5배라 2 × 5 = 10이에요.","6 ÷ ⟨3/5⟩ = 6 × ⟨5/3⟩ = 10 — 10 L예요."],"variant_rule":{"fd":{"ask":"nfrac","form":"story"}},"answer":["10","10L"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#18','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C7',1,'mc','auto','⟨2/9⟩ ÷ ⟨3/5⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M6-2-u1-X12']::text[],true,'{"seq":18,"concept":"M6-2-u1-C7","difficulty":1,"kind":"mc","stem":"⟨2/9⟩ ÷ ⟨3/5⟩을 곱셈으로 바르게 나타낸 것은 어느 것인가요?","explanation":["나누는 분수 ⟨3/5⟩만 분모와 분자를 바꿔요.","나누어지는 분수 ⟨2/9⟩는 그대로 두어야 양이 바뀌지 않아요.","그래서 ⟨2/9⟩ × ⟨5/3⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"expr"}},"options":[{"t":"⟨2/9⟩ × ⟨5/3⟩","correct":true},{"t":"⟨2/9⟩ × ⟨3/5⟩","mis":"M6-2-u1-X12"},{"t":"⟨9/2⟩ × ⟨5/3⟩","mis":"M6-2-u1-X12"},{"t":"⟨9/2⟩ × ⟨3/5⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#19','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C7',2,'mc','auto','⟨8/15⟩ ÷ ⟨4/5⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":19,"concept":"M6-2-u1-C7","difficulty":2,"kind":"mc","stem":"⟨8/15⟩ ÷ ⟨4/5⟩의 몫은 얼마인가요?","explanation":["나누는 분수의 분모와 분자를 바꾸어 곱해요 — ⟨8/15⟩ × ⟨5/4⟩.","분자끼리, 분모끼리 곱하면 ⟨40/60⟩ = ⟨2/3⟩예요.","그래서 몫은 ⟨2/3⟩예요."],"variant_rule":{"fd":{"ask":"mul","form":"ans"}},"options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨32/75⟩","mis":"M6-2-u1-X12"},{"t":"⟨1 1/2⟩","mis":"M6-2-u1-X05"},{"t":"⟨2 11/32⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#20','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C7',3,'error','auto','⟨2/9⟩ ÷ ⟨3/5⟩을 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?',ARRAY['M6-2-u1-X12']::text[],false,'{"seq":20,"concept":"M6-2-u1-C7","difficulty":3,"kind":"error","stem":"⟨2/9⟩ ÷ ⟨3/5⟩을 두고 친구들이 계산했어요. 바르게 계산한 친구는 누구인가요?","options":[{"t":"서윤 — 「⟨2/9⟩ × ⟨5/3⟩ = ⟨10/27⟩이야.」","correct":true,"mis_target":"M6-2-u1-X12"},{"t":"준서 — 「⟨2/9⟩ × ⟨3/5⟩ = ⟨2/15⟩야.」","mis":"M6-2-u1-X12"},{"t":"가은 — 「⟨9/2⟩ × ⟨5/3⟩ = ⟨45/6⟩야.」","mis":"M6-2-u1-X12"}],"explanation":["나누는 분수 ⟨3/5⟩만 뒤집어 ⟨2/9⟩ × ⟨5/3⟩예요.","분자끼리, 분모끼리 곱하면 ⟨10/27⟩이에요.","준서는 뒤집지 않았고 가은이는 두 분수를 다 뒤집었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#21','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',1,'mc','auto','⟨2 1/4⟩을 가분수로 바르게 고친 것은 어느 것인가요?',ARRAY['M6-2-u1-X14']::text[],true,'{"seq":21,"concept":"M6-2-u1-C8","difficulty":1,"kind":"mc","stem":"⟨2 1/4⟩을 가분수로 바르게 고친 것은 어느 것인가요?","explanation":["⟨2 1/4⟩은 2와 ⟨1/4⟩을 더한 수예요.","2는 ⟨8/4⟩이니 2 × 4 + 1 = 9가 분자예요.","가분수로 고치면 ⟨9/4⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"imp"}},"options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M6-2-u1-X14"},{"t":"⟨6/4⟩","mis":"M6-2-u1-X14"},{"t":"⟨8/4⟩","mis":"M6-2-u1-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#22','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',2,'mc','auto','⟨2 3/5⟩ ÷ ⟨2/3⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X13','M6-2-u1-X12','M6-2-u1-X05']::text[],true,'{"seq":22,"concept":"M6-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨2 3/5⟩ ÷ ⟨2/3⟩의 몫은 얼마인가요?","explanation":["대분수는 먼저 가분수로 고쳐요 — ⟨13/5⟩ ÷ ⟨2/3⟩.","⟨13/5⟩ × ⟨3/2⟩ = ⟨39/10⟩ = ⟨3 9/10⟩예요.","그래서 몫은 ⟨3 9/10⟩예요."],"variant_rule":{"fd":{"ask":"mixed","form":"ans"}},"options":[{"t":"⟨3 9/10⟩","correct":true},{"t":"⟨2 9/10⟩","mis":"M6-2-u1-X13"},{"t":"⟨1 11/15⟩","mis":"M6-2-u1-X12"},{"t":"⟨10/39⟩","mis":"M6-2-u1-X05"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#23','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C8',4,'mc','auto','어떤 수를 ⟨3 1/4⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨1 5/8⟩가 되었어요. 바르게 계산한 값은 얼마인가요?',ARRAY['M6-2-u1-X19']::text[],true,'{"seq":23,"concept":"M6-2-u1-C8","difficulty":4,"kind":"mc","stem":"어떤 수를 ⟨3 1/4⟩로 나누어야 할 것을 잘못하여 곱했더니 ⟨1 5/8⟩가 되었어요. 바르게 계산한 값은 얼마인가요?","explanation":["어떤 수를 □라 하면 □ × ⟨3 1/4⟩ = ⟨1 5/8⟩예요.","□ = ⟨1 5/8⟩ ÷ ⟨3 1/4⟩ = ⟨1 5/8⟩ × ⟨4/13⟩ = ⟨1/2⟩이에요.","바르게 계산하면 ⟨1/2⟩ ÷ ⟨3 1/4⟩ = ⟨1/2⟩ × ⟨4/13⟩ = ⟨2/13⟩예요."],"variant_rule":{"fd":{"ask":"back","form":"right"}},"options":[{"t":"⟨2/13⟩","correct":true},{"t":"⟨1/2⟩","mis":"M6-2-u1-X19"},{"t":"⟨5 9/32⟩","mis":"M6-2-u1-X19"},{"t":"⟨1 5/8⟩","mis":"M6-2-u1-X19"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#24','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C9',4,'sa','auto','한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 세로 ⟨82 1/2⟩ cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M6-2-u1-C9","difficulty":4,"kind":"sa","stem":"한 변이 ⟨7 1/2⟩ cm인 정사각형 타일을 벽의 세로 ⟨82 1/2⟩ cm에 빈틈없이 붙이려고 해요. 몇 개를 붙일 수 있나요? 숫자로 쓰세요.","explanation":["붙일 수 있는 개수는 ⟨82 1/2⟩ ÷ ⟨7 1/2⟩로 구해요.","⟨7 1/2⟩ = ⟨15/2⟩니 ⟨82 1/2⟩ ÷ ⟨15/2⟩ = ⟨165/2⟩ × ⟨2/15⟩ = 11이에요.","그래서 11개를 붙일 수 있어요."],"variant_rule":{"fd":{"ask":"tile","form":"row"}},"answer":["11","11개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_review_d#25','math',6,2,'u1','','g6_2_math_u1_review_d','unit_review','M6-2-u1-C9',4,'essay','teacher','한 변이 ⟨4 1/2⟩ cm인 정사각형 타일로 가로 45 cm, 세로 36 cm인 게시판을 가득 꾸미려고 해요. 타일 90개로 충분한지 계산 과정과 함께 판단해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한 변이 ⟨4 1/2⟩ cm인 정사각형 타일로 가로 45 cm, 세로 36 cm인 게시판을 가득 꾸미려고 해요. 타일 90개로 충분한지 계산 과정과 함께 판단해 보세요.","answer_guide":{"answer":"예: 가로에 10개, 세로에 8개가 들어가므로 필요한 타일은 10 × 8 = 80개이다. 90개로 충분하다.","scoring_points":["가로 10개를 구했는가","세로 8개를 구했는가","10 × 8 = 80개로 충분하다고 판단했는가"]},"explanation":["가로·세로에 들어가는 개수는 길이 ÷ 타일 한 변이에요.","필요한 타일은 10 × 8 = 80개예요.","90개면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
